select ac_cargar_unidad($ac${"slug":"residuos-1","rama":"residuos","orden":1,"nivel":1,"titulo_es":"Qué pasa con lo que tirás","bajada_es":"La bolsa sale de tu casa, pero no desaparece. De qué está hecha, adónde va, qué le pasa y quién la recupera.","objetivos_es":["Definir qué es un residuo y cuánto genera una persona","Describir la composición típica de la basura de una casa","Seguir el recorrido de un residuo desde la casa hasta su destino final","Diferenciar un relleno sanitario de un basural a cielo abierto","Reconocer el trabajo de los recicladores urbanos en la gestión de residuos"],"repasa":["tronco-1","tronco-2"],"requiere_tronco":1,"fuentes":["ley-25916-residuos","ceamse","ley-1854-basura-cero","faccyr","epa"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-1.s1","orden":1,"tipo":"leccion","titulo_es":"La bolsa que sale de casa","bajada_es":"Qué es un residuo, cuánto genera cada persona y por qué \"tirar\" no es hacer desaparecer.","minutos":12,"pasos":[{"slug":"residuos-1.s1.p1","orden":1,"grupo":"residuos-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es un residuo","cuerpo":["Un residuo es algo que su dueño descarta porque ya no le sirve. Los residuos sólidos urbanos (RSU) son los que se generan en casas, comercios, oficinas y la vía pública: restos de comida, envases, papeles, textiles, pequeños objetos rotos.","Hay otros residuos que tienen reglas propias, como los peligrosos (pilas, químicos, algunos aparatos electrónicos), los patogénicos (de hospitales) y los industriales."]},"solucion":{}},{"slug":"residuos-1.s1.p2","orden":2,"grupo":"residuos-1.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un residuo sólido urbano o de otro tipo?","grupos":[{"id":"g1","nombre":"Residuo sólido urbano"},{"id":"g2","nombre":"Otro tipo (con reglas propias)"}],"items":[{"id":"i1","texto":"Cáscaras de papa"},{"id":"i2","texto":"Jeringas de un hospital"},{"id":"i3","texto":"Una caja de cartón"},{"id":"i4","texto":"Restos de solventes de una fábrica"},{"id":"i5","texto":"Una botella de plástico"},{"id":"i6","texto":"Pilas usadas"},{"id":"i7","texto":"Una remera rota"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1"},"explicacion":"Los RSU son los de todos los días. Los otros necesitan una gestión especial porque pueden ser peligrosos."}},{"slug":"residuos-1.s1.p3","orden":3,"grupo":"residuos-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto tira una persona","cuerpo":["En Argentina, cada persona genera en promedio alrededor de 1 kilo de residuos por día, y bastante más en las grandes ciudades. Parece poco hasta que se multiplica: una familia de 4 genera unos 120 kilos por mes; una ciudad de un millón de habitantes, unas mil toneladas por día."],"destacado":{"valor":"≈ 1 kg","texto":"de residuos genera por día, en promedio, cada persona en Argentina."}},"solucion":{}},{"slug":"residuos-1.s1.p4","orden":4,"grupo":"residuos-1.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa viven 4 personas que generan 1 kg de residuos por día cada una. ¿Cuántos kilos generan en 30 días?","unidad":"kg","decimales":1},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"4 × 1 × 30 = 120 kg por mes. Lo que parece una bolsita por día es más que el peso de una persona por mes."}},{"slug":"residuos-1.s1.p4.v2","orden":4,"grupo":"residuos-1.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa viven 3 personas que generan 1,2 kg de residuos por día cada una. ¿Cuántos kilos generan en 30 días?","unidad":"kg","decimales":1},"solucion":{"valor":108,"tolerancia":2.16,"explicacion":"3 × 1,2 × 30 = 108 kg por mes. Lo que parece una bolsita por día es más que el peso de una persona por mes."}},{"slug":"residuos-1.s1.p4.v3","orden":4,"grupo":"residuos-1.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa viven 5 personas que generan 0,9 kg de residuos por día cada una. ¿Cuántos kilos generan en 30 días?","unidad":"kg","decimales":1},"solucion":{"valor":135,"tolerancia":2.7,"explicacion":"5 × 0,9 × 30 = 135 kg por mes. Lo que parece una bolsita por día es más que el peso de una persona por mes."}},{"slug":"residuos-1.s1.p5","orden":5,"grupo":"residuos-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 500.000 habitantes que generan 1 kg por día cada uno. ¿Cuántas toneladas genera por día?","unidad":"toneladas","decimales":0},"solucion":{"valor":500,"tolerancia":10,"explicacion":"500.000 kg ÷ 1.000 = 500 toneladas por día. Todos los días hay que recogerlas, transportarlas y hacer algo con ellas."}},{"slug":"residuos-1.s1.p5.v2","orden":5,"grupo":"residuos-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 1.000.000 habitantes que generan 1 kg por día cada uno. ¿Cuántas toneladas genera por día?","unidad":"toneladas","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"1.000.000 kg ÷ 1.000 = 1.000 toneladas por día. Todos los días hay que recogerlas, transportarlas y hacer algo con ellas."}},{"slug":"residuos-1.s1.p5.v3","orden":5,"grupo":"residuos-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 3.000.000 habitantes que generan 1 kg por día cada uno. ¿Cuántas toneladas genera por día?","unidad":"toneladas","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"3.000.000 kg ÷ 1.000 = 3.000 toneladas por día. Todos los días hay que recogerlas, transportarlas y hacer algo con ellas."}},{"slug":"residuos-1.s1.p6","orden":6,"grupo":"residuos-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tirar es cambiar de lugar","cuerpo":["En el tronco viste que la materia no desaparece. Con la basura se ve claro: cuando la bolsa sale de casa, alguien la recoge, la transporta y la deja en otro lugar, donde se queda, se descompone o se recupera.","\"Afuera\" no existe. Cada residuo termina en algún lugar concreto, con consecuencias concretas para alguien."]},"solucion":{}},{"slug":"residuos-1.s1.p7","orden":7,"grupo":"residuos-1.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuando el camión recolector se lleva la bolsa, el residuo deja de existir.","razones":[{"id":"r1","texto":"Porque la materia no desaparece: solo se traslada"},{"id":"r2","texto":"Porque el camión la destruye al compactarla"},{"id":"r3","texto":"Porque la basura se evapora en el relleno"}]},"solucion":{"valor":false,"explicacion":"Solo cambia de lugar. Termina en un relleno, un basural, una planta de reciclaje o, a veces, en un arroyo o un campo.","clave":["r1"]}},{"slug":"residuos-1.s1.p8","orden":8,"grupo":"residuos-1.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido típico de una bolsa de basura en una ciudad.","items":[{"id":"i1","texto":"Se genera en la casa y se saca a la vereda"},{"id":"i2","texto":"El camión la recoge y la compacta"},{"id":"i3","texto":"Pasa por una estación de transferencia"},{"id":"i4","texto":"Llega a un relleno sanitario"},{"id":"i5","texto":"Se devuelve a la casa al mes siguiente"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuatro etapas típicas. La ley nacional de residuos domiciliarios las describe como gestión integral: de la generación a la disposición final."}},{"slug":"residuos-1.s1.p9","orden":9,"grupo":"residuos-1.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las etapas de la gestión","cuerpo":["La Ley 25.916, de presupuestos mínimos para la gestión de residuos domiciliarios, describe las etapas de la gestión integral: generación, disposición inicial (cómo se saca a la calle), recolección y transporte, transferencia, tratamiento y disposición final.","Cada municipio organiza esas etapas. Por eso las reglas de cómo separar o qué día sacar la basura cambian de una ciudad a otra."]},"solucion":{}},{"slug":"residuos-1.s1.p10","orden":10,"grupo":"residuos-1.s1.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas de la gestión de residuos según la ley.","items":[{"id":"i1","texto":"Generación"},{"id":"i2","texto":"Disposición inicial"},{"id":"i3","texto":"Recolección y transporte"},{"id":"i4","texto":"Transferencia"},{"id":"i5","texto":"Tratamiento"},{"id":"i6","texto":"Disposición final"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Del tacho de la cocina al destino final. En cada etapa se puede reducir, separar o recuperar."}},{"slug":"residuos-1.s1.p11","orden":11,"grupo":"residuos-1.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las reglas para separar la basura cambian de una ciudad a otra?","opciones":[{"id":"o1","texto":"Porque cada municipio organiza su propia gestión"},{"id":"o2","texto":"Porque los residuos son distintos en cada provincia"},{"id":"o3","texto":"Porque la ley nacional prohíbe separar"},{"id":"o4","texto":"Porque los camiones de cada ciudad son de otra marca"}]},"solucion":{"clave":["o1"],"explicacion":"La ley nacional fija un piso común; la recolección y el tratamiento son responsabilidad local.","por_opcion":{"o3":"La ley nacional fija mínimos; los municipios organizan los detalles."}}},{"slug":"residuos-1.s1.p12","orden":12,"grupo":"residuos-1.s1.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pasa con la basura de una ciudad cada día? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Hay que recogerla"},{"id":"o2","texto":"Hay que transportarla"},{"id":"o3","texto":"Hay que decidir dónde termina"},{"id":"o4","texto":"Cuesta plata a todos los vecinos"},{"id":"o5","texto":"Se descompone sola en la vereda en unas horas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Recolectar y disponer residuos es uno de los mayores gastos de muchos municipios."}},{"slug":"residuos-1.s1.p13","orden":13,"grupo":"residuos-1.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cada persona genera alrededor de {{0}} kilo de residuos por día; al tirarlos, la materia no {{1}}: cambia de {{2}}.","banco":[{"id":"w1","texto":"1"},{"id":"w2","texto":"desaparece"},{"id":"w3","texto":"lugar"},{"id":"w4","texto":"10"},{"id":"w5","texto":"aumenta"},{"id":"w6","texto":"forma"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea del tronco aplicada a la bolsa de basura."}},{"slug":"residuos-1.s1.p14","orden":14,"grupo":"residuos-1.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Una persona genera cerca de un kilo de basura por día."},{"id":"s2","texto":"Una vez que el camión pasa, ya no es problema de nadie."},{"id":"s3","texto":"La gestión de residuos la organiza cada municipio."},{"id":"s4","texto":"Una familia no genera más de 10 kilos de basura por mes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los números chicos por día se vuelven grandes por mes y por ciudad.","por_opcion":{"s2":"Termina en algún lugar, y el costo lo pagan todos: plata, espacio y contaminación.","s4":"Con 1 kg por persona por día, una familia de 4 genera unos 120 kg por mes."}}}]},{"slug":"residuos-1.s2","orden":2,"tipo":"leccion","titulo_es":"De qué está hecha la basura","bajada_es":"Orgánicos, papel, plásticos, vidrio y metales: la composición de la bolsa y por qué importa conocerla.","minutos":11,"pasos":[{"slug":"residuos-1.s2.p1","orden":1,"grupo":"residuos-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Abrir la bolsa","cuerpo":["Los estudios de composición de residuos abren y pesan muestras de bolsas reales para saber qué hay adentro. En las ciudades argentinas, lo que más pesa son los residuos orgánicos: restos de comida y de jardín, que suelen ser alrededor de la mitad.","Después vienen el papel y el cartón, los plásticos, el vidrio, los metales, los textiles y otros materiales como pañales, madera y escombros."],"datos":{"tipo":"barras","titulo":"Composición de los residuos de una ciudad argentina (ejemplo aproximado)","unidad":"% del peso","filas":[{"etiqueta":"Orgánicos","valor":45},{"etiqueta":"Plásticos","valor":15},{"etiqueta":"Papel y cartón","valor":14},{"etiqueta":"Pañales y sanitarios","valor":7},{"etiqueta":"Vidrio","valor":4},{"etiqueta":"Textiles","valor":4},{"etiqueta":"Metales","valor":2},{"etiqueta":"Otros","valor":9}],"nota":"Valores ilustrativos redondeados; varían según la ciudad, el barrio y la época del año."}},"solucion":{}},{"slug":"residuos-1.s2.p2","orden":2,"grupo":"residuos-1.s2.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese ejemplo, ordená los materiales por su peso en la basura, de más a menos.","items":[{"id":"i1","texto":"Orgánicos"},{"id":"i2","texto":"Plásticos"},{"id":"i3","texto":"Papel y cartón"},{"id":"i4","texto":"Vidrio"},{"id":"i5","texto":"Metales"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los orgánicos son casi la mitad del peso. Cualquier plan serio de residuos tiene que empezar por ahí.","valores":{"i1":"≈ 45 %","i2":"≈ 15 %","i3":"≈ 14 %","i4":"≈ 4 %","i5":"≈ 2 %"}}},{"slug":"residuos-1.s2.p3","orden":3,"grupo":"residuos-1.s2.p3","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del peso de la basura de una casa son restos orgánicos.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":45,"banda":"lineal","explicacion":"Alrededor de la mitad. Por eso el compostaje, que vas a ver en esta rama, puede reducir tanto la basura."}},{"slug":"residuos-1.s2.p4","orden":4,"grupo":"residuos-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Peso contra volumen","cuerpo":["El peso y el volumen cuentan historias distintas. Los orgánicos pesan mucho porque tienen agua. Los plásticos y el cartón pesan poco pero ocupan mucho lugar: una bolsa llena de envases plásticos puede pesar menos de medio kilo.","Por eso un tacho puede llenarse rápido con envases sin que la basura pese mucho, y el volumen es lo que llena camiones y rellenos."]},"solucion":{}},{"slug":"residuos-1.s2.p5","orden":5,"grupo":"residuos-1.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los plásticos pesan poco, casi no ocupan lugar en la basura.","razones":[{"id":"r1","texto":"Porque son livianos pero voluminosos"},{"id":"r2","texto":"Porque los plásticos se compactan hasta desaparecer"},{"id":"r3","texto":"Porque el peso y el volumen son siempre proporcionales"}]},"solucion":{"valor":false,"explicacion":"Pesan poco pero ocupan mucho volumen. Son una parte chica del peso y una parte grande del espacio.","clave":["r1"]}},{"slug":"residuos-1.s2.p6","orden":6,"grupo":"residuos-1.s2.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué es más importante en este material: su peso o su volumen?","grupos":[{"id":"g1","nombre":"Pesa mucho (tiene agua)"},{"id":"g2","nombre":"Ocupa mucho (pesa poco)"}],"items":[{"id":"i1","texto":"Restos de verdura"},{"id":"i2","texto":"Botellas plásticas"},{"id":"i3","texto":"Yerba usada"},{"id":"i4","texto":"Cajas de cartón sin aplastar"},{"id":"i5","texto":"Pasto cortado"},{"id":"i6","texto":"Bandejas de telgopor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los orgánicos dominan el peso; los envases dominan el volumen. Los dos problemas tienen soluciones distintas."}},{"slug":"residuos-1.s2.p7","orden":7,"grupo":"residuos-1.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué conocer la composición","cuerpo":["Saber qué hay en la bolsa permite decidir qué hacer con cada parte: los orgánicos pueden compostarse, el papel, el cartón, muchos plásticos, el vidrio y los metales pueden reciclarse, y otros residuos necesitan tratamientos especiales.","Si todo va mezclado, los orgánicos ensucian los materiales reciclables y se pierde casi todo. Separar en origen, en la casa, es lo que hace posible el resto."]},"solucion":{}},{"slug":"residuos-1.s2.p8","orden":8,"grupo":"residuos-1.s2.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada material con lo que se puede hacer con él.","izquierda":[{"id":"a1","texto":"Restos de comida"},{"id":"a2","texto":"Cartón limpio"},{"id":"a3","texto":"Frascos de vidrio"},{"id":"a4","texto":"Latas de aluminio"}],"derecha":[{"id":"b1","texto":"Compostarlos"},{"id":"b2","texto":"Reciclarlo como papel"},{"id":"b3","texto":"Fundirlos para hacer vidrio nuevo"},{"id":"b4","texto":"Fundirlas para hacer aluminio nuevo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Casi todo lo que hay en la bolsa tiene un destino mejor que el relleno, si llega limpio y separado."}},{"slug":"residuos-1.s2.p9","orden":9,"grupo":"residuos-1.s2.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué mezclar orgánicos con reciclables arruina el reciclaje.","items":[{"id":"i1","texto":"Los restos de comida van en la misma bolsa que el cartón"},{"id":"i2","texto":"El cartón se moja y se engrasa"},{"id":"i3","texto":"Las plantas de reciclaje no pueden usarlo"},{"id":"i4","texto":"Ese cartón termina en el relleno"},{"id":"i5","texto":"El cartón engrasado se recicla mejor"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Separar en origen es la condición para que todo lo demás funcione."}},{"slug":"residuos-1.s2.p10","orden":10,"grupo":"residuos-1.s2.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 120 kg de residuos por mes y el 45 % son orgánicos. ¿Cuántos kilos de orgánicos genera por mes?","unidad":"kg","decimales":1},"solucion":{"valor":54,"tolerancia":1.08,"explicacion":"120 × 45 ÷ 100 = 54 kg de orgánicos por mes, que podrían compostarse en vez de viajar al relleno."}},{"slug":"residuos-1.s2.p10.v2","orden":10,"grupo":"residuos-1.s2.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 90 kg de residuos por mes y el 50 % son orgánicos. ¿Cuántos kilos de orgánicos genera por mes?","unidad":"kg","decimales":1},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"90 × 50 ÷ 100 = 45 kg de orgánicos por mes, que podrían compostarse en vez de viajar al relleno."}},{"slug":"residuos-1.s2.p10.v3","orden":10,"grupo":"residuos-1.s2.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 150 kg de residuos por mes y el 40 % son orgánicos. ¿Cuántos kilos de orgánicos genera por mes?","unidad":"kg","decimales":1},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"150 × 40 ÷ 100 = 60 kg de orgánicos por mes, que podrían compostarse en vez de viajar al relleno."}},{"slug":"residuos-1.s2.p11","orden":11,"grupo":"residuos-1.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos residuos son orgánicos? Marcá todos.","opciones":[{"id":"o1","texto":"Cáscaras de huevo"},{"id":"o2","texto":"Yerba y saquitos de té"},{"id":"o3","texto":"Restos de poda"},{"id":"o4","texto":"Cáscaras de frutas"},{"id":"o5","texto":"Una bandeja de telgopor"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Orgánico es lo que viene de un ser vivo y se descompone. El telgopor es plástico."}},{"slug":"residuos-1.s2.p12","orden":12,"grupo":"residuos-1.s2.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una ciudad quiere reducir a la mitad lo que manda al relleno. ¿Qué parte de la basura conviene atacar primero?","opciones":[{"id":"o1","texto":"Los orgánicos, que son casi la mitad del peso"},{"id":"o2","texto":"Los metales, que son muy valiosos"},{"id":"o3","texto":"El vidrio, porque es pesado"},{"id":"o4","texto":"Los textiles, porque son difíciles de tratar"}]},"solucion":{"clave":["o1"],"explicacion":"Elegir por impacto: los orgánicos son la fracción más grande y pueden tratarse cerca, con compostaje.","por_opcion":{"o3":"El vidrio pesa, pero es una parte chica del total, alrededor del 4 %."}}},{"slug":"residuos-1.s2.p13","orden":13,"grupo":"residuos-1.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta conclusión de un estudio escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los orgánicos fueron la parte más pesada de la bolsa."},{"id":"s2","texto":"Como los plásticos pesaron poco, no son un problema."},{"id":"s3","texto":"El cartón mojado con restos de comida ya no sirve para reciclar."},{"id":"s4","texto":"Separar no sirve porque todo termina mezclado igual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Peso y volumen, y la importancia de separar en origen.","por_opcion":{"s2":"Pesan poco pero ocupan mucho volumen y duran mucho tiempo.","s4":"Donde hay recolección diferenciada o recicladores, separar permite recuperar materiales."}}},{"slug":"residuos-1.s2.p14","orden":14,"grupo":"residuos-1.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los residuos {{0}} son casi la mitad del peso de la basura; los plásticos pesan poco pero ocupan mucho {{1}}.","banco":[{"id":"w1","texto":"orgánicos"},{"id":"w2","texto":"volumen"},{"id":"w3","texto":"metales"},{"id":"w4","texto":"peso"},{"id":"w5","texto":"agua"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos datos que cambian cómo se piensa un plan de residuos."}}]},{"slug":"residuos-1.s3","orden":3,"tipo":"leccion","titulo_es":"Relleno sanitario o basural","bajada_es":"Dos destinos muy distintos para la misma basura: uno controlado y otro que contamina.","minutos":12,"pasos":[{"slug":"residuos-1.s3.p1","orden":1,"grupo":"residuos-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El basural a cielo abierto","cuerpo":["Un basural a cielo abierto es un lugar donde la basura se tira sin ningún control: sin impermeabilizar el suelo, sin cubrirla y muchas veces quemándola. En Argentina hay miles de basurales de este tipo, sobre todo en municipios chicos y medianos.","Contaminan el suelo y las napas con los líquidos que se forman, el aire con el humo de las quemas, atraen roedores e insectos que transmiten enfermedades y ponen en riesgo a quienes viven o trabajan cerca."]},"solucion":{}},{"slug":"residuos-1.s3.p2","orden":2,"grupo":"residuos-1.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas causa un basural a cielo abierto? Marcá todos.","opciones":[{"id":"o1","texto":"Contamina el suelo y las napas"},{"id":"o2","texto":"El humo de las quemas contamina el aire"},{"id":"o3","texto":"Atrae ratas, moscas y mosquitos"},{"id":"o4","texto":"Pone en riesgo la salud de quienes viven cerca"},{"id":"o5","texto":"Produce agua potable para el barrio"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un basural afecta el suelo, el agua, el aire y la salud al mismo tiempo."}},{"slug":"residuos-1.s3.p3","orden":3,"grupo":"residuos-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El relleno sanitario","cuerpo":["Un relleno sanitario es una obra de ingeniería. El suelo se impermeabiliza con arcillas y membranas para que los líquidos no lleguen a las napas. La basura se compacta en capas y se cubre con tierra todos los días. Los líquidos se recogen y se tratan, y los gases se captan con caños.","En el área metropolitana de Buenos Aires, la empresa estatal CEAMSE opera los rellenos que reciben miles de toneladas por día. Un relleno controla la contaminación, pero ocupa tierra, se llena y sigue emitiendo gases durante décadas."]},"solucion":{}},{"slug":"residuos-1.s3.p4","orden":4,"grupo":"residuos-1.s3.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es característica de un relleno sanitario o de un basural a cielo abierto?","grupos":[{"id":"g1","nombre":"Relleno sanitario"},{"id":"g2","nombre":"Basural a cielo abierto"}],"items":[{"id":"i1","texto":"Membranas que impermeabilizan el suelo"},{"id":"i2","texto":"Quema de la basura"},{"id":"i3","texto":"Cobertura diaria con tierra"},{"id":"i4","texto":"Líquidos que se infiltran en el suelo"},{"id":"i5","texto":"Captación de gases con caños"},{"id":"i6","texto":"Basura expuesta a animales y lluvia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La diferencia es el control: un relleno está diseñado para contener; un basural no contiene nada."}},{"slug":"residuos-1.s3.p5","orden":5,"grupo":"residuos-1.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lixiviados: el jugo de la basura","cuerpo":["Cuando llueve sobre la basura, el agua la atraviesa y arrastra sustancias: restos orgánicos, metales, químicos. Ese líquido se llama lixiviado, y es muy contaminante.","En un relleno, los lixiviados se juntan en el fondo impermeable y se bombean a una planta de tratamiento. En un basural, se infiltran directamente hacia las napas o escurren hacia arroyos."]},"solucion":{}},{"slug":"residuos-1.s3.p6","orden":6,"grupo":"residuos-1.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un basural puede contaminar el agua de un pozo.","items":[{"id":"i1","texto":"Llueve sobre el basural"},{"id":"i2","texto":"El agua atraviesa la basura y arrastra sustancias"},{"id":"i3","texto":"Se forma un lixiviado muy contaminante"},{"id":"i4","texto":"El lixiviado se infiltra en el suelo sin barrera"},{"id":"i5","texto":"Llega a la napa de la que bebe un pozo cercano"},{"id":"i6","texto":"El lixiviado se purifica solo al tocar el suelo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es la conexión entre residuos y agua que viste en la rama de Agua: lo que se tira en tierra puede terminar en el vaso."}},{"slug":"residuos-1.s3.p7","orden":7,"grupo":"residuos-1.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un relleno sanitario no contamina nada, así que da igual cuánta basura se mande.","razones":[{"id":"r1","texto":"Porque igual ocupa tierra, emite gases y se llena"},{"id":"r2","texto":"Porque los rellenos son infinitos"},{"id":"r3","texto":"Porque la basura desaparece en el relleno"}]},"solucion":{"valor":false,"explicacion":"Controla mucho mejor que un basural, pero ocupa tierra, se llena, emite metano durante décadas y cuesta mucho. Mandar menos siempre es mejor.","clave":["r1"]}},{"slug":"residuos-1.s3.p8","orden":8,"grupo":"residuos-1.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Metano: el gas de la basura","cuerpo":["En un relleno, la basura orgánica queda enterrada sin oxígeno. Ahí la descomponen microbios que producen metano, un gas de efecto invernadero que, como viste en el tronco, calienta muchas veces más que el CO₂ en un período de 100 años.","Los rellenos y basurales están entre las mayores fuentes de metano causadas por las personas. Captar ese gas y quemarlo o usarlo para generar electricidad reduce mucho su efecto."]},"solucion":{}},{"slug":"residuos-1.s3.p9","orden":9,"grupo":"residuos-1.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los restos de comida enterrados en un relleno producen metano?","opciones":[{"id":"o1","texto":"Porque se descomponen sin oxígeno"},{"id":"o2","texto":"Porque la tierra que los cubre tiene metano"},{"id":"o3","texto":"Porque los camiones los rocían con gas"},{"id":"o4","texto":"Porque los rellenos se construyen sobre pozos de gas"}]},"solucion":{"clave":["o1"],"explicacion":"Sin oxígeno, los microbios que descomponen producen metano. Con oxígeno, como en una compostera bien hecha, producen sobre todo CO₂ y mucho menos metano.","por_opcion":{"o3":"El metano lo producen microbios al descomponer lo orgánico sin aire."}}},{"slug":"residuos-1.s3.p10","orden":10,"grupo":"residuos-1.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno emite 2 toneladas de metano. Si el metano calienta unas 28 veces más que el CO₂ en 100 años, ¿cuántas toneladas de CO₂ equivalente son?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"2 × 28 = 56 t de CO₂ equivalente. Es la cuenta del tronco: gases distintos, un mismo número para comparar."}},{"slug":"residuos-1.s3.p10.v2","orden":10,"grupo":"residuos-1.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno emite 5 toneladas de metano. Si el metano calienta unas 28 veces más que el CO₂ en 100 años, ¿cuántas toneladas de CO₂ equivalente son?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"5 × 28 = 140 t de CO₂ equivalente. Es la cuenta del tronco: gases distintos, un mismo número para comparar."}},{"slug":"residuos-1.s3.p10.v3","orden":10,"grupo":"residuos-1.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno emite 10 toneladas de metano. Si el metano calienta unas 28 veces más que el CO₂ en 100 años, ¿cuántas toneladas de CO₂ equivalente son?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":280,"tolerancia":5.6000000000000005,"explicacion":"10 × 28 = 280 t de CO₂ equivalente. Es la cuenta del tronco: gases distintos, un mismo número para comparar."}},{"slug":"residuos-1.s3.p11","orden":11,"grupo":"residuos-1.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su definición.","izquierda":[{"id":"a1","texto":"Lixiviado"},{"id":"a2","texto":"Relleno sanitario"},{"id":"a3","texto":"Basural a cielo abierto"},{"id":"a4","texto":"Biogás"}],"derecha":[{"id":"b1","texto":"Líquido contaminante que se forma en la basura"},{"id":"b2","texto":"Obra que aísla y controla los residuos"},{"id":"b3","texto":"Lugar de descarte sin controles"},{"id":"b4","texto":"Gas con metano que sale de lo orgánico enterrado"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palabras que aparecen en cualquier discusión sobre el destino de la basura."}},{"slug":"residuos-1.s3.p12","orden":12,"grupo":"residuos-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta noticia local y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El municipio cerrará su basural y llevará los residuos a un relleno sanitario."},{"id":"s2","texto":"Así la basura dejará de generar metano."},{"id":"s3","texto":"El relleno tendrá membranas y tratamiento de lixiviados."},{"id":"s4","texto":"Por eso ya no hace falta reducir ni separar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Pasar de basural a relleno es un gran avance, pero no reemplaza reducir y recuperar.","por_opcion":{"s2":"El relleno también genera metano; puede captarse, pero no desaparece.","s4":"El relleno se llena y cuesta: reducir y separar sigue siendo clave."}}},{"slug":"residuos-1.s3.p13","orden":13,"grupo":"residuos-1.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos destinos de un residuo orgánico de peor a mejor para el ambiente.","items":[{"id":"i1","texto":"Quemado en un basural a cielo abierto"},{"id":"i2","texto":"Enterrado en un relleno sin captación de gas"},{"id":"i3","texto":"Enterrado en un relleno con captación de gas"},{"id":"i4","texto":"Compostado"}],"extremos":["Peor","Mejor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada paso mejora el control. El compostaje, que vas a ver en esta rama, evita el problema en el origen.","valores":{"i1":"humo, lixiviados y metano","i2":"metano a la atmósfera","i3":"metano captado en parte","i4":"vuelve al suelo como abono"}}},{"slug":"residuos-1.s3.p14","orden":14,"grupo":"residuos-1.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un relleno, lo orgánico se descompone sin {{0}} y produce {{1}}; el líquido que atraviesa la basura se llama {{2}}.","banco":[{"id":"w1","texto":"oxígeno"},{"id":"w2","texto":"metano"},{"id":"w3","texto":"lixiviado"},{"id":"w4","texto":"luz"},{"id":"w5","texto":"vapor"},{"id":"w6","texto":"compost"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas que explican por qué la basura orgánica es un problema climático."}}]},{"slug":"residuos-1.s4","orden":4,"tipo":"leccion","titulo_es":"La basura también tiene costo","bajada_es":"Cuánto cuesta recoger y enterrar, quién lo paga y por qué cada kilo que no se tira ahorra en toda la cadena.","minutos":11,"pasos":[{"slug":"residuos-1.s4.p1","orden":1,"grupo":"residuos-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El costo de la cadena","cuerpo":["Recoger, transportar y disponer residuos cuesta mucho: camiones, combustible, trabajadores, estaciones de transferencia y rellenos. En muchos municipios es uno de los gastos más grandes del presupuesto, y lo pagan todos los vecinos con sus tasas.","El costo suele crecer con la cantidad: más toneladas son más viajes de camión y más espacio en el relleno. Por eso cada kilo que no se genera, o que se recupera, ahorra plata a toda la ciudad."]},"solucion":{}},{"slug":"residuos-1.s4.p2","orden":2,"grupo":"residuos-1.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad gestiona 1.000 toneladas de residuos por día y cada tonelada le cuesta $50.000 entre recolección y disposición. ¿Cuánto gasta por día?","unidad":"$","decimales":0},"solucion":{"valor":50000000,"tolerancia":1000000,"explicacion":"1.000 × $50.000 = $50.000.000 por día. Por año, 365 veces eso."}},{"slug":"residuos-1.s4.p2.v2","orden":2,"grupo":"residuos-1.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad gestiona 500 toneladas de residuos por día y cada tonelada le cuesta $60.000 entre recolección y disposición. ¿Cuánto gasta por día?","unidad":"$","decimales":0},"solucion":{"valor":30000000,"tolerancia":600000,"explicacion":"500 × $60.000 = $30.000.000 por día. Por año, 365 veces eso."}},{"slug":"residuos-1.s4.p2.v3","orden":2,"grupo":"residuos-1.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad gestiona 3.000 toneladas de residuos por día y cada tonelada le cuesta $45.000 entre recolección y disposición. ¿Cuánto gasta por día?","unidad":"$","decimales":0},"solucion":{"valor":135000000,"tolerancia":2700000,"explicacion":"3.000 × $45.000 = $135.000.000 por día. Por año, 365 veces eso."}},{"slug":"residuos-1.s4.p3","orden":3,"grupo":"residuos-1.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad de 1.000 toneladas por día reduce un 10 % lo que manda al relleno, ¿cuántas toneladas por día deja de enviar?","unidad":"toneladas","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"1.000 × 10 ÷ 100 = 100 toneladas por día menos: menos viajes de camión, menos espacio de relleno y menos gasto."}},{"slug":"residuos-1.s4.p3.v2","orden":3,"grupo":"residuos-1.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad de 500 toneladas por día reduce un 20 % lo que manda al relleno, ¿cuántas toneladas por día deja de enviar?","unidad":"toneladas","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"500 × 20 ÷ 100 = 100 toneladas por día menos: menos viajes de camión, menos espacio de relleno y menos gasto."}},{"slug":"residuos-1.s4.p3.v3","orden":3,"grupo":"residuos-1.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad de 3.000 toneladas por día reduce un 15 % lo que manda al relleno, ¿cuántas toneladas por día deja de enviar?","unidad":"toneladas","decimales":0},"solucion":{"valor":450,"tolerancia":9,"explicacion":"3.000 × 15 ÷ 100 = 450 toneladas por día menos: menos viajes de camión, menos espacio de relleno y menos gasto."}},{"slug":"residuos-1.s4.p4","orden":4,"grupo":"residuos-1.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los costos que no aparecen en la factura","cuerpo":["Hay costos que no se pagan en pesos: el metano que calienta el planeta, la contaminación del agua y el suelo cerca de basurales, la salud de quienes viven al lado, la tierra ocupada por rellenos durante décadas. Se llaman costos externos, porque no los paga quien genera el residuo."]},"solucion":{}},{"slug":"residuos-1.s4.p5","orden":5,"grupo":"residuos-1.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un costo que se paga en la tasa municipal o un costo externo?","grupos":[{"id":"g1","nombre":"Se paga en la tasa"},{"id":"g2","nombre":"Costo externo"}],"items":[{"id":"i1","texto":"El combustible de los camiones"},{"id":"i2","texto":"El metano que calienta el planeta"},{"id":"i3","texto":"Los sueldos de los recolectores"},{"id":"i4","texto":"La napa contaminada cerca de un basural"},{"id":"i5","texto":"La operación del relleno"},{"id":"i6","texto":"Las enfermedades de quienes viven al lado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los costos externos existen aunque nadie los facture. Reducir residuos baja los dos tipos."}},{"slug":"residuos-1.s4.p6","orden":6,"grupo":"residuos-1.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la tasa de basura es baja, tirar mucho no tiene costo.","razones":[{"id":"r1","texto":"Porque hay costos externos que la tasa no refleja"},{"id":"r2","texto":"Porque la basura se gestiona gratis"},{"id":"r3","texto":"Porque los rellenos no ocupan tierra"}]},"solucion":{"valor":false,"explicacion":"La tasa no refleja los costos externos: contaminación, metano y salud. Y la cuenta del municipio la terminan pagando todos.","clave":["r1"]}},{"slug":"residuos-1.s4.p7","orden":7,"grupo":"residuos-1.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién genera, quién paga","cuerpo":["Hoy, la mayoría de los costos de los envases los paga el municipio, no quien los fabrica o vende. La responsabilidad extendida del productor (REP) es una idea que propone que las empresas que ponen envases en el mercado se hagan cargo de financiar su recuperación.","Varios países la aplican y en Argentina hay leyes provinciales y proyectos nacionales. La idea es que el costo del residuo entre en el precio del producto, y que las empresas tengan un incentivo para diseñar envases más fáciles de reciclar o reutilizar."]},"solucion":{}},{"slug":"residuos-1.s4.p8","orden":8,"grupo":"residuos-1.s4.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué busca la responsabilidad extendida del productor?","opciones":[{"id":"o1","texto":"Que quien pone envases en el mercado financie su recuperación"},{"id":"o2","texto":"Que los vecinos paguen más tasa municipal por la basura"},{"id":"o3","texto":"Que se prohíban todos los envases de plástico"},{"id":"o4","texto":"Que los municipios dejen de recoger los residuos de envases"}]},"solucion":{"clave":["o1"],"explicacion":"Cuando el costo del residuo recae en quien lo diseña, aparece el incentivo para diseñarlo mejor.","por_opcion":{"o3":"No prohíbe: busca que el costo de gestión lo asuma el productor."}}},{"slug":"residuos-1.s4.p9","orden":9,"grupo":"residuos-1.s4.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la responsabilidad extendida del productor puede cambiar un envase.","items":[{"id":"i1","texto":"La empresa paga por cada tonelada de envases que vende"},{"id":"i2","texto":"Los envases difíciles de reciclar le cuestan más"},{"id":"i3","texto":"La empresa rediseña el envase para que sea reciclable o más liviano"},{"id":"i4","texto":"Llegan menos envases problemáticos al relleno"},{"id":"i5","texto":"Los vecinos pagan el rediseño con más tasa"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un incentivo bien puesto cambia decisiones de diseño que ningún vecino puede cambiar solo. Es lo tuyo y lo de todos del tronco."}},{"slug":"residuos-1.s4.p10","orden":10,"grupo":"residuos-1.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos son costos reales de tirar más basura? Marcá todos.","opciones":[{"id":"o1","texto":"Más viajes de camión y combustible"},{"id":"o2","texto":"Rellenos que se llenan antes"},{"id":"o3","texto":"Más metano en la atmósfera"},{"id":"o4","texto":"Más tierra ocupada por décadas"},{"id":"o5","texto":"Más agua potable en la ciudad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Algunos se pagan en pesos, otros en ambiente y salud. Todos son reales."}},{"slug":"residuos-1.s4.p11","orden":11,"grupo":"residuos-1.s4.p11","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada idea con su ejemplo.","izquierda":[{"id":"a1","texto":"Costo interno"},{"id":"a2","texto":"Costo externo"},{"id":"a3","texto":"Responsabilidad extendida"},{"id":"a4","texto":"Ahorro en cadena"}],"derecha":[{"id":"b1","texto":"El sueldo de un recolector"},{"id":"b2","texto":"Una napa contaminada por lixiviados"},{"id":"b3","texto":"Una empresa financia la recuperación de sus envases"},{"id":"b4","texto":"Un kilo menos es menos camión y menos relleno"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ideas económicas para pensar los residuos más allá de la bolsa."}},{"slug":"residuos-1.s4.p12","orden":12,"grupo":"residuos-1.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Recolectar residuos es uno de los grandes gastos de un municipio."},{"id":"s2","texto":"Si la basura no la veo, no me cuesta nada."},{"id":"s3","texto":"Reducir un 10 % la basura ahorra camiones y espacio de relleno."},{"id":"s4","texto":"La responsabilidad extendida del productor significa que los vecinos paguen los envases."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La basura tiene costos visibles e invisibles, y alguien siempre los paga.","por_opcion":{"s2":"Se paga con las tasas y con costos externos como la contaminación.","s4":"Es al revés: busca que los productores financien la recuperación."}}},{"slug":"residuos-1.s4.p13","orden":13,"grupo":"residuos-1.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los costos que no paga quien genera el residuo se llaman {{0}}; la responsabilidad extendida busca que los pague el {{1}}.","banco":[{"id":"w1","texto":"externos"},{"id":"w2","texto":"productor"},{"id":"w3","texto":"internos"},{"id":"w4","texto":"vecino"},{"id":"w5","texto":"municipio"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos conceptos para discutir quién paga por la basura."}}]},{"slug":"residuos-1.s5","orden":5,"tipo":"leccion","titulo_es":"Quienes recuperan","bajada_es":"Recicladores urbanos, cooperativas y centros verdes: el trabajo que hace posible el reciclaje en Argentina.","minutos":11,"pasos":[{"slug":"residuos-1.s5.p1","orden":1,"grupo":"residuos-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los recicladores urbanos","cuerpo":["En Argentina, gran parte de los materiales que se reciclan son recuperados por recicladores urbanos, también llamados cartoneros o recuperadores. Recorren las calles, separan papel, cartón, plásticos, vidrio y metales, y los venden a la industria.","Durante mucho tiempo fue un trabajo informal y sin derechos. Con los años, muchos se organizaron en cooperativas y en organizaciones como la Federación Argentina de Cartoneros, Carreros y Recicladores (FACCyR), y varios municipios los incorporaron a su sistema de gestión."]},"solucion":{}},{"slug":"residuos-1.s5.p2","orden":2,"grupo":"residuos-1.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Quiénes recuperan gran parte de los materiales reciclables en las ciudades argentinas?","opciones":[{"id":"o1","texto":"Los recicladores urbanos y sus cooperativas"},{"id":"o2","texto":"Las fábricas de envases directamente en las casas"},{"id":"o3","texto":"Los camiones compactadores comunes"},{"id":"o4","texto":"Los rellenos sanitarios al enterrar la basura"}]},"solucion":{"clave":["o1"],"explicacion":"Sin los recicladores, las tasas de reciclaje del país serían mucho más bajas.","por_opcion":{"o3":"El camión común compacta todo junto: ahí se pierde casi todo lo reciclable."}}},{"slug":"residuos-1.s5.p3","orden":3,"grupo":"residuos-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Basura Cero y la inclusión","cuerpo":["En la Ciudad de Buenos Aires, leyes como la Ley 992 reconocieron a los recuperadores urbanos, y la Ley 1.854, conocida como \"Basura Cero\", fijó el objetivo de reducir progresivamente lo que se entierra y promover la separación en origen y el reciclaje.","Las cooperativas operan centros verdes: lugares donde el material separado se clasifica, se enfarda y se vende. Cuanto más limpio y separado llega el material, más vale y mejores son las condiciones de ese trabajo."]},"solucion":{}},{"slug":"residuos-1.s5.p4","orden":4,"grupo":"residuos-1.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una caja de cartón que separaste en tu casa.","items":[{"id":"i1","texto":"La separás limpia y seca en casa"},{"id":"i2","texto":"Un reciclador o un camión diferenciado la recoge"},{"id":"i3","texto":"Llega a un centro verde"},{"id":"i4","texto":"Se clasifica y se enfarda con otros cartones"},{"id":"i5","texto":"Se vende a una fábrica de papel"},{"id":"i6","texto":"Se entierra en el relleno junto con los orgánicos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Tu separación es el primer eslabón. Si falla, los demás no pueden hacer nada."}},{"slug":"residuos-1.s5.p5","orden":5,"grupo":"residuos-1.s5.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda al trabajo de los recicladores urbanos? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Separar los reciclables limpios y secos"},{"id":"o2","texto":"No mezclar vidrio roto con el resto sin protegerlo"},{"id":"o3","texto":"Aplastar las cajas y botellas"},{"id":"o4","texto":"Sacar los reciclables en el horario indicado"},{"id":"o5","texto":"Mezclar restos de comida con el cartón"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Material limpio vale más y es más seguro de manipular. Es respeto y es eficiencia."}},{"slug":"residuos-1.s5.p6","orden":6,"grupo":"residuos-1.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Separar los reciclables en casa no tiene efecto si no hay camión diferenciado.","razones":[{"id":"r1","texto":"Porque recicladores y puntos verdes pueden recuperarlo"},{"id":"r2","texto":"Porque separar hace que el material se degrade"},{"id":"r3","texto":"Porque los camiones comunes separan todo solos"}]},"solucion":{"valor":false,"explicacion":"En muchas ciudades los recicladores urbanos recuperan el material separado aunque no haya camión especial. Además, hay puntos verdes donde llevarlo.","clave":["r1"]}},{"slug":"residuos-1.s5.p7","orden":7,"grupo":"residuos-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un trabajo con riesgos","cuerpo":["Revolver bolsas mezcladas expone a los recicladores a cortes con vidrios, agujas y latas, a restos de comida en descomposición y a químicos. Las cooperativas organizadas trabajan para tener equipamiento, galpones, obra social y un ingreso más estable.","Separar bien en casa no solo mejora el reciclaje: reduce los riesgos de quien después toca esos materiales."]},"solucion":{}},{"slug":"residuos-1.s5.p8","orden":8,"grupo":"residuos-1.s5.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción en casa hace más seguro o más riesgoso el trabajo de un reciclador?","grupos":[{"id":"g1","nombre":"Más seguro"},{"id":"g2","nombre":"Más riesgoso"}],"items":[{"id":"i1","texto":"Envolver el vidrio roto en papel y marcarlo"},{"id":"i2","texto":"Tirar agujas sueltas en la bolsa"},{"id":"i3","texto":"Separar los reciclables secos de los orgánicos"},{"id":"i4","texto":"Mezclar vidrio roto con cartón"},{"id":"i5","texto":"Cerrar bien las bolsas"},{"id":"i6","texto":"Poner químicos en botellas de bebida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La bolsa que sacás la toca otra persona. Pensarlo cambia cómo la armás."}},{"slug":"residuos-1.s5.p9","orden":9,"grupo":"residuos-1.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada lugar o actor con su función.","izquierda":[{"id":"a1","texto":"Centro verde"},{"id":"a2","texto":"Cooperativa de recicladores"},{"id":"a3","texto":"Punto verde"},{"id":"a4","texto":"Industria recicladora"}],"derecha":[{"id":"b1","texto":"Clasifica y enfarda el material separado"},{"id":"b2","texto":"Organiza el trabajo de recuperación"},{"id":"b3","texto":"Lugar donde los vecinos dejan reciclables"},{"id":"b4","texto":"Transforma el material en producto nuevo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El reciclaje es una cadena de actores. Cada uno depende del anterior."}},{"slug":"residuos-1.s5.p10","orden":10,"grupo":"residuos-1.s5.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una vecina pregunta si vale la pena lavar un frasco antes de separarlo. ¿Qué le responderías?","opciones":[{"id":"o1","texto":"Sí, con un enjuague alcanza: el material limpio vale más"},{"id":"o2","texto":"No, en la planta lo lavan todo con máquinas especiales"},{"id":"o3","texto":"No, el vidrio sucio se recicla igual de bien que el limpio"},{"id":"o4","texto":"Sí, pero solo si es un frasco de vidrio muy caro"}]},"solucion":{"clave":["o1"],"explicacion":"No hace falta dejarlo impecable: con sacarle los restos y enjuagarlo alcanza para no ensuciar el resto.","por_opcion":{"o3":"Los restos de comida contaminan otros materiales y bajan su valor."}}},{"slug":"residuos-1.s5.p11","orden":11,"grupo":"residuos-1.s5.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario en redes y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los cartoneros recuperan buena parte del material reciclable del país."},{"id":"s2","texto":"Separar en casa es inútil: los cartoneros revuelven todo igual."},{"id":"s3","texto":"Muchos se organizaron en cooperativas."},{"id":"s4","texto":"Es un trabajo sin ningún riesgo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reconocer el trabajo de los recicladores es también cambiar cómo armamos la bolsa.","por_opcion":{"s2":"Si el material ya viene separado, no tienen que revolver: es más limpio, seguro y valioso.","s4":"Hay riesgos de cortes, pinchazos e infecciones, sobre todo con bolsas mezcladas."}}},{"slug":"residuos-1.s5.p12","orden":12,"grupo":"residuos-1.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas bolsas de la más valiosa a la menos valiosa para un centro verde.","items":[{"id":"i1","texto":"Cartón seco y aplastado"},{"id":"i2","texto":"Botellas plásticas enjuagadas"},{"id":"i3","texto":"Reciclables secos mezclados entre sí"},{"id":"i4","texto":"Reciclables mezclados con restos de comida"}],"extremos":["Más valiosa","Menos valiosa"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto mejor separado y más limpio, más material se recupera y mejor se paga ese trabajo.","valores":{"i1":"se vende directo","i2":"se venden tras clasificar","i3":"hay que clasificar todo","i4":"casi todo se pierde"}}},{"slug":"residuos-1.s5.p13","orden":13,"grupo":"residuos-1.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los recicladores urbanos llevan el material a centros {{0}}, donde se clasifica y se {{1}} para venderlo a la {{2}}.","banco":[{"id":"w1","texto":"verdes"},{"id":"w2","texto":"enfarda"},{"id":"w3","texto":"industria"},{"id":"w4","texto":"rojos"},{"id":"w5","texto":"entierra"},{"id":"w6","texto":"municipalidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El recorrido del material separado, en una línea."}}]},{"slug":"residuos-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: qué pasa con lo que tirás","bajada_es":"Qué es un residuo, composición, destino, costos y recuperadores, mezclados.","minutos":8,"pasos":[{"slug":"residuos-1.s6.p1","orden":1,"grupo":"residuos-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Qué pasa con lo que tirás». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la semana de la familia Sosa","bajada_es":"La familia Sosa pesó su basura durante una semana. Con los números, encontrá qué hacer primero. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"residuos-1.s7.p1","orden":1,"grupo":"residuos-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos de los Sosa","cuerpo":["Los Sosa son 4 y viven en un municipio que manda todo a un relleno sanitario. Durante una semana pesaron su basura: 30 kilos en total.","Separaron por tipo: 15 kg de restos de comida y yerba, 5 kg de papel y cartón, 4 kg de plásticos, 2 kg de vidrio, 1 kg de metales y 3 kg de pañales y otros. En su barrio pasan recicladores dos veces por semana y hay un punto verde a diez cuadras."]},"solucion":{}},{"slug":"residuos-1.s7.p2","orden":2,"grupo":"residuos-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos por persona por día generaron los Sosa?","unidad":"kg","decimales":2,"contexto":"30 kg en una semana, 4 personas."},"solucion":{"valor":1.07,"tolerancia":0.02,"explicacion":"30 kg ÷ 4 personas ÷ 7 días ≈ 1,07 kg por persona por día: muy cerca del promedio argentino."}},{"slug":"residuos-1.s7.p3","orden":3,"grupo":"residuos-1.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de su basura son orgánicos?","unidad":"%","decimales":0,"contexto":"15 kg de orgánicos sobre 30 kg totales."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"15 ÷ 30 × 100 = 50 %. La mitad de la bolsa podría compostarse."}},{"slug":"residuos-1.s7.p4","orden":4,"grupo":"residuos-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos por semana son reciclables secos (papel y cartón, plásticos, vidrio y metales)?","unidad":"kg","decimales":0,"contexto":"Papel y cartón 5 kg, plásticos 4, vidrio 2, metales 1."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"5 + 4 + 2 + 1 = 12 kg. El 40 % de su basura podría ir a los recicladores o al punto verde."}},{"slug":"residuos-1.s7.p5","orden":5,"grupo":"residuos-1.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los Sosa compostan el 100 % de sus orgánicos (15 kg) y separan el 100 % de sus reciclables secos (12 kg), ¿cuántos kilos por semana seguirían yendo al relleno?","unidad":"kg","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Compostan 15 kg y separan 12 kg: 30 − 15 − 12 = 3 kg al relleno por semana."}},{"slug":"residuos-1.s7.p5.v2","orden":5,"grupo":"residuos-1.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los Sosa compostan el 80 % de sus orgánicos (15 kg) y separan el 75 % de sus reciclables secos (12 kg), ¿cuántos kilos por semana seguirían yendo al relleno?","unidad":"kg","decimales":1},"solucion":{"valor":9,"tolerancia":0.18,"explicacion":"Compostan 12 kg y separan 9 kg: 30 − 12 − 9 = 9 kg al relleno por semana."}},{"slug":"residuos-1.s7.p5.v3","orden":5,"grupo":"residuos-1.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los Sosa compostan el 60 % de sus orgánicos (15 kg) y separan el 50 % de sus reciclables secos (12 kg), ¿cuántos kilos por semana seguirían yendo al relleno?","unidad":"kg","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"Compostan 9 kg y separan 6 kg: 30 − 9 − 6 = 15 kg al relleno por semana."}},{"slug":"residuos-1.s7.p6","orden":6,"grupo":"residuos-1.s7.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las acciones posibles de los Sosa por cuántos kilos sacarían del relleno por semana, de más a menos.","items":[{"id":"i1","texto":"Compostar los orgánicos"},{"id":"i2","texto":"Separar papel y cartón"},{"id":"i3","texto":"Separar plásticos"},{"id":"i4","texto":"Separar vidrio"},{"id":"i5","texto":"Separar metales"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El compostaje es el cambio más grande por peso. Separar los secos suma casi lo mismo entre todos.","valores":{"i1":"hasta 15 kg","i2":"hasta 5 kg","i3":"hasta 4 kg","i4":"hasta 2 kg","i5":"hasta 1 kg"}}},{"slug":"residuos-1.s7.p7","orden":7,"grupo":"residuos-1.s7.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Los Sosa no tienen patio. ¿Qué pueden hacer con los orgánicos?","opciones":[{"id":"o1","texto":"Buscar una compostera de balcón o un compostaje comunitario"},{"id":"o2","texto":"Tirarlos por el inodoro para que no ocupen lugar"},{"id":"o3","texto":"Nada: sin patio no hay forma de compostar"},{"id":"o4","texto":"Mezclarlos con el cartón para que pesen menos"}]},"solucion":{"clave":["o1"],"explicacion":"Sin patio también se puede: vermicompostaje en balcón o llevar los orgánicos a un punto de compostaje comunitario.","por_opcion":{"o3":"Hay composteras chicas para interiores y programas de compostaje barrial."}}},{"slug":"residuos-1.s7.p8","orden":8,"grupo":"residuos-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Los Sosa escriben su plan en la heladera. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Separamos cartón, plástico, vidrio y metal limpios y secos."},{"id":"s2","texto":"Guardamos los restos de comida junto con el cartón hasta que pasen los recicladores."},{"id":"s3","texto":"Probamos una compostera de balcón para los orgánicos."},{"id":"s4","texto":"El vidrio roto va suelto en la bolsa de reciclables."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan separa bien, piensa en quien recibe la bolsa y ataca primero lo más pesado.","por_opcion":{"s2":"Los orgánicos ensucian el cartón y lo vuelven irrecuperable.","s4":"Hay que envolverlo y marcarlo: es un riesgo para quien lo manipula."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"residuos-2","rama":"residuos","orden":2,"nivel":1,"titulo_es":"Reducir, reutilizar, reciclar","bajada_es":"No son tres opciones iguales: son una escalera. Por qué reducir le gana a reciclar, y cómo funciona el reciclaje por dentro.","objetivos_es":["Ordenar las opciones de gestión según la jerarquía de residuos","Identificar formas concretas de reducir residuos en la fuente","Evaluar cuándo reutilizar un objeto compensa su fabricación","Explicar las etapas del reciclaje y los límites de cada material","Argumentar por qué el reciclaje solo no resuelve el problema"],"repasa":["residuos-1","tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["ellen-macarthur","yale-reciclaje","unep-plasticos","oecd-plasticos","mst-bolsas-2018","iai-reciclaje-aluminio","ley-25916-residuos","epa"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-2.s1","orden":1,"tipo":"leccion","titulo_es":"La escalera de los residuos","bajada_es":"Prevenir, reutilizar, reciclar, recuperar energía y enterrar: un orden con fundamento.","minutos":11,"pasos":[{"slug":"residuos-2.s1.p1","orden":1,"grupo":"residuos-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todas las opciones valen lo mismo","cuerpo":["La jerarquía de residuos ordena las opciones de mejor a peor para el ambiente: primero prevenir (que el residuo no exista), después reutilizar, después reciclar, después recuperar energía y, como último recurso, disponer en un relleno.","Cada escalón hacia arriba ahorra más materiales, energía y emisiones. Reciclar es bueno, pero es el tercer escalón, no el primero."],"lista":["1. Prevenir y reducir","2. Reutilizar","3. Reciclar","4. Recuperar energía","5. Disponer en relleno"]},"solucion":{}},{"slug":"residuos-2.s1.p2","orden":2,"grupo":"residuos-2.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la jerarquía de residuos de la mejor a la peor opción.","items":[{"id":"i1","texto":"Prevenir que el residuo exista"},{"id":"i2","texto":"Reutilizar el objeto"},{"id":"i3","texto":"Reciclar el material"},{"id":"i4","texto":"Recuperar energía"},{"id":"i5","texto":"Enterrar en un relleno sanitario"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una escalera: cuanto más arriba se resuelve, menos se pierde."}},{"slug":"residuos-2.s1.p3","orden":3,"grupo":"residuos-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué ese orden","cuerpo":["Fabricar algo nuevo usa materias primas, agua y energía. Si un objeto no se fabrica, se ahorra todo eso. Si se reutiliza, se ahorra casi todo. Si se recicla, se recupera el material, pero hay que recolectarlo, transportarlo, limpiarlo, fundirlo o triturarlo y volver a fabricar: se ahorra una parte.","Recuperar energía quemando residuos aprovecha algo, pero el material se pierde. Enterrar pierde todo."]},"solucion":{}},{"slug":"residuos-2.s1.p4","orden":4,"grupo":"residuos-2.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué reutilizar un frasco ahorra más que reciclarlo.","items":[{"id":"i1","texto":"El frasco reutilizado sigue siendo un frasco"},{"id":"i2","texto":"No hace falta fundirlo ni fabricar uno nuevo"},{"id":"i3","texto":"Se ahorra la energía de fundir el vidrio a más de 1.000 °C"},{"id":"i4","texto":"Se evitan las emisiones de esa energía"},{"id":"i5","texto":"Reutilizar el frasco lo vuelve más pesado"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Reciclar vidrio es bueno, pero fundirlo pide mucha energía. Lavarlo y volver a llenarlo, muy poca."}},{"slug":"residuos-2.s1.p5","orden":5,"grupo":"residuos-2.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué escalón de la jerarquía está cada acción?","grupos":[{"id":"g1","nombre":"Prevenir o reducir"},{"id":"g2","nombre":"Reutilizar"},{"id":"g3","nombre":"Reciclar"}],"items":[{"id":"i1","texto":"No aceptar un folleto que no vas a leer"},{"id":"i2","texto":"Usar una botella retornable"},{"id":"i3","texto":"Separar latas para que se fundan"},{"id":"i4","texto":"Comprar a granel con tu propio frasco"},{"id":"i5","texto":"Arreglar una silla rota"},{"id":"i6","texto":"Llevar el cartón al punto verde"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada acción cuenta, pero no cuenta igual. Las de arriba evitan todo lo que viene después."}},{"slug":"residuos-2.s1.p6","orden":6,"grupo":"residuos-2.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si todo lo que uso se recicla, no importa cuánto consumo.","razones":[{"id":"r1","texto":"Porque reciclar tiene costos y pérdidas en cada vuelta"},{"id":"r2","texto":"Porque reciclar crea materiales nuevos de la nada"},{"id":"r3","texto":"Porque el reciclaje no usa energía"}]},"solucion":{"valor":false,"explicacion":"Reciclar recupera una parte, pero cuesta energía, transporte y agua, y nunca recupera el 100 %. Reducir sigue siendo mejor.","clave":["r1"]}},{"slug":"residuos-2.s1.p7","orden":7,"grupo":"residuos-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un ejemplo con números","cuerpo":["Supongamos que fabricar una botella nueva de vidrio cuesta 100 unidades de energía. Reciclar una botella usada para hacer otra puede costar alrededor de 70 a 80, porque fundir vidrio reciclado pide algo menos de energía que partir de arena. Lavar y volver a llenar una botella retornable puede costar menos de 10.","Los números exactos cambian mucho según el caso, pero el orden casi nunca cambia: reutilizar le gana a reciclar, y reciclar le gana a fabricar de cero."]},"solucion":{}},{"slug":"residuos-2.s1.p8","orden":8,"grupo":"residuos-2.s1.p8","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para tener una botella llena de nuevo, de más a menos energía (ejemplo aproximado).","items":[{"id":"i1","texto":"Fabricar una botella nueva desde arena"},{"id":"i2","texto":"Fabricar una botella con vidrio reciclado"},{"id":"i3","texto":"Lavar y rellenar una botella retornable"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"El orden de la jerarquía se ve en la energía. La retornable no necesita volver a fundir nada.","valores":{"i1":"≈ 100 unidades","i2":"≈ 70-80 unidades","i3":"menos de 10 unidades"}}},{"slug":"residuos-2.s1.p9","orden":9,"grupo":"residuos-2.s1.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tenés un frasco de vidrio vacío en buen estado. ¿Cuál es la mejor opción según la jerarquía?","opciones":[{"id":"o1","texto":"Usarlo de nuevo para guardar algo"},{"id":"o2","texto":"Llevarlo al punto verde para reciclarlo"},{"id":"o3","texto":"Tirarlo con la basura común"},{"id":"o4","texto":"Romperlo para que ocupe menos lugar en el tacho"}]},"solucion":{"clave":["o1"],"explicacion":"Si el frasco sirve, usarlo es el escalón más alto disponible. Cuando ya no sirva, el reciclaje.","por_opcion":{"o3":"Es la peor opción: se pierde todo el material y la energía de fabricarlo."}}},{"slug":"residuos-2.s1.p10","orden":10,"grupo":"residuos-2.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas acciones están en el escalón más alto, prevenir? Marcá todas.","opciones":[{"id":"o1","texto":"Rechazar una bolsa cuando no la necesitás"},{"id":"o2","texto":"Comprar productos con menos envoltorio"},{"id":"o3","texto":"Planificar las compras para no tirar comida"},{"id":"o4","texto":"Separar las botellas para el reciclaje"},{"id":"o5","texto":"Llevar las pilas a un punto de recolección"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Prevenir es actuar antes de que el residuo exista. Separar y llevar a un punto verde es bueno, pero ya hay residuo."}},{"slug":"residuos-2.s1.p11","orden":11,"grupo":"residuos-2.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este afiche escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las tres R son reducir, reutilizar y reciclar."},{"id":"s2","texto":"Las tres valen lo mismo: da igual cuál hagas."},{"id":"s3","texto":"Enterrar es la última opción."},{"id":"s4","texto":"Reciclar es la mejor forma de cuidar el ambiente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El orden de las R es la parte más importante del mensaje, y la que más se olvida.","por_opcion":{"s2":"Son una jerarquía: reducir evita más impacto que reutilizar, y reutilizar más que reciclar.","s4":"Es buena, pero está por debajo de reducir y reutilizar."}}},{"slug":"residuos-2.s1.p12","orden":12,"grupo":"residuos-2.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En la jerarquía de residuos, primero se busca {{0}}, después {{1}} y recién después {{2}}.","banco":[{"id":"w1","texto":"reducir"},{"id":"w2","texto":"reutilizar"},{"id":"w3","texto":"reciclar"},{"id":"w4","texto":"enterrar"},{"id":"w5","texto":"quemar"},{"id":"w6","texto":"comprar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres R, en el orden que de verdad importa."}},{"slug":"residuos-2.s1.p13","orden":13,"grupo":"residuos-2.s1.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada escalón con su ejemplo.","izquierda":[{"id":"a1","texto":"Prevenir"},{"id":"a2","texto":"Reutilizar"},{"id":"a3","texto":"Reciclar"},{"id":"a4","texto":"Disponer"}],"derecha":[{"id":"b1","texto":"No imprimir un documento que se puede leer en pantalla"},{"id":"b2","texto":"Usar la hoja impresa del otro lado"},{"id":"b3","texto":"Separar el papel para hacer papel nuevo"},{"id":"b4","texto":"Tirar el papel con restos de comida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El mismo material, cuatro destinos distintos. Cuanto más arriba, menos se pierde."}}]},{"slug":"residuos-2.s2","orden":2,"tipo":"leccion","titulo_es":"Reducir: el residuo que no existe","bajada_es":"Envases, descartables, compras y comida: dónde nace la basura y cómo evitar que nazca.","minutos":12,"pasos":[{"slug":"residuos-2.s2.p1","orden":1,"grupo":"residuos-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La basura se decide al comprar","cuerpo":["Buena parte de lo que termina en la bolsa entró a la casa en el changuito: envases, bolsas, bandejas, envoltorios. Cada decisión de compra decide también qué residuos vamos a tener.","Reducir no es privarse de todo: es elegir, cuando se puede, la opción que genera menos residuo para la misma necesidad."]},"solucion":{}},{"slug":"residuos-2.s2.p2","orden":2,"grupo":"residuos-2.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Cuál de las dos opciones genera menos residuo?","grupos":[{"id":"g1","nombre":"Menos residuo"},{"id":"g2","nombre":"Más residuo"}],"items":[{"id":"i1","texto":"Fruta suelta en tu propia bolsa"},{"id":"i2","texto":"Fruta en bandeja de telgopor con film"},{"id":"i3","texto":"Detergente en envase grande o recarga"},{"id":"i4","texto":"Detergente en muchos envases chicos"},{"id":"i5","texto":"Agua de la canilla en botella reutilizable"},{"id":"i6","texto":"Agua en botellitas descartables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La misma necesidad, distinta cantidad de envase. Muchas veces la opción con menos residuo también es más barata."}},{"slug":"residuos-2.s2.p3","orden":3,"grupo":"residuos-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los descartables","cuerpo":["Los objetos de un solo uso —vasos, cubiertos, sorbetes, bolsas livianas, bandejas— se fabrican para usarse minutos y duran como residuo décadas o siglos. Son chicos uno por uno, pero se usan por miles de millones.","Muchas ciudades del país y del mundo restringieron bolsas livianas y algunos descartables. El cambio más efectivo, igual, es el de hábito: llevar la bolsa, el vaso o la botella propios."]},"solucion":{}},{"slug":"residuos-2.s2.p4","orden":4,"grupo":"residuos-2.s2.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 4 personas cada una usa 3 bolsas descartables por semana. ¿Cuántas bolsas usan en un año de 52 semanas?","unidad":"bolsas","decimales":0},"solucion":{"valor":624,"tolerancia":12.48,"explicacion":"3 × 4 × 52 = 624 bolsas por año. Una bolsa reutilizable reemplaza cientos de ellas."}},{"slug":"residuos-2.s2.p4.v2","orden":4,"grupo":"residuos-2.s2.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 3 personas cada una usa 2 bolsas descartables por semana. ¿Cuántas bolsas usan en un año de 52 semanas?","unidad":"bolsas","decimales":0},"solucion":{"valor":312,"tolerancia":6.24,"explicacion":"2 × 3 × 52 = 312 bolsas por año. Una bolsa reutilizable reemplaza cientos de ellas."}},{"slug":"residuos-2.s2.p4.v3","orden":4,"grupo":"residuos-2.s2.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 2 personas cada una usa 5 bolsas descartables por semana. ¿Cuántas bolsas usan en un año de 52 semanas?","unidad":"bolsas","decimales":0},"solucion":{"valor":520,"tolerancia":10.4,"explicacion":"5 × 2 × 52 = 520 bolsas por año. Una bolsa reutilizable reemplaza cientos de ellas."}},{"slug":"residuos-2.s2.p5","orden":5,"grupo":"residuos-2.s2.p5","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un vaso descartable se usa minutos, pero puede durar como residuo muchísimo más tiempo.","razones":[{"id":"r1","texto":"Porque el material dura mucho más que su uso"},{"id":"r2","texto":"Porque el vaso se desintegra al terminar de usarse"},{"id":"r3","texto":"Porque los descartables se reciclan siempre solos"}]},"solucion":{"valor":true,"explicacion":"Es la paradoja del descartable: diseñado para durar como producto unos minutos y como residuo, décadas o siglos si es de plástico.","clave":["r1"]}},{"slug":"residuos-2.s2.p6","orden":6,"grupo":"residuos-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Comprar a granel y recargar","cuerpo":["Comprar a granel —legumbres, cereales, especias, productos de limpieza— con frascos o bolsas propias evita muchos envases. Los sistemas de recarga (de detergente, de agua en bidones, de gas en garrafas) hacen lo mismo: el envase vuelve y se llena otra vez.","No siempre es posible, pero donde existe, reduce el residuo desde la raíz."]},"solucion":{}},{"slug":"residuos-2.s2.p7","orden":7,"grupo":"residuos-2.s2.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas prácticas reducen residuos en la fuente? Marcá todas.","opciones":[{"id":"o1","texto":"Comprar legumbres a granel con frasco propio"},{"id":"o2","texto":"Usar un sistema de recarga de detergente"},{"id":"o3","texto":"Llevar un termo en lugar de comprar café en vaso descartable"},{"id":"o4","texto":"Pedir la comida para llevar sin cubiertos descartables"},{"id":"o5","texto":"Comprar agua en botellitas y separarlas para reciclar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Separar botellitas ayuda, pero el residuo ya existe. Las otras cuatro evitan que exista."}},{"slug":"residuos-2.s2.p8","orden":8,"grupo":"residuos-2.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La comida: el residuo más pesado","cuerpo":["Como viste en la unidad anterior, los restos orgánicos son casi la mitad de la basura. Una parte son cáscaras y restos inevitables, pero otra es comida que se compró y no se comió: se venció, se echó a perder o sobró.","Planificar las compras, guardar bien los alimentos, usar primero lo que vence antes y aprovechar las sobras reduce la bolsa y, además, ahorra plata. El desperdicio de alimentos se ve en detalle en la rama de Alimentación."]},"solucion":{}},{"slug":"residuos-2.s2.p9","orden":9,"grupo":"residuos-2.s2.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para reducir la comida que se tira en una casa.","items":[{"id":"i1","texto":"Revisar qué hay en la heladera y la alacena"},{"id":"i2","texto":"Planificar las comidas de la semana"},{"id":"i3","texto":"Hacer una lista y comprar solo lo necesario"},{"id":"i4","texto":"Guardar bien y poner adelante lo que vence antes"},{"id":"i5","texto":"Aprovechar las sobras en otra comida"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Mirar, planificar, comprar justo, guardar bien y aprovechar: la comida que no se tira es residuo que nunca existió."}},{"slug":"residuos-2.s2.p10","orden":10,"grupo":"residuos-2.s2.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué reduce más la basura de una familia: separar los envases o dejar de tirar comida que se echa a perder?","opciones":[{"id":"o1","texto":"Depende, pero la comida suele pesar mucho más"},{"id":"o2","texto":"Separar envases, porque los plásticos son lo peor"},{"id":"o3","texto":"Son exactamente iguales siempre"},{"id":"o4","texto":"Ninguna de las dos cambia la cantidad de basura"}]},"solucion":{"clave":["o1"],"explicacion":"Por peso, la comida desperdiciada suele ser mucho más que los envases. Las dos acciones suman, y conviene hacer ambas.","por_opcion":{"o3":"Pesan y funcionan distinto: la comida es una parte muy grande del peso de la bolsa."}}},{"slug":"residuos-2.s2.p11","orden":11,"grupo":"residuos-2.s2.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una lista de compras reduce la basura.","items":[{"id":"i1","texto":"Se revisa qué hay antes de salir"},{"id":"i2","texto":"Se compra solo lo que se va a usar"},{"id":"i3","texto":"Se vence y se echa a perder menos comida"},{"id":"i4","texto":"Llegan menos orgánicos a la bolsa"},{"id":"i5","texto":"La lista hace que la comida dure el doble"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una decisión antes de comprar evita un residuo días después."}},{"slug":"residuos-2.s2.p12","orden":12,"grupo":"residuos-2.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los que no reducen residuos.","segmentos":[{"id":"s1","texto":"Llevá tu bolsa de tela al supermercado."},{"id":"s2","texto":"Comprá todo en porciones individuales para no desperdiciar."},{"id":"s3","texto":"Pedí delivery sin cubiertos descartables."},{"id":"s4","texto":"Comprá más cantidad de lo que está en oferta, aunque no lo vayas a usar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reducir es comprar lo que se usa, con el menor envase posible.","por_opcion":{"s2":"Las porciones individuales multiplican los envases; conviene porcionar en casa.","s4":"Si se vence sin usar, se convierte en residuo."}}},{"slug":"residuos-2.s2.p13","orden":13,"grupo":"residuos-2.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Buena parte de la basura se decide al {{0}}; los descartables se usan minutos y duran como residuo {{1}}.","banco":[{"id":"w1","texto":"comprar"},{"id":"w2","texto":"décadas"},{"id":"w3","texto":"tirar"},{"id":"w4","texto":"segundos"},{"id":"w5","texto":"horas"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de reducir: actuar antes de que el residuo exista."}},{"slug":"residuos-2.s2.p14","orden":14,"grupo":"residuos-2.s2.p14","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas bolsas descartables usaría por año una persona que usa 1 por día.","min":50,"max":1000,"paso":5,"unidad":"bolsas","escala":"lineal"},"solucion":{"valor":365,"banda":"lineal","explicacion":"Una por día son 365 por año. Multiplicado por millones de personas, miles de millones de bolsas."}}]},{"slug":"residuos-2.s3","orden":3,"tipo":"leccion","titulo_es":"Reutilizar y reparar","bajada_es":"Retornables, bolsas reutilizables y reparación: cuándo reutilizar compensa y cuánto hay que usar algo para que valga.","minutos":14,"pasos":[{"slug":"residuos-2.s3.p1","orden":1,"grupo":"residuos-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reutilizar es alargar la vida","cuerpo":["Reutilizar es volver a usar un objeto para lo mismo o para otra cosa, sin transformarlo industrialmente: una botella retornable que se lava y se vuelve a llenar, un frasco que guarda legumbres, una mochila que pasa de un hermano a otro.","Reparar es una forma de reutilizar: una silla arreglada, un celular con batería nueva, una campera con cierre cambiado. Cada año de vida extra es un objeto nuevo que no se fabricó."]},"solucion":{}},{"slug":"residuos-2.s3.p2","orden":2,"grupo":"residuos-2.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es reutilizar/reparar o es reciclar?","grupos":[{"id":"g1","nombre":"Reutilizar o reparar"},{"id":"g2","nombre":"Reciclar"}],"items":[{"id":"i1","texto":"Cambiarle la suela a unas zapatillas"},{"id":"i2","texto":"Triturar botellas para hacer fibra"},{"id":"i3","texto":"Usar un frasco de mermelada como vaso"},{"id":"i4","texto":"Fundir latas para hacer aluminio"},{"id":"i5","texto":"Devolver un envase retornable"},{"id":"i6","texto":"Hacer pasta de papel con diarios viejos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Reutilizar conserva el objeto; reciclar lo destruye para recuperar el material."}},{"slug":"residuos-2.s3.p3","orden":3,"grupo":"residuos-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La huella de fabricar","cuerpo":["Un objeto reutilizable suele necesitar más material y energía para fabricarse que uno descartable: una bolsa de tela o un vaso de acero tienen más huella de fabricación que una bolsa o un vaso descartables. Por eso reutilizar compensa solo si se usa muchas veces.","Estudios de ciclo de vida muestran que una bolsa de algodón necesita decenas de usos solo para compensar su huella de carbono frente a una bolsa plástica liviana, y muchos más si se cuentan otros impactos como el agua. La mejor bolsa es la que ya tenés, usada muchas veces."]},"solucion":{}},{"slug":"residuos-2.s3.p4","orden":4,"grupo":"residuos-2.s3.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El punto de equilibrio","planteo":"Fabricar un vaso de acero reutilizable emite lo mismo que fabricar 50 vasos descartables. Lavarlo emite muy poco.","pasos":["Si se usa 10 veces, reemplaza 10 descartables: todavía emite más que ellos.","Si se usa 50 veces, empata.","Si se usa 500 veces, emite alrededor de una décima parte de lo que emitirían 500 descartables."],"resultado":"El reutilizable gana solo si se usa más allá del punto de equilibrio. Comprarlo y olvidarlo en un cajón es peor que no comprarlo."},"solucion":{}},{"slug":"residuos-2.s3.p5","orden":5,"grupo":"residuos-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un objeto reutilizable necesita 50 usos para compensar su fabricación. Si se usa 200 veces, ¿cuántas veces supera ese punto de equilibrio?","unidad":"veces","decimales":1},"solucion":{"valor":4,"tolerancia":0.08,"explicacion":"200 ÷ 50 = 4 veces el punto de equilibrio. A partir de ahí, cada uso es ganancia neta para el ambiente."}},{"slug":"residuos-2.s3.p5.v2","orden":5,"grupo":"residuos-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un objeto reutilizable necesita 30 usos para compensar su fabricación. Si se usa 150 veces, ¿cuántas veces supera ese punto de equilibrio?","unidad":"veces","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"150 ÷ 30 = 5 veces el punto de equilibrio. A partir de ahí, cada uso es ganancia neta para el ambiente."}},{"slug":"residuos-2.s3.p5.v3","orden":5,"grupo":"residuos-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un objeto reutilizable necesita 100 usos para compensar su fabricación. Si se usa 300 veces, ¿cuántas veces supera ese punto de equilibrio?","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"300 ÷ 100 = 3 veces el punto de equilibrio. A partir de ahí, cada uso es ganancia neta para el ambiente."}},{"slug":"residuos-2.s3.p6","orden":6,"grupo":"residuos-2.s3.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar una bolsa de tela nueva siempre es mejor para el ambiente que usar bolsas plásticas.","razones":[{"id":"r1","texto":"Porque su fabricación tiene más impacto y hay que compensarlo usándola"},{"id":"r2","texto":"Porque las bolsas de tela no se pueden lavar"},{"id":"r3","texto":"Porque las bolsas plásticas no tienen ningún impacto"}]},"solucion":{"valor":false,"explicacion":"Solo si se usa muchas veces. Fabricar una bolsa de tela tiene más impacto que fabricar una plástica liviana; compensa con el uso repetido.","clave":["r1"]}},{"slug":"residuos-2.s3.p7","orden":7,"grupo":"residuos-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Envases retornables","cuerpo":["Un envase retornable de vidrio o de plástico grueso se lava y se vuelve a llenar muchas veces: decenas de ciclos en el caso de algunas botellas de vidrio. Los sistemas de retornables fueron comunes en Argentina con las gaseosas, la leche y la cerveza, y muchas marcas los siguen usando.","Funcionan mejor cuando las distancias son cortas y hay un sistema organizado para devolverlos: si el envase viaja muy lejos, el transporte se come parte del ahorro."]},"solucion":{}},{"slug":"residuos-2.s3.p8","orden":8,"grupo":"residuos-2.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el ciclo de una botella retornable.","items":[{"id":"i1","texto":"Se llena en la planta embotelladora"},{"id":"i2","texto":"Se vende con el producto"},{"id":"i3","texto":"Se devuelve vacía en el comercio"},{"id":"i4","texto":"Vuelve a la planta y se lava"},{"id":"i5","texto":"Se llena de nuevo"},{"id":"i6","texto":"Se funde después de cada uso"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ciclo sin fundir ni fabricar. Cada vuelta evita una botella nueva."}},{"slug":"residuos-2.s3.p9","orden":9,"grupo":"residuos-2.s3.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un sistema de retornables funcione bien? Marcá todo lo que ayuda.","opciones":[{"id":"o1","texto":"Distancias cortas entre la planta y los comercios"},{"id":"o2","texto":"Un incentivo para devolver el envase, como un depósito"},{"id":"o3","texto":"Envases resistentes que aguanten muchos lavados"},{"id":"o4","texto":"Muchos comercios donde se puedan devolver"},{"id":"o5","texto":"Envases muy livianos que se rompen con facilidad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un retornable es un sistema, no solo un envase. Sin logística ni incentivos, los envases no vuelven."}},{"slug":"residuos-2.s3.p10","orden":10,"grupo":"residuos-2.s3.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reparar","cuerpo":["Reparar alarga la vida de los objetos y evita fabricar nuevos. Pero muchos aparatos están diseñados de forma que repararlos es difícil: piezas pegadas, repuestos que no se venden, tornillos especiales. En varios países se discute el \"derecho a reparar\": que los fabricantes vendan repuestos, publiquen manuales y no bloqueen reparaciones.","En muchas ciudades hay talleres de reparación comunitarios donde voluntarios enseñan a arreglar objetos."]},"solucion":{}},{"slug":"residuos-2.s3.p11","orden":11,"grupo":"residuos-2.s3.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué propone el \"derecho a reparar\"?","opciones":[{"id":"o1","texto":"Que los fabricantes faciliten repuestos, manuales y reparaciones"},{"id":"o2","texto":"Que cada persona repare sola cualquier aparato sin ayuda"},{"id":"o3","texto":"Que se prohíba vender aparatos nuevos"},{"id":"o4","texto":"Que los aparatos rotos se reciclen apenas fallan"}]},"solucion":{"clave":["o1"],"explicacion":"Un aparato que se puede reparar puede durar años más. El diseño decide si eso es posible.","por_opcion":{"o3":"No prohíbe vender: pide que reparar sea posible y accesible."}}},{"slug":"residuos-2.s3.p12","orden":12,"grupo":"residuos-2.s3.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para un celular con la batería gastada, de mejor a peor para el ambiente.","items":[{"id":"i1","texto":"Cambiarle la batería y seguir usándolo"},{"id":"i2","texto":"Venderlo o regalarlo a alguien que lo repare"},{"id":"i3","texto":"Llevarlo a un punto de reciclaje de electrónicos"},{"id":"i4","texto":"Tirarlo con la basura común"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Fabricar un celular es la parte más pesada de su huella. Alargar su vida es lo que más ahorra.","valores":{"i1":"evita fabricar un celular nuevo","i2":"otra persona lo sigue usando","i3":"recupera parte de los materiales","i4":"se pierde todo y puede contaminar"}}},{"slug":"residuos-2.s3.p13","orden":13,"grupo":"residuos-2.s3.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Nuestro vaso de acero dura años."},{"id":"s2","texto":"Comprá uno de cada color: cada vaso reutilizable ayuda al planeta."},{"id":"s3","texto":"Reemplaza cientos de vasos descartables si lo usás todos los días."},{"id":"s4","texto":"Con solo comprarlo ya estás reduciendo residuos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo reutilizable ayuda cuando se usa, no cuando se acumula.","por_opcion":{"s2":"Cada vaso nuevo tiene una huella de fabricación; solo compensa si se usa muchas veces.","s4":"Reduce si se usa en lugar de descartables, no por comprarlo."}}},{"slug":"residuos-2.s3.p14","orden":14,"grupo":"residuos-2.s3.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas veces hay que usar una bolsa de algodón para compensar solo su huella de carbono frente a una bolsa plástica liviana.","min":1,"max":1000,"paso":1,"unidad":"usos","escala":"log"},"solucion":{"valor":50,"banda":"log","explicacion":"Del orden de 50 usos según un estudio de ciclo de vida de la agencia ambiental danesa, y muchos más si se suman otros impactos como el agua. La bolsa que ya tenés, usada mil veces, es la mejor."}},{"slug":"residuos-2.s3.p15","orden":15,"grupo":"residuos-2.s3.p15","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Reparar un aparato casi siempre tiene menos impacto que fabricar uno nuevo.","razones":[{"id":"r1","texto":"Porque la fabricación suele ser la parte más pesada de la huella"},{"id":"r2","texto":"Porque los repuestos no tienen ninguna huella"},{"id":"r3","texto":"Porque los aparatos nuevos no consumen energía"}]},"solucion":{"valor":true,"explicacion":"La mayor parte de la huella de muchos aparatos está en su fabricación. Cambiar una pieza evita fabricar el aparato entero.","clave":["r1"]}},{"slug":"residuos-2.s3.p16","orden":16,"grupo":"residuos-2.s3.p16","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un objeto reutilizable compensa su fabricación recién después de muchos {{0}}; reparar {{1}} la vida del objeto y evita fabricar uno {{2}}.","banco":[{"id":"w1","texto":"usos"},{"id":"w2","texto":"alarga"},{"id":"w3","texto":"nuevo"},{"id":"w4","texto":"lavados"},{"id":"w5","texto":"acorta"},{"id":"w6","texto":"reciclado"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La lógica del punto de equilibrio, en una línea."}}]},{"slug":"residuos-2.s4","orden":4,"tipo":"leccion","titulo_es":"Cómo funciona el reciclaje","bajada_es":"Del punto verde a la fábrica: qué le pasa a cada material, qué dicen los números de los envases y qué se recicla mejor.","minutos":12,"pasos":[{"slug":"residuos-2.s4.p1","orden":1,"grupo":"residuos-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las etapas","cuerpo":["Reciclar es transformar un residuo en materia prima para fabricar algo nuevo. Tiene varias etapas: separación en origen, recolección, clasificación por material (y por tipo, en los plásticos), limpieza, procesamiento (triturar, fundir, hacer pasta) y fabricación del producto nuevo.","Si falla una etapa, el material se pierde. La más frágil suele ser la primera: si el residuo llega sucio o mezclado, muchas veces ya no se puede usar."]},"solucion":{}},{"slug":"residuos-2.s4.p2","orden":2,"grupo":"residuos-2.s4.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas del reciclaje de una botella de plástico.","items":[{"id":"i1","texto":"Se separa en casa, limpia y seca"},{"id":"i2","texto":"Se recolecta"},{"id":"i3","texto":"Se clasifica por tipo de plástico"},{"id":"i4","texto":"Se lava y se tritura en escamas"},{"id":"i5","texto":"Las escamas se usan para fabricar un producto nuevo"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada eslabón depende del anterior. El de tu casa es el primero."}},{"slug":"residuos-2.s4.p3","orden":3,"grupo":"residuos-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cada material es distinto","cuerpo":["El aluminio y el vidrio se pueden reciclar muchísimas veces sin perder calidad. Reciclar aluminio ahorra alrededor del 95 % de la energía que se necesita para producirlo desde el mineral.","El papel se puede reciclar varias veces, pero sus fibras se acortan en cada vuelta, así que en algún momento hay que sumar fibra nueva. Muchos plásticos pierden calidad al reciclarse y suelen convertirse en productos de menor exigencia: una botella puede volverse fibra textil, y esa fibra, difícilmente una botella otra vez."],"destacado":{"valor":"≈ 95 %","texto":"de la energía se ahorra al fabricar aluminio reciclado en vez de producirlo desde el mineral."}},"solucion":{}},{"slug":"residuos-2.s4.p4","orden":4,"grupo":"residuos-2.s4.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada material con su comportamiento al reciclarse.","izquierda":[{"id":"a1","texto":"Aluminio"},{"id":"a2","texto":"Vidrio"},{"id":"a3","texto":"Papel"},{"id":"a4","texto":"Plástico"}],"derecha":[{"id":"b1","texto":"Se recicla sin perder calidad y ahorra mucha energía"},{"id":"b2","texto":"Se funde y se vuelve vidrio muchas veces"},{"id":"b3","texto":"Sus fibras se acortan en cada vuelta"},{"id":"b4","texto":"Suele perder calidad y bajar de categoría"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"No todo reciclaje es igual. Algunos materiales dan muchas vueltas; otros, pocas."}},{"slug":"residuos-2.s4.p5","orden":5,"grupo":"residuos-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Producir una cantidad de aluminio desde el mineral usa 100 unidades de energía. Si reciclar ahorra el 95 %, ¿cuántas unidades usa hacerlo con aluminio reciclado?","unidad":"unidades","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"Se ahorra el 95 %: se usa el 5 %. 100 × 5 ÷ 100 = 5 unidades. Por eso las latas son de los residuos más valiosos."}},{"slug":"residuos-2.s4.p5.v2","orden":5,"grupo":"residuos-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Producir una cantidad de aluminio desde el mineral usa 200 unidades de energía. Si reciclar ahorra el 95 %, ¿cuántas unidades usa hacerlo con aluminio reciclado?","unidad":"unidades","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"Se ahorra el 95 %: se usa el 5 %. 200 × 5 ÷ 100 = 10 unidades. Por eso las latas son de los residuos más valiosos."}},{"slug":"residuos-2.s4.p5.v3","orden":5,"grupo":"residuos-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Producir una cantidad de aluminio desde el mineral usa 150 unidades de energía. Si reciclar ahorra el 95 %, ¿cuántas unidades usa hacerlo con aluminio reciclado?","unidad":"unidades","decimales":1},"solucion":{"valor":7.5,"tolerancia":0.15,"explicacion":"Se ahorra el 95 %: se usa el 5 %. 150 × 5 ÷ 100 = 7.5 unidades. Por eso las latas son de los residuos más valiosos."}},{"slug":"residuos-2.s4.p6","orden":6,"grupo":"residuos-2.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números de los plásticos","cuerpo":["Muchos envases plásticos tienen un triángulo con un número del 1 al 7. No quiere decir que sea reciclable: indica de qué tipo de plástico está hecho. El 1 es PET (botellas de bebidas), el 2 es polietileno de alta densidad (envases de lavandina o shampoo), el 3 es PVC, el 4 polietileno de baja densidad (bolsas y films), el 5 polipropileno (tapas, potes), el 6 poliestireno (incluido el telgopor) y el 7, otros o mezclas.","Los más reciclados en Argentina suelen ser el 1 (PET) y el 2 (PEAD). Otros tienen menos mercado y muchas veces no se recuperan."],"datos":{"tipo":"tabla","titulo":"Códigos de los plásticos","columnas":["Número","Material","Ejemplo"],"filas":[["1","PET","Botellas de bebidas"],["2","PEAD","Envases de lavandina y shampoo"],["3","PVC","Caños, algunos blísteres"],["4","PEBD","Bolsas y films"],["5","PP","Tapas, potes de yogur"],["6","PS","Vasos descartables, telgopor"],["7","Otros","Mezclas y otros plásticos"]]}},"solucion":{}},{"slug":"residuos-2.s4.p7","orden":7,"grupo":"residuos-2.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un envase tiene el triángulo con un número, seguro se recicla.","razones":[{"id":"r1","texto":"Porque el número indica el material, no que haya mercado para reciclarlo"},{"id":"r2","texto":"Porque el triángulo solo se pone en envases de vidrio"},{"id":"r3","texto":"Porque todos los plásticos se reciclan igual"}]},"solucion":{"valor":false,"explicacion":"El número indica el tipo de plástico, no que exista quien lo recicle. Algunos tipos casi no tienen mercado y terminan en el relleno.","clave":["r1"]}},{"slug":"residuos-2.s4.p8","orden":8,"grupo":"residuos-2.s4.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada envase con su número de plástico más probable.","izquierda":[{"id":"a1","texto":"Botella de gaseosa"},{"id":"a2","texto":"Bidón de lavandina"},{"id":"a3","texto":"Tapa de una botella"},{"id":"a4","texto":"Bandeja de telgopor"}],"derecha":[{"id":"b1","texto":"1 (PET)"},{"id":"b2","texto":"2 (PEAD)"},{"id":"b3","texto":"5 (PP)"},{"id":"b4","texto":"6 (PS)"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer los códigos ayuda a separar según lo que acepta el punto verde de tu ciudad."}},{"slug":"residuos-2.s4.p9","orden":9,"grupo":"residuos-2.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reciclaje que baja de categoría","cuerpo":["Cuando un material reciclado se usa para un producto de menor exigencia que el original, se habla de infrarreciclaje (downcycling en inglés). Una botella de PET puede convertirse en fibra para una remera o un relleno de almohadón, que después es muy difícil de reciclar otra vez.","Es mejor que enterrar, pero no cierra el círculo: el material termina saliendo del sistema en pocas vueltas."]},"solucion":{}},{"slug":"residuos-2.s4.p10","orden":10,"grupo":"residuos-2.s4.p10","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una botella de PET que baja de categoría.","items":[{"id":"i1","texto":"Botella de gaseosa"},{"id":"i2","texto":"Escamas de PET recicladas"},{"id":"i3","texto":"Fibra para una remera"},{"id":"i4","texto":"Remera usada que casi no se puede reciclar"},{"id":"i5","texto":"Termina como residuo"},{"id":"i6","texto":"Vuelve a ser botella infinitas veces sin pérdida"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Reciclar alarga la vida del material, pero en muchos plásticos no la hace eterna."}},{"slug":"residuos-2.s4.p11","orden":11,"grupo":"residuos-2.s4.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué material suele poder reciclarse muchas veces y cuál pocas?","grupos":[{"id":"g1","nombre":"Muchas veces"},{"id":"g2","nombre":"Pocas veces"}],"items":[{"id":"i1","texto":"Lata de aluminio"},{"id":"i2","texto":"Bandeja de telgopor"},{"id":"i3","texto":"Frasco de vidrio"},{"id":"i4","texto":"Envase multicapa de papas fritas"},{"id":"i5","texto":"Olla de acero"},{"id":"i6","texto":"Film de plástico con restos de comida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los metales y el vidrio son los campeones del reciclaje. Los plásticos mezclados y sucios, los que menos vuelven."}},{"slug":"residuos-2.s4.p12","orden":12,"grupo":"residuos-2.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El aluminio se puede reciclar muchas veces."},{"id":"s2","texto":"El número en el triángulo significa que el envase es reciclable en cualquier ciudad."},{"id":"s3","texto":"El papel pierde calidad en cada vuelta."},{"id":"s4","texto":"Una botella de PET siempre vuelve a ser botella."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El reciclaje real depende del material, del estado en que llega y del mercado.","por_opcion":{"s2":"Indica el tipo de plástico; que se recicle depende del mercado y del sistema local.","s4":"Muchas veces se convierte en fibra u otros productos de menor exigencia."}}},{"slug":"residuos-2.s4.p13","orden":13,"grupo":"residuos-2.s4.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las latas de aluminio son de los residuos más buscados por los recicladores?","opciones":[{"id":"o1","texto":"Porque reciclarlas ahorra mucha energía y no pierden calidad"},{"id":"o2","texto":"Porque son el residuo más pesado de toda la bolsa de basura"},{"id":"o3","texto":"Porque el aluminio se descompone rápido en el relleno"},{"id":"o4","texto":"Porque las latas se pueden compostar junto con los restos de comida"}]},"solucion":{"clave":["o1"],"explicacion":"Un material que ahorra el 95 % de la energía y se recicla sin perder calidad tiene buen precio en el mercado.","por_opcion":{"o3":"El aluminio no se descompone rápido: su valor está en reciclarlo."}}},{"slug":"residuos-2.s4.p14","orden":14,"grupo":"residuos-2.s4.p14","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las fibras de papel se pueden reciclar infinitas veces sin perder calidad.","razones":[{"id":"r1","texto":"Porque las fibras se acortan en cada reciclaje"},{"id":"r2","texto":"Porque el papel reciclado se vuelve plástico"},{"id":"r3","texto":"Porque el papel no se puede reciclar nunca"}]},"solucion":{"valor":false,"explicacion":"En cada vuelta las fibras se acortan y se debilitan. Después de varias vueltas ya no sirven y hay que sumar fibra nueva.","clave":["r1"]}},{"slug":"residuos-2.s4.p15","orden":15,"grupo":"residuos-2.s4.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Reciclar {{0}} ahorra cerca del 95 % de la energía; el número del triángulo indica el tipo de {{1}}, no que sea {{2}}.","banco":[{"id":"w1","texto":"aluminio"},{"id":"w2","texto":"plástico"},{"id":"w3","texto":"reciclable"},{"id":"w4","texto":"vidrio"},{"id":"w5","texto":"papel"},{"id":"w6","texto":"liviano"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Dos datos que desarman confusiones comunes."}}]},{"slug":"residuos-2.s5","orden":5,"tipo":"leccion","titulo_es":"Por qué reciclar no alcanza","bajada_es":"Solo una fracción del plástico del mundo se recicla. Los límites del reciclaje y el error del \"reciclaje por deseo\".","minutos":12,"pasos":[{"slug":"residuos-2.s5.p1","orden":1,"grupo":"residuos-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números globales","cuerpo":["A nivel mundial, menos del 10 % de todo el plástico que se produjo se recicló. La mayor parte terminó en rellenos, basurales o el ambiente, o se quemó. En los materiales como el aluminio o el papel las tasas son mucho más altas, pero en los plásticos el reciclaje es la excepción, no la regla.","La producción de plástico, además, sigue creciendo. Aunque se recicle más, si se produce mucho más, el total de residuos igual aumenta."],"destacado":{"valor":"< 10 %","texto":"de todo el plástico producido en el mundo se recicló."}},"solucion":{}},{"slug":"residuos-2.s5.p2","orden":2,"grupo":"residuos-2.s5.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de todo el plástico producido en el mundo se recicló.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":9,"banda":"lineal","explicacion":"Menos del 10 %. El resto se enterró, se quemó o quedó en el ambiente. Por eso el foco está cada vez más en reducir la producción de plásticos innecesarios."}},{"slug":"residuos-2.s5.p3","orden":3,"grupo":"residuos-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reciclar también cuesta","cuerpo":["El reciclaje necesita camiones, plantas, agua para lavar y energía para procesar. Para algunos materiales, el ahorro es enorme (aluminio); para otros, más chico. Y solo funciona si hay alguien que compre el material reciclado: si es más barato fabricar plástico nuevo, el reciclado no se vende y termina en el relleno."]},"solucion":{}},{"slug":"residuos-2.s5.p4","orden":4,"grupo":"residuos-2.s5.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un material separado puede terminar en el relleno igual.","items":[{"id":"i1","texto":"El plástico nuevo es muy barato"},{"id":"i2","texto":"Las fábricas prefieren comprar plástico nuevo"},{"id":"i3","texto":"Nadie compra el plástico reciclado de ese tipo"},{"id":"i4","texto":"El centro verde no puede venderlo"},{"id":"i5","texto":"Termina en el relleno aunque estaba separado"},{"id":"i6","texto":"El plástico separado se destruye solo en el centro verde"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El reciclaje es un mercado. Sin compradores, la separación no alcanza."}},{"slug":"residuos-2.s5.p5","orden":5,"grupo":"residuos-2.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El reciclaje por deseo","cuerpo":["Cuando alguien pone en los reciclables algo que no se recicla \"por las dudas\" —un envase sucio, un vidrio de ventana, un papel plastificado—, cree que ayuda, pero puede contaminar un fardo entero y hacer que se pierda todo. Se lo llama reciclaje por deseo (wishcycling en inglés).","Separar bien es separar lo que realmente se recupera en tu ciudad. Ante la duda, conviene informarse en el punto verde o en la página del municipio."]},"solucion":{}},{"slug":"residuos-2.s5.p6","orden":6,"grupo":"residuos-2.s5.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es el \"reciclaje por deseo\"?","opciones":[{"id":"o1","texto":"Poner en los reciclables cosas que no se reciclan, por las dudas"},{"id":"o2","texto":"Separar solo los materiales que realmente se reciclan"},{"id":"o3","texto":"Desear que haya más plantas de reciclaje"},{"id":"o4","texto":"Reciclar solo los envases que más te gustan"}]},"solucion":{"clave":["o1"],"explicacion":"Con buena intención se puede arruinar un lote entero. Separar bien es separar lo que se recupera.","por_opcion":{"o3":"No es un deseo abstracto: es poner cosas equivocadas en los reciclables."}}},{"slug":"residuos-2.s5.p7","orden":7,"grupo":"residuos-2.s5.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos residuos suelen arruinar un lote de reciclables? Marcá todos.","opciones":[{"id":"o1","texto":"Una caja de pizza muy engrasada"},{"id":"o2","texto":"Un envase de yogur con restos"},{"id":"o3","texto":"Pañales usados"},{"id":"o4","texto":"Vidrio de ventana mezclado con botellas"},{"id":"o5","texto":"Una botella de PET enjuagada y aplastada"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Grasa, restos de comida y materiales que no corresponden contaminan el lote. La botella limpia es exactamente lo que se busca."}},{"slug":"residuos-2.s5.p8","orden":8,"grupo":"residuos-2.s5.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si no sé si algo se recicla, conviene ponerlo en los reciclables por las dudas.","razones":[{"id":"r1","texto":"Porque un material equivocado puede contaminar todo el lote"},{"id":"r2","texto":"Porque los centros verdes reciclan absolutamente todo"},{"id":"r3","texto":"Porque separar de más nunca tiene consecuencias"}]},"solucion":{"valor":false,"explicacion":"Puede contaminar el lote y hacer que se pierda material que sí se reciclaba. Mejor averiguar qué acepta el sistema de tu ciudad.","clave":["r1"]}},{"slug":"residuos-2.s5.p9","orden":9,"grupo":"residuos-2.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué se necesita además","cuerpo":["Para que el reciclaje funcione hacen falta varias cosas a la vez: separación correcta en las casas, recolección diferenciada, plantas y cooperativas con condiciones dignas, mercado para el material reciclado y, sobre todo, productos diseñados desde el principio para ser reciclados o reutilizados.","Y, antes que todo eso, producir menos residuos. Reciclar es una herramienta dentro de la jerarquía, no un permiso para consumir sin límite."]},"solucion":{}},{"slug":"residuos-2.s5.p10","orden":10,"grupo":"residuos-2.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto depende de cada persona o del sistema?","grupos":[{"id":"g1","nombre":"Cada persona"},{"id":"g2","nombre":"El sistema"}],"items":[{"id":"i1","texto":"Separar limpio y seco"},{"id":"i2","texto":"Recolección diferenciada"},{"id":"i3","texto":"Averiguar qué acepta el punto verde"},{"id":"i4","texto":"Mercado para el material reciclado"},{"id":"i5","texto":"Comprar menos descartables"},{"id":"i6","texto":"Diseño de envases reciclables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Como viste en el tronco: lo tuyo y lo de todos. El reciclaje necesita las dos columnas."}},{"slug":"residuos-2.s5.p11","orden":11,"grupo":"residuos-2.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país producía 100 mil toneladas de plástico y reciclaba el 9 %. Años después produce 150 mil toneladas y recicla el 15 %. ¿Cuántas mil toneladas NO recicladas tiene ahora?","unidad":"mil toneladas","decimales":1},"solucion":{"valor":127.5,"tolerancia":2.5500000000000003,"explicacion":"Ahora: 150 × 85 ÷ 100 = 127,5 mil t sin reciclar. Antes eran 91. Más reciclaje no compensa si la producción crece más rápido."}},{"slug":"residuos-2.s5.p11.v2","orden":11,"grupo":"residuos-2.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país producía 200 mil toneladas de plástico y reciclaba el 15 %. Años después produce 300 mil toneladas y recicla el 20 %. ¿Cuántas mil toneladas NO recicladas tiene ahora?","unidad":"mil toneladas","decimales":1},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"Ahora: 300 × 80 ÷ 100 = 240 mil t sin reciclar. Antes eran 170. Más reciclaje no compensa si la producción crece más rápido."}},{"slug":"residuos-2.s5.p11.v3","orden":11,"grupo":"residuos-2.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país producía 150 mil toneladas de plástico y reciclaba el 20 %. Años después produce 250 mil toneladas y recicla el 25 %. ¿Cuántas mil toneladas NO recicladas tiene ahora?","unidad":"mil toneladas","decimales":1},"solucion":{"valor":187.5,"tolerancia":3.75,"explicacion":"Ahora: 250 × 75 ÷ 100 = 187,5 mil t sin reciclar. Antes eran 120. Más reciclaje no compensa si la producción crece más rápido."}},{"slug":"residuos-2.s5.p12","orden":12,"grupo":"residuos-2.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas estrategias contra los residuos plásticos según el escalón de la jerarquía, de más alto a más bajo.","items":[{"id":"i1","texto":"Eliminar envases innecesarios"},{"id":"i2","texto":"Sistemas de envases retornables"},{"id":"i3","texto":"Mejorar la separación y el reciclaje"},{"id":"i4","texto":"Quemar plásticos para generar energía"}],"extremos":["Más alto","Más bajo"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las estrategias más efectivas están arriba. El reciclaje es necesario, pero no es la primera línea.","valores":{"i1":"prevenir","i2":"reutilizar","i3":"reciclar","i4":"recuperar energía"}}},{"slug":"residuos-2.s5.p13","orden":13,"grupo":"residuos-2.s5.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota de opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Menos del 10 % del plástico del mundo se recicló."},{"id":"s2","texto":"Por eso separar no sirve para nada."},{"id":"s3","texto":"El reciclaje necesita mercado para el material recuperado."},{"id":"s4","texto":"Si reciclamos más, podemos producir todo el plástico que queramos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reciclar sí, pero dentro de la escalera: reducir primero.","por_opcion":{"s2":"Separar bien es necesario; lo que no alcanza es solo reciclar sin reducir.","s4":"Si la producción crece más rápido que el reciclaje, los residuos igual aumentan."}}},{"slug":"residuos-2.s5.p14","orden":14,"grupo":"residuos-2.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Menos del {{0}} % del plástico producido se recicló; poner en los reciclables algo que no se recicla es reciclaje por {{1}}.","banco":[{"id":"w1","texto":"10"},{"id":"w2","texto":"deseo"},{"id":"w3","texto":"50"},{"id":"w4","texto":"error"},{"id":"w5","texto":"costumbre"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para entender los límites del reciclaje."}}]},{"slug":"residuos-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: reducir, reutilizar, reciclar","bajada_es":"Jerarquía, reducción, reutilización, reciclaje y sus límites, mezclados.","minutos":8,"pasos":[{"slug":"residuos-2.s6.p1","orden":1,"grupo":"residuos-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Reducir, reutilizar, reciclar». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la cantina del colegio","bajada_es":"La cantina de un colegio genera muchísimos descartables. Con los números, aplicá la jerarquía y armá un plan.","minutos":10,"pasos":[{"slug":"residuos-2.s7.p1","orden":1,"grupo":"residuos-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cantina","cuerpo":["En un colegio de 600 estudiantes, la cantina vende por día 300 bebidas en botellitas de PET de 500 ml, 200 alfajores envueltos y 150 cafés en vasos descartables con tapa. Hay un solo tacho para todo en el patio.","La dirección quiere reducir los residuos a la mitad este año. Tiene poco presupuesto, pero puede cambiar reglas de la cantina y hacer campañas."]},"solucion":{}},{"slug":"residuos-2.s7.p2","orden":2,"grupo":"residuos-2.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos envases descartables en total genera la cantina por día (botellas, envoltorios y vasos, sin contar tapas)?","unidad":"envases","decimales":0,"contexto":"300 botellitas, 200 envoltorios y 150 vasos por día."},"solucion":{"valor":650,"tolerancia":13,"explicacion":"300 + 200 + 150 = 650 envases por día. En un año escolar de 180 días, 117.000."}},{"slug":"residuos-2.s7.p3","orden":3,"grupo":"residuos-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el año escolar tiene 180 días, ¿cuántas botellitas de PET se venden por año?","unidad":"botellitas","decimales":0,"contexto":"300 botellitas por día, 180 días de clase."},"solucion":{"valor":54000,"tolerancia":1080,"explicacion":"300 × 180 = 54.000 botellitas por año solo en un colegio."}},{"slug":"residuos-2.s7.p4","orden":4,"grupo":"residuos-2.s7.p4","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas según el escalón de la jerarquía en que están, del más alto al más bajo.","items":[{"id":"i1","texto":"Instalar un bebedero y pedir botellas propias"},{"id":"i2","texto":"Vender café en tazas que se lavan"},{"id":"i3","texto":"Poner tachos separados para PET y cartón"},{"id":"i4","texto":"Seguir con un solo tacho para todo"}],"extremos":["Más alto","Más bajo"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las medidas de arriba eliminan residuos; las de abajo los manejan. El plan tiene que empezar arriba.","valores":{"i1":"prevenir","i2":"reutilizar","i3":"reciclar","i4":"disponer"}}},{"slug":"residuos-2.s7.p5","orden":5,"grupo":"residuos-2.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el bebedero, el 60 % de los estudiantes deja de comprar botellitas. ¿Cuántas botellitas por día se siguen vendiendo? (antes: 300)","unidad":"botellitas","decimales":0},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"300 × 0,4 = 120 botellitas por día. 180 envases menos cada día, sin reciclar nada."}},{"slug":"residuos-2.s7.p5.v2","orden":5,"grupo":"residuos-2.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el bebedero, el 50 % de los estudiantes deja de comprar botellitas. ¿Cuántas botellitas por día se siguen vendiendo? (antes: 300)","unidad":"botellitas","decimales":0},"solucion":{"valor":150,"tolerancia":3,"explicacion":"300 × 0,5 = 150 botellitas por día. 150 envases menos cada día, sin reciclar nada."}},{"slug":"residuos-2.s7.p5.v3","orden":5,"grupo":"residuos-2.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el bebedero, el 70 % de los estudiantes deja de comprar botellitas. ¿Cuántas botellitas por día se siguen vendiendo? (antes: 300)","unidad":"botellitas","decimales":3},"solucion":{"valor":90.00000000000001,"tolerancia":1.8000000000000003,"explicacion":"300 × 0,3 = 90.00000000000001 botellitas por día. 210 envases menos cada día, sin reciclar nada."}},{"slug":"residuos-2.s7.p6","orden":6,"grupo":"residuos-2.s7.p6","tipo":"opcion","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La cantina propone vasos \"compostables\" en lugar de tazas lavables. ¿Qué tener en cuenta?","opciones":[{"id":"o1","texto":"Solo se compostan si hay un sistema que los reciba"},{"id":"o2","texto":"Son siempre mejores que cualquier taza lavable"},{"id":"o3","texto":"Desaparecen solos en el tacho del patio"},{"id":"o4","texto":"Se pueden reciclar junto con las botellas de PET"}]},"solucion":{"clave":["o1"],"explicacion":"Un descartable \"compostable\" sigue siendo descartable. Sin compostaje organizado, la taza lavable es mejor.","por_opcion":{"o3":"Necesitan condiciones de compostaje; en un relleno se comportan casi como basura común."}}},{"slug":"residuos-2.s7.p7","orden":7,"grupo":"residuos-2.s7.p7","tipo":"clasificar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estas propuestas del centro de estudiantes.","grupos":[{"id":"g1","nombre":"Reducen residuos de verdad"},{"id":"g2","nombre":"No reducen o empeoran"}],"items":[{"id":"i1","texto":"Descuento a quien trae su taza"},{"id":"i2","texto":"Regalar un vaso reutilizable nuevo cada mes"},{"id":"i3","texto":"Bebederos en cada piso"},{"id":"i4","texto":"Cambiar las botellas por latitas del mismo tamaño"},{"id":"i5","texto":"Alfajores caseros sin envoltorio individual"},{"id":"i6","texto":"Poner más tachos únicos para que no se desborden"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Reducir es que haya menos envases, no cambiar un descartable por otro ni acumular reutilizables sin usar."}},{"slug":"residuos-2.s7.p8","orden":8,"grupo":"residuos-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La dirección escribe el plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Instalamos bebederos y pedimos que cada estudiante traiga su botella."},{"id":"s2","texto":"Como vamos a reciclar las botellitas, no hace falta vender menos."},{"id":"s3","texto":"Ponemos tachos separados para lo que igual se genere."},{"id":"s4","texto":"Aceptamos en los reciclables los vasos con restos de café, por las dudas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan escolar empieza por prevenir, reutiliza lo que puede y separa bien lo que queda.","por_opcion":{"s2":"Reciclar está por debajo de reducir; el objetivo es que haya menos envases.","s4":"Los restos contaminan el lote: es reciclaje por deseo."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"residuos-3","rama":"residuos","orden":3,"nivel":2,"titulo_es":"Compostar: la mitad de la bolsa","bajada_es":"Casi la mitad de lo que tirás puede volver a ser tierra fértil en pocos meses. La receta, los errores comunes y cómo hacerlo en casa, en el edificio o en la ciudad.","objetivos_es":["Explicar el compostaje como un proceso biológico con oxígeno","Equilibrar materiales secos y húmedos, agua y aire","Decidir qué residuos van a una compostera casera y cuáles no","Diagnosticar y resolver problemas comunes de una compostera","Comparar el compostaje doméstico, comunitario y municipal"],"repasa":["residuos-1","residuos-2","tronco-1"],"requiere_tronco":2,"fuentes":["fao-suelos","epa","ley-1854-basura-cero","unep-food-waste-2024"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-3.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es compostar","bajada_es":"Microbios, lombrices y oxígeno: cómo los restos de comida se convierten en tierra fértil.","minutos":11,"pasos":[{"slug":"residuos-3.s1.p1","orden":1,"grupo":"residuos-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Descomponer con aire","cuerpo":["Compostar es acelerar lo que la naturaleza hace en el suelo de un bosque: descomponer restos orgánicos para convertirlos en un material oscuro, suelto y con olor a tierra húmeda, el compost, que devuelve nutrientes y materia orgánica al suelo.","El trabajo lo hacen bacterias, hongos, lombrices, bichos bolita y muchos otros organismos. La clave es que haya oxígeno: con aire, la descomposición produce sobre todo CO₂, agua y calor, y casi nada de metano. Sin aire, como en un relleno, se producen metano y malos olores."]},"solucion":{}},{"slug":"residuos-3.s1.p2","orden":2,"grupo":"residuos-3.s1.p2","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una cáscara de banana se convierte en compost.","items":[{"id":"i1","texto":"La cáscara entra a la compostera junto con hojas secas"},{"id":"i2","texto":"Bacterias y hongos empiezan a descomponerla"},{"id":"i3","texto":"La pila se calienta por la actividad de los microbios"},{"id":"i4","texto":"Lombrices y bichos siguen triturando y descomponiendo"},{"id":"i5","texto":"Queda un material oscuro con olor a tierra"},{"id":"i6","texto":"La cáscara se evapora con el calor del sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Muchos organismos trabajando en cadena, como los descomponedores de la rama de Animales."}},{"slug":"residuos-3.s1.p3","orden":3,"grupo":"residuos-3.s1.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué una compostera bien manejada casi no produce metano?","opciones":[{"id":"o1","texto":"Porque la descomposición ocurre con oxígeno"},{"id":"o2","texto":"Porque el compost absorbe todo el metano del aire"},{"id":"o3","texto":"Porque los restos de comida no tienen carbono"},{"id":"o4","texto":"Porque la compostera está siempre tapada y sin aire"}]},"solucion":{"clave":["o1"],"explicacion":"Con aire, los microbios producen CO₂; sin aire, metano. Por eso airear es tan importante.","por_opcion":{"o3":"Tienen mucho carbono; lo que cambia es que, con aire, se forma CO₂ y no metano."}}},{"slug":"residuos-3.s1.p4","orden":4,"grupo":"residuos-3.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una pila que se calienta","cuerpo":["En una pila grande y bien armada, la actividad de los microbios puede calentar el interior a 50 o 60 °C durante días. Ese calor acelera la descomposición y elimina muchas semillas de malezas y microbios que causan enfermedades. Después la pila se enfría y entran en acción hongos, lombrices e insectos que terminan el trabajo.","En una compostera casera chica, la temperatura sube menos, y el proceso es más lento, pero funciona igual."]},"solucion":{}},{"slug":"residuos-3.s1.p5","orden":5,"grupo":"residuos-3.s1.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas de una pila de compost.","items":[{"id":"i1","texto":"Se arma la pila con restos secos y húmedos"},{"id":"i2","texto":"Los microbios se multiplican y la pila se calienta"},{"id":"i3","texto":"Se mantiene caliente varios días y se descompone rápido"},{"id":"i4","texto":"Se enfría y entran lombrices y hongos"},{"id":"i5","texto":"Madura y queda compost listo para usar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Calentamiento, fase caliente, enfriamiento y maduración: el ciclo de una pila de compost."}},{"slug":"residuos-3.s1.p6","orden":6,"grupo":"residuos-3.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Que una pila de compost se caliente mucho por dentro es señal de que algo anda mal.","razones":[{"id":"r1","texto":"Porque indica mucha actividad de los microbios"},{"id":"r2","texto":"Porque el compost solo funciona en frío"},{"id":"r3","texto":"Porque el calor viene de un incendio"}]},"solucion":{"valor":false,"explicacion":"Es una buena señal: muestra mucha actividad de microbios. El calor acelera el proceso y elimina semillas y patógenos.","clave":["r1"]}},{"slug":"residuos-3.s1.p7","orden":7,"grupo":"residuos-3.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué se obtiene","cuerpo":["Del compostaje se obtiene compost: un abono que mejora la estructura del suelo, retiene agua y alimenta la vida del suelo, como viste en la rama de Aire y Suelo. Y se reduce mucho el volumen: los restos pierden agua y se descomponen, así que el compost final pesa y ocupa bastante menos que lo que entró."]},"solucion":{}},{"slug":"residuos-3.s1.p8","orden":8,"grupo":"residuos-3.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Entran 100 kg de restos orgánicos a una compostera. Si el compost final pesa el 30 % de lo que entró, ¿cuántos kg de compost se obtienen?","unidad":"kg","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"100 × 30 ÷ 100 = 30 kg. El resto se fue como agua evaporada y CO₂ de la respiración de los microbios."}},{"slug":"residuos-3.s1.p8.v2","orden":8,"grupo":"residuos-3.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Entran 60 kg de restos orgánicos a una compostera. Si el compost final pesa el 25 % de lo que entró, ¿cuántos kg de compost se obtienen?","unidad":"kg","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"60 × 25 ÷ 100 = 15 kg. El resto se fue como agua evaporada y CO₂ de la respiración de los microbios."}},{"slug":"residuos-3.s1.p8.v3","orden":8,"grupo":"residuos-3.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Entran 200 kg de restos orgánicos a una compostera. Si el compost final pesa el 35 % de lo que entró, ¿cuántos kg de compost se obtienen?","unidad":"kg","decimales":0},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"200 × 35 ÷ 100 = 70 kg. El resto se fue como agua evaporada y CO₂ de la respiración de los microbios."}},{"slug":"residuos-3.s1.p9","orden":9,"grupo":"residuos-3.s1.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada organismo con su papel en la compostera.","izquierda":[{"id":"a1","texto":"Bacterias"},{"id":"a2","texto":"Hongos"},{"id":"a3","texto":"Lombrices"},{"id":"a4","texto":"Bichos bolita"}],"derecha":[{"id":"b1","texto":"Inician la descomposición y calientan la pila"},{"id":"b2","texto":"Descomponen materiales duros como hojas y cartón"},{"id":"b3","texto":"Trituran y mezclan, y producen humus"},{"id":"b4","texto":"Fragmentan restos en trozos más chicos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una compostera es un ecosistema en miniatura."}},{"slug":"residuos-3.s1.p10","orden":10,"grupo":"residuos-3.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios tiene compostar en casa? Marcá todos.","opciones":[{"id":"o1","texto":"Se reduce mucho la basura que va al relleno"},{"id":"o2","texto":"Se evita metano del relleno"},{"id":"o3","texto":"Se obtiene abono para plantas y huertas"},{"id":"o4","texto":"Mejora la vida del suelo donde se usa"},{"id":"o5","texto":"Genera electricidad para la casa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Menos basura, menos metano, mejor suelo."}},{"slug":"residuos-3.s1.p11","orden":11,"grupo":"residuos-3.s1.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto ocurre en una compostera bien manejada o en un relleno sanitario?","grupos":[{"id":"g1","nombre":"Compostera bien manejada"},{"id":"g2","nombre":"Relleno sanitario"}],"items":[{"id":"i1","texto":"Descomposición con oxígeno"},{"id":"i2","texto":"Descomposición sin oxígeno"},{"id":"i3","texto":"Olor a tierra húmeda"},{"id":"i4","texto":"Producción de metano"},{"id":"i5","texto":"Se obtiene abono"},{"id":"i6","texto":"Lixiviados que hay que tratar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los mismos restos, dos destinos muy distintos."}},{"slug":"residuos-3.s1.p12","orden":12,"grupo":"residuos-3.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El compost se forma por la acción de microbios y otros organismos."},{"id":"s2","texto":"Compostar produce más metano que mandar los restos al relleno."},{"id":"s3","texto":"El compost mejora la estructura del suelo."},{"id":"s4","texto":"El compost final pesa más que los restos que entraron."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Compostar es devolver al suelo lo que vino del suelo.","por_opcion":{"s2":"Con aire, produce mucho menos metano que un relleno.","s4":"Pesa bastante menos: se pierde agua y CO₂."}}},{"slug":"residuos-3.s1.p13","orden":13,"grupo":"residuos-3.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Compostar es descomponer restos orgánicos con {{0}}; así se produce poco {{1}} y se obtiene un abono llamado {{2}}.","banco":[{"id":"w1","texto":"oxígeno"},{"id":"w2","texto":"metano"},{"id":"w3","texto":"compost"},{"id":"w4","texto":"nitrógeno"},{"id":"w5","texto":"vapor"},{"id":"w6","texto":"fertilizante químico"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La definición de compostar, resumida en una línea."}},{"slug":"residuos-3.s1.p14","orden":14,"grupo":"residuos-3.s1.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá a qué temperatura puede llegar el interior de una pila de compost grande y activa.","min":10,"max":100,"paso":5,"unidad":"°C","escala":"lineal"},"solucion":{"valor":60,"banda":"lineal","explicacion":"Entre 50 y 60 °C, e incluso algo más. Todo ese calor lo producen los microbios al trabajar."}}]},{"slug":"residuos-3.s2","orden":2,"tipo":"leccion","titulo_es":"La receta: secos, húmedos, agua y aire","bajada_es":"El equilibrio de materiales que hace funcionar una compostera.","minutos":11,"pasos":[{"slug":"residuos-3.s2.p1","orden":1,"grupo":"residuos-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Secos y húmedos","cuerpo":["Una compostera necesita dos tipos de materiales. Los húmedos (o \"verdes\") son ricos en nitrógeno: restos de frutas y verduras, yerba, café, pasto recién cortado. Los secos (o \"marrones\") son ricos en carbono: hojas secas, ramitas, aserrín sin tratar, cartón y papel sin tinta de color.","Una regla práctica es poner, en volumen, entre dos y tres partes de secos por cada parte de húmedos. Los secos aportan estructura y aire; los húmedos, nitrógeno y humedad."],"destacado":{"valor":"2-3 : 1","texto":"partes de secos por cada parte de húmedos, en volumen, es una buena regla práctica."}},"solucion":{}},{"slug":"residuos-3.s2.p2","orden":2,"grupo":"residuos-3.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un material seco (marrón) o húmedo (verde)?","grupos":[{"id":"g1","nombre":"Seco (marrón)"},{"id":"g2","nombre":"Húmedo (verde)"}],"items":[{"id":"i1","texto":"Hojas secas"},{"id":"i2","texto":"Cáscaras de verdura"},{"id":"i3","texto":"Cartón cortado"},{"id":"i4","texto":"Yerba usada"},{"id":"i5","texto":"Aserrín sin tratar"},{"id":"i6","texto":"Pasto recién cortado"},{"id":"i7","texto":"Ramitas"},{"id":"i8","texto":"Restos de fruta"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Los dos grupos se complementan. Casi todos los problemas vienen de tener demasiado de uno."}},{"slug":"residuos-3.s2.p3","orden":3,"grupo":"residuos-3.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si agregás 10 litros de restos húmedos por semana y querés mantener 2 partes de secos por cada parte de húmedos, ¿cuántos litros de secos necesitás?","unidad":"litros","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"10 × 2 = 20 litros de secos por semana. Tener una bolsa de hojas secas a mano junto a la compostera facilita mantener la proporción."}},{"slug":"residuos-3.s2.p3.v2","orden":3,"grupo":"residuos-3.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si agregás 6 litros de restos húmedos por semana y querés mantener 3 partes de secos por cada parte de húmedos, ¿cuántos litros de secos necesitás?","unidad":"litros","decimales":0},"solucion":{"valor":18,"tolerancia":0.5,"explicacion":"6 × 3 = 18 litros de secos por semana. Tener una bolsa de hojas secas a mano junto a la compostera facilita mantener la proporción."}},{"slug":"residuos-3.s2.p3.v3","orden":3,"grupo":"residuos-3.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si agregás 15 litros de restos húmedos por semana y querés mantener 2 partes de secos por cada parte de húmedos, ¿cuántos litros de secos necesitás?","unidad":"litros","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"15 × 2 = 30 litros de secos por semana. Tener una bolsa de hojas secas a mano junto a la compostera facilita mantener la proporción."}},{"slug":"residuos-3.s2.p4","orden":4,"grupo":"residuos-3.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua y aire","cuerpo":["La humedad ideal es parecida a la de una esponja escurrida: si se aprieta un puñado, apenas gotea. Muy seco, los microbios se frenan; muy mojado, el aire no entra y aparecen malos olores.","El aire se asegura con materiales secos que dejan huecos, revolviendo cada tanto y evitando compactar. Trozar los restos en pedazos más chicos acelera todo, porque aumenta la superficie donde trabajan los microbios."]},"solucion":{}},{"slug":"residuos-3.s2.p5","orden":5,"grupo":"residuos-3.s2.p5","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo tiene que estar la humedad de una compostera?","opciones":[{"id":"o1","texto":"Como una esponja escurrida"},{"id":"o2","texto":"Completamente seca, como arena"},{"id":"o3","texto":"Encharcada, para que se descomponga rápido"},{"id":"o4","texto":"Siempre cubierta con agua"}]},"solucion":{"clave":["o1"],"explicacion":"Húmeda pero no mojada: los microbios necesitan agua y aire al mismo tiempo.","por_opcion":{"o3":"Encharcada falta aire y aparecen malos olores."}}},{"slug":"residuos-3.s2.p6","orden":6,"grupo":"residuos-3.s2.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ingrediente de la receta con su función.","izquierda":[{"id":"a1","texto":"Materiales secos"},{"id":"a2","texto":"Materiales húmedos"},{"id":"a3","texto":"Revolver"},{"id":"a4","texto":"Trozar los restos"}],"derecha":[{"id":"b1","texto":"Aportan carbono, estructura y aire"},{"id":"b2","texto":"Aportan nitrógeno y humedad"},{"id":"b3","texto":"Mete aire en la pila"},{"id":"b4","texto":"Acelera la descomposición"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ingredientes de una compostera que funciona bien."}},{"slug":"residuos-3.s2.p7","orden":7,"grupo":"residuos-3.s2.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué pasa si solo se agregan restos húmedos.","items":[{"id":"i1","texto":"Se agregan solo restos de cocina, sin secos"},{"id":"i2","texto":"La mezcla se compacta y se moja"},{"id":"i3","texto":"El aire no llega al interior"},{"id":"i4","texto":"Los microbios trabajan sin oxígeno"},{"id":"i5","texto":"Aparecen malos olores"},{"id":"i6","texto":"La compostera se seca por completo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El error más común: faltan secos. La solución es sumar hojas o cartón y revolver."}},{"slug":"residuos-3.s2.p8","orden":8,"grupo":"residuos-3.s2.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Trozar los restos en pedazos chicos hace que se compostan más rápido.","razones":[{"id":"r1","texto":"Porque aumenta la superficie donde trabajan los microbios"},{"id":"r2","texto":"Porque los microbios solo comen pedazos grandes"},{"id":"r3","texto":"Porque trozar evita que se descompongan"}]},"solucion":{"valor":true,"explicacion":"Aumenta la superficie donde trabajan los microbios. Una cáscara entera de zapallo tarda mucho más que trozada.","clave":["r1"]}},{"slug":"residuos-3.s2.p9","orden":9,"grupo":"residuos-3.s2.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Armar por capas","cuerpo":["Una forma práctica de empezar es armar capas: una base de ramitas para que circule aire, una capa de secos, los restos húmedos encima y, siempre, una tapa de secos para cubrirlos. Cada vez que se agregan restos, se cubren con secos. Así se evitan moscas y olores."]},"solucion":{}},{"slug":"residuos-3.s2.p10","orden":10,"grupo":"residuos-3.s2.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo se arma una compostera nueva.","items":[{"id":"i1","texto":"Poner una base de ramitas en el fondo"},{"id":"i2","texto":"Agregar una capa de hojas secas"},{"id":"i3","texto":"Sumar los restos húmedos de la cocina"},{"id":"i4","texto":"Cubrir los húmedos con otra capa de secos"},{"id":"i5","texto":"Humedecer si hace falta y revolver cada tanto"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La tapa de secos es el secreto para evitar moscas."}},{"slug":"residuos-3.s2.p11","orden":11,"grupo":"residuos-3.s2.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que la compostera funcione rápido? Marcá todo.","opciones":[{"id":"o1","texto":"Mantener la proporción de secos y húmedos"},{"id":"o2","texto":"Trozar los restos"},{"id":"o3","texto":"Revolver cada una o dos semanas"},{"id":"o4","texto":"Humedad como de esponja escurrida"},{"id":"o5","texto":"Apretar todo bien fuerte para que entre más"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Compactar saca el aire. Lo que ayuda es mezclar, airear y equilibrar."}},{"slug":"residuos-3.s2.p12","orden":12,"grupo":"residuos-3.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Cubrí siempre los restos de cocina con hojas secas."},{"id":"s2","texto":"Poné solo restos de cocina, sin nada seco, para que sea más rápido."},{"id":"s3","texto":"Revolvé cada tanto para airear."},{"id":"s4","texto":"Mantené la compostera encharcada para que no se seque."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Equilibrio de secos y húmedos, agua y aire: toda la receta.","por_opcion":{"s2":"Sin secos falta aire y aparecen olores.","s4":"Encharcada falta oxígeno; tiene que estar como esponja escurrida."}}},{"slug":"residuos-3.s2.p13","orden":13,"grupo":"residuos-3.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los materiales {{0}} aportan carbono y aire; los {{1}} aportan nitrógeno; y conviene poner unas dos o tres partes de los primeros por cada {{2}} de los segundos.","banco":[{"id":"w1","texto":"secos"},{"id":"w2","texto":"húmedos"},{"id":"w3","texto":"parte"},{"id":"w4","texto":"metálicos"},{"id":"w5","texto":"plásticos"},{"id":"w6","texto":"litro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La proporción de la receta del compost, en una sola línea."}},{"slug":"residuos-3.s2.p14","orden":14,"grupo":"residuos-3.s2.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos materiales según cuánto tardan en descomponerse, de más rápido a más lento.","items":[{"id":"i1","texto":"Restos de lechuga"},{"id":"i2","texto":"Cáscaras de naranja"},{"id":"i3","texto":"Hojas secas enteras"},{"id":"i4","texto":"Ramas gruesas"}],"extremos":["Más rápido","Más lento"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo tierno y húmedo va rápido; lo leñoso, lento. Por eso conviene trozar lo duro.","valores":{"i1":"días a semanas","i2":"semanas","i3":"meses","i4":"muchos meses o años"}}}]},{"slug":"residuos-3.s3","orden":3,"tipo":"leccion","titulo_es":"Qué va y qué no","bajada_es":"Qué residuos se pueden compostar en casa, cuáles conviene evitar y por qué.","minutos":11,"pasos":[{"slug":"residuos-3.s3.p1","orden":1,"grupo":"residuos-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que sí","cuerpo":["En una compostera casera van muy bien: restos crudos de frutas y verduras, cáscaras de huevo trituradas, yerba, saquitos de té y borra de café, hojas secas, pasto, restos de poda chicos, cartón y papel sin tinta de color ni plastificado, servilletas de papel usadas."]},"solucion":{}},{"slug":"residuos-3.s3.p2","orden":2,"grupo":"residuos-3.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que conviene evitar","cuerpo":["En una compostera casera conviene no poner carne, pescado, huesos, lácteos ni restos con mucho aceite: atraen roedores y moscas y generan olores. Tampoco heces de perros o gatos, que pueden tener microbios peligrosos; plantas enfermas o con plagas; ni cenizas de carbón o de cigarrillos.","Y nunca plásticos, vidrio, metales o pañales: no son orgánicos. Los envases \"compostables\" solo conviene ponerlos si se sabe que se degradan en compostaje casero, porque muchos necesitan compostaje industrial."]},"solucion":{}},{"slug":"residuos-3.s3.p3","orden":3,"grupo":"residuos-3.s3.p3","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Va a la compostera casera o no?","grupos":[{"id":"g1","nombre":"Sí va"},{"id":"g2","nombre":"No va"}],"items":[{"id":"i1","texto":"Borra de café"},{"id":"i2","texto":"Restos de asado"},{"id":"i3","texto":"Cáscaras de huevo trituradas"},{"id":"i4","texto":"Heces del perro"},{"id":"i5","texto":"Hojas secas"},{"id":"i6","texto":"Un pañal"},{"id":"i7","texto":"Cartón sin tinta"},{"id":"i8","texto":"Una bolsa de plástico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Vegetales crudos y secos, sí. Carne, heces, pañales y plásticos, no."}},{"slug":"residuos-3.s3.p4","orden":4,"grupo":"residuos-3.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene no poner restos de carne en una compostera casera?","opciones":[{"id":"o1","texto":"Porque atraen roedores y producen malos olores"},{"id":"o2","texto":"Porque la carne no tiene materia orgánica"},{"id":"o3","texto":"Porque la carne es un residuo peligroso por ley"},{"id":"o4","texto":"Porque la carne se convierte en plástico"}]},"solucion":{"clave":["o1"],"explicacion":"En composteras industriales, con altas temperaturas y control, sí se pueden tratar. En casa conviene evitarla.","por_opcion":{"o3":"No es peligroso por ley: el problema práctico son los olores y los roedores."}}},{"slug":"residuos-3.s3.p5","orden":5,"grupo":"residuos-3.s3.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las heces de perros y gatos son un buen abono para la compostera de la huerta.","razones":[{"id":"r1","texto":"Porque pueden tener parásitos y microbios peligrosos"},{"id":"r2","texto":"Porque no tienen materia orgánica"},{"id":"r3","texto":"Porque aceleran demasiado el compost"}]},"solucion":{"valor":false,"explicacion":"Pueden contener parásitos y microbios que causan enfermedades. No se ponen en la compostera de alimentos.","clave":["r1"]}},{"slug":"residuos-3.s3.p6","orden":6,"grupo":"residuos-3.s3.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos papeles y cartones se pueden compostar? Marcá todos.","opciones":[{"id":"o1","texto":"Cartón de huevos"},{"id":"o2","texto":"Servilletas de papel usadas"},{"id":"o3","texto":"Papel de diario en pequeñas cantidades"},{"id":"o4","texto":"Papel plastificado de revistas brillantes"},{"id":"o5","texto":"Vasos de cartón con capa plástica"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Papeles simples sí; los que tienen plástico o recubrimientos, no."}},{"slug":"residuos-3.s3.p7","orden":7,"grupo":"residuos-3.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Envases compostables","cuerpo":["Algunos envases dicen \"compostable\". Muchos de ellos están certificados para compostaje industrial, donde las temperaturas altas y el tiempo controlado los descomponen. En una compostera casera pueden tardar muchísimo o no descomponerse del todo. Por eso conviene fijarse si dice específicamente \"compostable en casa\"."]},"solucion":{}},{"slug":"residuos-3.s3.p8","orden":8,"grupo":"residuos-3.s3.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué pasa si ponés un vaso \"compostable industrial\" en tu compostera casera.","items":[{"id":"i1","texto":"Ponés el vaso en la compostera del balcón"},{"id":"i2","texto":"La temperatura no sube tanto como en una planta industrial"},{"id":"i3","texto":"El vaso casi no se degrada en meses"},{"id":"i4","texto":"Aparece entero cuando sacás el compost"},{"id":"i5","texto":"El vaso se convierte en abono en una semana"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Compostable no siempre significa compostable en casa. La etiqueta lo tiene que decir."}},{"slug":"residuos-3.s3.p9","orden":9,"grupo":"residuos-3.s3.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada residuo con su mejor destino.","izquierda":[{"id":"a1","texto":"Cáscaras de papa"},{"id":"a2","texto":"Restos de pollo"},{"id":"a3","texto":"Botella de PET"},{"id":"a4","texto":"Pañal"}],"derecha":[{"id":"b1","texto":"Compostera"},{"id":"b2","texto":"Basura o compostaje municipal si lo acepta"},{"id":"b3","texto":"Reciclables"},{"id":"b4","texto":"Basura común"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada residuo tiene su lugar. La compostera recibe lo vegetal y crudo."}},{"slug":"residuos-3.s3.p10","orden":10,"grupo":"residuos-3.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 15 kg de restos orgánicos por semana. Si el 70 % son restos vegetales que pueden ir a la compostera casera, ¿cuántos kg por semana puede compostar?","unidad":"kg","decimales":1},"solucion":{"valor":10.5,"tolerancia":0.21,"explicacion":"15 × 70 ÷ 100 = 10,5 kg por semana. El resto (carne, lácteos) necesita otro destino o un compostaje municipal que lo acepte."}},{"slug":"residuos-3.s3.p10.v2","orden":10,"grupo":"residuos-3.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 10 kg de restos orgánicos por semana. Si el 80 % son restos vegetales que pueden ir a la compostera casera, ¿cuántos kg por semana puede compostar?","unidad":"kg","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"10 × 80 ÷ 100 = 8 kg por semana. El resto (carne, lácteos) necesita otro destino o un compostaje municipal que lo acepte."}},{"slug":"residuos-3.s3.p10.v3","orden":10,"grupo":"residuos-3.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 20 kg de restos orgánicos por semana. Si el 60 % son restos vegetales que pueden ir a la compostera casera, ¿cuántos kg por semana puede compostar?","unidad":"kg","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"20 × 60 ÷ 100 = 12 kg por semana. El resto (carne, lácteos) necesita otro destino o un compostaje municipal que lo acepte."}},{"slug":"residuos-3.s3.p11","orden":11,"grupo":"residuos-3.s3.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos residuos del más fácil al más difícil de compostar en casa.","items":[{"id":"i1","texto":"Restos de lechuga"},{"id":"i2","texto":"Cáscaras de huevo trituradas"},{"id":"i3","texto":"Vaso compostable industrial"},{"id":"i4","texto":"Hueso de asado"}],"extremos":["Más fácil","Más difícil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"De lo vegetal y tierno a lo que requiere condiciones industriales.","valores":{"i1":"muy fácil","i2":"fácil","i3":"difícil en casa","i4":"no recomendado en casa"}}},{"slug":"residuos-3.s3.p12","orden":12,"grupo":"residuos-3.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta lista pegada en una compostera y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Sí: yerba, café y cáscaras."},{"id":"s2","texto":"Sí: restos de asado y huesos."},{"id":"s3","texto":"Sí: hojas secas y cartón sin tinta."},{"id":"s4","texto":"Sí: cualquier envase que diga \"biodegradable\"."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una buena lista evita la mayoría de los problemas.","por_opcion":{"s2":"En casa atraen roedores y generan olores.","s4":"Muchos no se degradan en una compostera casera."}}},{"slug":"residuos-3.s3.p13","orden":13,"grupo":"residuos-3.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"A la compostera casera van restos {{0}} y secos; se evitan la {{1}} y los lácteos; y muchos envases compostables necesitan compostaje {{2}}.","banco":[{"id":"w1","texto":"vegetales"},{"id":"w2","texto":"carne"},{"id":"w3","texto":"industrial"},{"id":"w4","texto":"plásticos"},{"id":"w5","texto":"yerba"},{"id":"w6","texto":"casero"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La regla de qué va y qué no, en una línea."}},{"slug":"residuos-3.s3.p14","orden":14,"grupo":"residuos-3.s3.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los restos orgánicos de una casa típica son vegetales aptos para compostera casera.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"La mayor parte, en muchas casas alrededor de tres cuartos. Carne, huesos y lácteos suelen ser una parte menor."}}]},{"slug":"residuos-3.s4","orden":4,"tipo":"leccion","titulo_es":"Problemas y soluciones","bajada_es":"Olor, moscas, bichos y un compost que no avanza: cómo diagnosticar y arreglar una compostera.","minutos":11,"pasos":[{"slug":"residuos-3.s4.p1","orden":1,"grupo":"residuos-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Diagnosticar","cuerpo":["La mayoría de los problemas de una compostera tienen causas simples. El olor a podrido o a amoníaco indica exceso de húmedos o falta de aire. Las moscas aparecen cuando los restos quedan destapados. Si no pasa nada durante semanas, suele faltar humedad o haber demasiados secos. Los roedores llegan si hay carne, lácteos o comida cocida."]},"solucion":{}},{"slug":"residuos-3.s4.p2","orden":2,"grupo":"residuos-3.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada síntoma con su causa más probable.","izquierda":[{"id":"a1","texto":"Olor a podrido"},{"id":"a2","texto":"Moscas"},{"id":"a3","texto":"No se descompone nada"},{"id":"a4","texto":"Roedores"}],"derecha":[{"id":"b1","texto":"Exceso de húmedos y falta de aire"},{"id":"b2","texto":"Restos de cocina sin cubrir"},{"id":"b3","texto":"Falta de humedad o exceso de secos"},{"id":"b4","texto":"Restos de carne o comida cocida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada síntoma señala una causa, como un buen diagnóstico."}},{"slug":"residuos-3.s4.p3","orden":3,"grupo":"residuos-3.s4.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La compostera huele a podrido. ¿Qué conviene hacer?","opciones":[{"id":"o1","texto":"Agregar secos y revolver para meter aire"},{"id":"o2","texto":"Agregar más restos de cocina"},{"id":"o3","texto":"Regarla con mucha agua para lavar el olor"},{"id":"o4","texto":"Taparla herméticamente para que no salga el olor"}]},"solucion":{"clave":["o1"],"explicacion":"Olor es falta de aire y exceso de humedad. Secos y revolver lo resuelven en pocos días.","por_opcion":{"o3":"Más agua empeora el problema: falta aire."}}},{"slug":"residuos-3.s4.p4","orden":4,"grupo":"residuos-3.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Seco y lento","cuerpo":["Si la compostera está seca y fría, los microbios trabajan muy lento. Conviene agregar agua de a poco, sumar restos húmedos y revolver. En invierno todo es más lento: es normal.","Los pequeños mosquitos de la fruta suelen aparecer cuando las cáscaras quedan expuestas; se evitan cubriendo siempre con secos."]},"solucion":{}},{"slug":"residuos-3.s4.p5","orden":5,"grupo":"residuos-3.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué solución corresponde a cada problema?","grupos":[{"id":"g1","nombre":"Agregar secos y airear"},{"id":"g2","nombre":"Agregar agua y húmedos"},{"id":"g3","nombre":"Cubrir mejor los restos"}],"items":[{"id":"i1","texto":"Olor fuerte"},{"id":"i2","texto":"Todo seco y sin cambios"},{"id":"i3","texto":"Moscas y mosquitos"},{"id":"i4","texto":"Mezcla chorreando líquido"},{"id":"i5","texto":"Pila fría hace semanas en verano"},{"id":"i6","texto":"Cáscaras a la vista"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres soluciones para casi todos los problemas: secos y aire, agua y húmedos, o tapar."}},{"slug":"residuos-3.s4.p6","orden":6,"grupo":"residuos-3.s4.p6","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se resuelve una compostera con olor.","items":[{"id":"i1","texto":"Se detecta olor a podrido"},{"id":"i2","texto":"Se agregan hojas secas o cartón"},{"id":"i3","texto":"Se revuelve para meter aire"},{"id":"i4","texto":"Los microbios vuelven a trabajar con oxígeno"},{"id":"i5","texto":"El olor desaparece en pocos días"},{"id":"i6","texto":"Se agrega carne para equilibrar el olor"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un problema frecuente con una solución simple."}},{"slug":"residuos-3.s4.p7","orden":7,"grupo":"residuos-3.s4.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si aparecen lombrices y bichos bolita en la compostera, hay que eliminarlos.","razones":[{"id":"r1","texto":"Porque ayudan a descomponer: son señal de buena salud"},{"id":"r2","texto":"Porque arruinan el compost"},{"id":"r3","texto":"Porque transmiten enfermedades a las plantas"}]},"solucion":{"valor":false,"explicacion":"Son aliados: descomponen y mezclan los restos. Su presencia es señal de una compostera sana.","clave":["r1"]}},{"slug":"residuos-3.s4.p8","orden":8,"grupo":"residuos-3.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuándo está listo","cuerpo":["El compost está listo cuando no se reconocen los restos originales (salvo algún trozo duro), tiene color oscuro, olor a tierra de bosque y está a temperatura ambiente. En una compostera casera suele tardar de tres a seis meses. Si hay trozos sin descomponer, se tamizan y vuelven a la compostera."]},"solucion":{}},{"slug":"residuos-3.s4.p9","orden":9,"grupo":"residuos-3.s4.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales indican que el compost está listo? Marcá todas.","opciones":[{"id":"o1","texto":"Color oscuro"},{"id":"o2","texto":"Olor a tierra de bosque"},{"id":"o3","texto":"No se reconocen los restos originales"},{"id":"o4","texto":"Está a temperatura ambiente"},{"id":"o5","texto":"Olor fuerte a podrido"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Oscuro, fresco, con olor a tierra y sin restos reconocibles."}},{"slug":"residuos-3.s4.p10","orden":10,"grupo":"residuos-3.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el compost tarda unos 4 meses en estar listo, ¿aproximadamente cuántas semanas son? (Usá 4,3 semanas por mes) Redondeá al entero.","unidad":"semanas","decimales":0},"solucion":{"valor":17,"tolerancia":1,"explicacion":"4 × 4,3 ≈ 17 semanas. Mientras tanto, conviene tener una segunda compostera o un segundo compartimento para seguir agregando restos."}},{"slug":"residuos-3.s4.p10.v2","orden":10,"grupo":"residuos-3.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el compost tarda unos 3 meses en estar listo, ¿aproximadamente cuántas semanas son? (Usá 4,3 semanas por mes) Redondeá al entero.","unidad":"semanas","decimales":0},"solucion":{"valor":13,"tolerancia":1,"explicacion":"3 × 4,3 ≈ 13 semanas. Mientras tanto, conviene tener una segunda compostera o un segundo compartimento para seguir agregando restos."}},{"slug":"residuos-3.s4.p10.v3","orden":10,"grupo":"residuos-3.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el compost tarda unos 6 meses en estar listo, ¿aproximadamente cuántas semanas son? (Usá 4,3 semanas por mes) Redondeá al entero.","unidad":"semanas","decimales":0},"solucion":{"valor":26,"tolerancia":1,"explicacion":"6 × 4,3 ≈ 26 semanas. Mientras tanto, conviene tener una segunda compostera o un segundo compartimento para seguir agregando restos."}},{"slug":"residuos-3.s4.p11","orden":11,"grupo":"residuos-3.s4.p11","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená qué hacer para cosechar el compost.","items":[{"id":"i1","texto":"Dejar de agregar restos a esa compostera"},{"id":"i2","texto":"Esperar a que madure unas semanas"},{"id":"i3","texto":"Sacar el compost de abajo, que es el más maduro"},{"id":"i4","texto":"Tamizar y devolver los trozos grandes"},{"id":"i5","texto":"Usar el compost en macetas o en la huerta"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cosechar bien permite aprovechar todo y reiniciar el ciclo."}},{"slug":"residuos-3.s4.p12","orden":12,"grupo":"residuos-3.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diagnóstico y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Hay moscas porque dejamos las cáscaras sin tapar."},{"id":"s2","texto":"Huele mal porque le falta agua: vamos a regarla mucho."},{"id":"s3","texto":"Hay lombrices, buena señal."},{"id":"s4","texto":"Aparecieron ratas; debe ser por las hojas secas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Diagnosticar bien evita soluciones que empeoran el problema.","por_opcion":{"s2":"El olor suele ser exceso de humedad y falta de aire.","s4":"Las ratas suelen venir por carne, lácteos o comida cocida."}}},{"slug":"residuos-3.s4.p13","orden":13,"grupo":"residuos-3.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Si hay olor, faltan {{0}} y aire; si hay moscas, hay que {{1}} los restos; y el compost listo huele a {{2}}.","banco":[{"id":"w1","texto":"secos"},{"id":"w2","texto":"cubrir"},{"id":"w3","texto":"tierra"},{"id":"w4","texto":"húmedos"},{"id":"w5","texto":"regar"},{"id":"w6","texto":"amoníaco"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para resolver problemas de la compostera."}},{"slug":"residuos-3.s4.p14","orden":14,"grupo":"residuos-3.s4.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos problemas según qué tan fácil es resolverlos, de más fácil a más difícil.","items":[{"id":"i1","texto":"Moscas por restos sin tapar"},{"id":"i2","texto":"Olor por exceso de húmedos"},{"id":"i3","texto":"Compost seco que no avanza"},{"id":"i4","texto":"Roedores por restos de carne"}],"extremos":["Más fácil","Más difícil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Casi todos los problemas tienen solución; cuanto antes se detectan, más fácil.","valores":{"i1":"se resuelve en un día","i2":"se resuelve en días","i3":"se resuelve en semanas","i4":"requiere cambiar lo que se agrega y proteger la compostera"}}}]},{"slug":"residuos-3.s5","orden":5,"tipo":"leccion","titulo_es":"Compostar a escala","bajada_es":"Composteras de balcón, comunitarias y plantas municipales: cómo el compostaje puede cambiar la basura de una ciudad.","minutos":11,"pasos":[{"slug":"residuos-3.s5.p1","orden":1,"grupo":"residuos-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sin patio también","cuerpo":["Sin patio se puede compostar en un balcón con una compostera chica o con un vermicompostador, un sistema de cajas donde lombrices, como la lombriz roja, transforman los restos en un abono muy rico llamado lombricompuesto. También se pueden llevar los restos a composteras comunitarias de plazas, escuelas o huertas del barrio."]},"solucion":{}},{"slug":"residuos-3.s5.p2","orden":2,"grupo":"residuos-3.s5.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué opción de compostaje conviene en cada situación?","grupos":[{"id":"g1","nombre":"Compostera en el patio"},{"id":"g2","nombre":"Vermicompostador en el balcón"},{"id":"g3","nombre":"Compostera comunitaria"}],"items":[{"id":"i1","texto":"Casa con jardín amplio"},{"id":"i2","texto":"Departamento sin patio"},{"id":"i3","texto":"Edificio con vecinos interesados"},{"id":"i4","texto":"Familia con huerta en el fondo"},{"id":"i5","texto":"Persona que genera pocos restos"},{"id":"i6","texto":"Escuela con un espacio verde"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Hay una opción para casi cualquier vivienda."}},{"slug":"residuos-3.s5.p3","orden":3,"grupo":"residuos-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Compostaje municipal","cuerpo":["Algunas ciudades recolectan los residuos orgánicos por separado y los llevan a plantas de compostaje. A esa escala se pueden tratar también restos de comida cocida, carne y poda, porque se controla la temperatura y el proceso. El compost resultante se usa en plazas, viveros o se vende.","Como los orgánicos son casi la mitad de la basura, separar y compostar a escala municipal puede reducir muchísimo lo que va al relleno."]},"solucion":{}},{"slug":"residuos-3.s5.p4","orden":4,"grupo":"residuos-3.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un sistema de compostaje municipal.","items":[{"id":"i1","texto":"Los vecinos separan los orgánicos en casa"},{"id":"i2","texto":"Un camión los recolecta por separado"},{"id":"i3","texto":"Llegan a una planta de compostaje"},{"id":"i4","texto":"Se compostan con control de temperatura"},{"id":"i5","texto":"El compost se usa en plazas y huertas"},{"id":"i6","texto":"Los orgánicos se entierran junto con el resto de la basura"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Separación en origen, recolección diferenciada y tratamiento: el mismo esquema del reciclaje, aplicado a lo orgánico."}},{"slug":"residuos-3.s5.p5","orden":5,"grupo":"residuos-3.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad genera 500 toneladas de basura por día; el 45 % son orgánicos. Si logra compostar el 30 % de esos orgánicos, ¿cuántas toneladas por día deja de mandar al relleno?","unidad":"toneladas","decimales":1},"solucion":{"valor":67.5,"tolerancia":1.35,"explicacion":"500 × 45 % = 225 t de orgánicos; × 30 % = 67,5 t por día que no van al relleno ni producen metano allí."}},{"slug":"residuos-3.s5.p5.v2","orden":5,"grupo":"residuos-3.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad genera 1000 toneladas de basura por día; el 50 % son orgánicos. Si logra compostar el 20 % de esos orgánicos, ¿cuántas toneladas por día deja de mandar al relleno?","unidad":"toneladas","decimales":1},"solucion":{"valor":100,"tolerancia":2,"explicacion":"1000 × 50 % = 500 t de orgánicos; × 20 % = 100 t por día que no van al relleno ni producen metano allí."}},{"slug":"residuos-3.s5.p5.v3","orden":5,"grupo":"residuos-3.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad genera 200 toneladas de basura por día; el 40 % son orgánicos. Si logra compostar el 50 % de esos orgánicos, ¿cuántas toneladas por día deja de mandar al relleno?","unidad":"toneladas","decimales":1},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"200 × 40 % = 80 t de orgánicos; × 50 % = 40 t por día que no van al relleno ni producen metano allí."}},{"slug":"residuos-3.s5.p6","orden":6,"grupo":"residuos-3.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"A escala municipal, con temperatura controlada, se pueden compostar también restos de carne y comida cocida.","razones":[{"id":"r1","texto":"Porque controlan la temperatura y el proceso"},{"id":"r2","texto":"Porque la carne se convierte en vegetal en la planta"},{"id":"r3","texto":"Porque a escala municipal no hay roedores nunca"}]},"solucion":{"valor":true,"explicacion":"Las plantas industriales alcanzan y mantienen temperaturas altas y controlan el proceso, lo que permite tratar restos que en casa conviene evitar.","clave":["r1"]}},{"slug":"residuos-3.s5.p7","orden":7,"grupo":"residuos-3.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una compostera comunitaria","cuerpo":["Una compostera comunitaria necesita un lugar, algunas personas responsables, reglas claras (qué va y qué no), materiales secos disponibles (por ejemplo, hojas de la poda del barrio) y comunicación con los vecinos. Bien organizada, puede tratar los orgánicos de decenas de familias y producir compost para la plaza o la huerta."]},"solucion":{}},{"slug":"residuos-3.s5.p8","orden":8,"grupo":"residuos-3.s5.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para armar una compostera comunitaria en un edificio.","items":[{"id":"i1","texto":"Consultar a los vecinos y a la administración"},{"id":"i2","texto":"Elegir un lugar ventilado y accesible"},{"id":"i3","texto":"Armar la compostera y conseguir secos"},{"id":"i4","texto":"Poner un cartel con qué va y qué no"},{"id":"i5","texto":"Organizar turnos para revolver y cuidar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Como cualquier proyecto comunitario: acuerdo, lugar, materiales, reglas y turnos."}},{"slug":"residuos-3.s5.p9","orden":9,"grupo":"residuos-3.s5.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué necesita una compostera comunitaria para funcionar bien? Marcá todo.","opciones":[{"id":"o1","texto":"Reglas claras sobre qué va y qué no"},{"id":"o2","texto":"Materiales secos disponibles"},{"id":"o3","texto":"Personas responsables con turnos"},{"id":"o4","texto":"Comunicación con los vecinos"},{"id":"o5","texto":"Que cada vecino tire lo que quiera sin avisar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo técnico es simple; lo organizativo es la clave."}},{"slug":"residuos-3.s5.p10","orden":10,"grupo":"residuos-3.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada escala con una característica.","izquierda":[{"id":"a1","texto":"Compostera casera"},{"id":"a2","texto":"Vermicompostador"},{"id":"a3","texto":"Compostera comunitaria"},{"id":"a4","texto":"Planta municipal"}],"derecha":[{"id":"b1","texto":"Solo restos vegetales y secos"},{"id":"b2","texto":"Lombrices en cajas, ideal para departamentos"},{"id":"b3","texto":"Varias familias con turnos compartidos"},{"id":"b4","texto":"Temperatura controlada y restos de todo tipo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas escalas, un mismo objetivo: que lo orgánico vuelva al suelo."}},{"slug":"residuos-3.s5.p11","orden":11,"grupo":"residuos-3.s5.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué separar los orgánicos en origen es clave para el compostaje municipal?","opciones":[{"id":"o1","texto":"Porque mezclado, el compost queda contaminado"},{"id":"o2","texto":"Porque así los camiones van más rápido"},{"id":"o3","texto":"Porque los orgánicos separados no pesan"},{"id":"o4","texto":"Porque la ley prohíbe mezclar residuos en la calle"}]},"solucion":{"clave":["o1"],"explicacion":"Un compost con restos de vidrio o plástico no sirve para plazas ni huertas. La calidad empieza en casa.","por_opcion":{"o3":"Pesan igual; el punto es que lleguen limpios para compostar."}}},{"slug":"residuos-3.s5.p12","orden":12,"grupo":"residuos-3.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan municipal y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Recolectaremos los orgánicos por separado dos veces por semana."},{"id":"s2","texto":"Aceptaremos orgánicos mezclados con plásticos para simplificar."},{"id":"s3","texto":"Usaremos el compost en las plazas de la ciudad."},{"id":"s4","texto":"No haremos campañas: los vecinos ya saben qué es orgánico."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El compostaje a escala es un sistema: separación, recolección, tratamiento y comunicación.","por_opcion":{"s2":"El compost quedaría contaminado y no serviría.","s4":"Sin comunicación, la separación falla. Las campañas son clave."}}},{"slug":"residuos-3.s5.p13","orden":13,"grupo":"residuos-3.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las lombrices en cajas forman un {{0}}; a escala {{1}} se pueden compostar también restos cocidos; y la clave es separar en {{2}}.","banco":[{"id":"w1","texto":"vermicompostador"},{"id":"w2","texto":"municipal"},{"id":"w3","texto":"origen"},{"id":"w4","texto":"termotanque"},{"id":"w5","texto":"casera"},{"id":"w6","texto":"destino"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las escalas del compostaje, en una línea."}},{"slug":"residuos-3.s5.p14","orden":14,"grupo":"residuos-3.s5.p14","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas escalas por la cantidad de residuos que pueden tratar, de menos a más.","items":[{"id":"i1","texto":"Vermicompostador de balcón"},{"id":"i2","texto":"Compostera de patio"},{"id":"i3","texto":"Compostera comunitaria"},{"id":"i4","texto":"Planta municipal"}],"extremos":["Menos","Más"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada escala suma. Una ciudad puede combinarlas todas.","valores":{"i1":"una casa chica","i2":"una familia","i3":"decenas de familias","i4":"toneladas por día"}}}]},{"slug":"residuos-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: compostar","bajada_es":"Proceso, receta, qué va y qué no, problemas y escalas, mezclados.","minutos":8,"pasos":[{"slug":"residuos-3.s6.p1","orden":1,"grupo":"residuos-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Compostar: la mitad de la bolsa». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la compostera del edificio","bajada_es":"Un edificio de 24 departamentos quiere compostar en su patio. Con los números, armá el plan.","minutos":10,"pasos":[{"slug":"residuos-3.s7.p1","orden":1,"grupo":"residuos-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El edificio","cuerpo":["El edificio tiene 24 departamentos. Se sumaron 12 al proyecto. Cada departamento genera unos 3 kg de restos vegetales por semana. En el patio hay lugar para dos composteras de 400 litros. El jardinero del edificio junta hojas secas de dos árboles.","Un kilo de restos de cocina ocupa alrededor de 2 litros, y cada litro de húmedos necesita unos 2 litros de secos."]},"solucion":{}},{"slug":"residuos-3.s7.p2","orden":2,"grupo":"residuos-3.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de restos vegetales por semana juntan los 12 departamentos?","unidad":"kg","decimales":0,"contexto":"12 departamentos; 3 kg de restos vegetales por semana cada uno."},"solucion":{"valor":36,"tolerancia":0.72,"explicacion":"12 × 3 = 36 kg por semana de restos que hoy van a la basura común."}},{"slug":"residuos-3.s7.p3","orden":3,"grupo":"residuos-3.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de restos húmedos son por semana? (2 litros por kg)","unidad":"litros","decimales":0,"contexto":"36 kg de restos por semana; 2 litros por kg."},"solucion":{"valor":72,"tolerancia":1.44,"explicacion":"36 kg × 2 = 72 litros de húmedos por semana."}},{"slug":"residuos-3.s7.p4","orden":4,"grupo":"residuos-3.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de secos hacen falta por semana para mantener la proporción de 2 a 1?","unidad":"litros","decimales":0,"contexto":"72 litros de húmedos por semana; 2 de secos por cada 1 de húmedos."},"solucion":{"valor":144,"tolerancia":2.88,"explicacion":"72 × 2 = 144 litros de secos por semana. Las hojas del jardinero pueden no alcanzar todo el año: conviene guardar hojas del otoño y sumar cartón."}},{"slug":"residuos-3.s7.p5","orden":5,"grupo":"residuos-3.s7.p5","tipo":"opcion","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Con 72 litros de húmedos y 144 de secos por semana, ¿alcanzan dos composteras de 400 litros?","opciones":[{"id":"o1","texto":"Sí, porque el volumen baja mucho al descomponerse"},{"id":"o2","texto":"No, se llenan en tres días y hay que tirar todo"},{"id":"o3","texto":"Sí, porque los secos no ocupan lugar"},{"id":"o4","texto":"No, el compost crece en volumen con el tiempo"}]},"solucion":{"clave":["o1"],"explicacion":"Entran 216 litros por semana, pero el volumen se reduce mucho: con dos composteras y buena rotación, alcanza.","por_opcion":{"o3":"Ocupan lugar; lo que ayuda es que todo se reduce mucho al descomponerse."}}},{"slug":"residuos-3.s7.p6","orden":6,"grupo":"residuos-3.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de la reunión de consorcio.","grupos":[{"id":"g1","nombre":"Conviene"},{"id":"g2","nombre":"No conviene"}],"items":[{"id":"i1","texto":"Cartel con qué va y qué no"},{"id":"i2","texto":"Aceptar restos de asado para que no haya quejas"},{"id":"i3","texto":"Turnos para revolver"},{"id":"i4","texto":"Taparla herméticamente para evitar olores"},{"id":"i5","texto":"Guardar hojas del otoño para todo el año"},{"id":"i6","texto":"Poner la compostera dentro del hall"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Reglas claras, secos disponibles, aire y un lugar ventilado."}},{"slug":"residuos-3.s7.p7","orden":7,"grupo":"residuos-3.s7.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los departamentos compostan 36 kg por semana, ¿cuántos kg dejan de ir al relleno en un año de 52 semanas?","unidad":"kg","decimales":0},"solucion":{"valor":1872,"tolerancia":37.44,"explicacion":"36 × 52 = 1.872 kg por año: casi 1.9 toneladas de residuos que se convierten en abono."}},{"slug":"residuos-3.s7.p7.v2","orden":7,"grupo":"residuos-3.s7.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los departamentos compostan 30 kg por semana, ¿cuántos kg dejan de ir al relleno en un año de 52 semanas?","unidad":"kg","decimales":0},"solucion":{"valor":1560,"tolerancia":31.2,"explicacion":"30 × 52 = 1.560 kg por año: casi 1.6 toneladas de residuos que se convierten en abono."}},{"slug":"residuos-3.s7.p7.v3","orden":7,"grupo":"residuos-3.s7.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los departamentos compostan 42 kg por semana, ¿cuántos kg dejan de ir al relleno en un año de 52 semanas?","unidad":"kg","decimales":0},"solucion":{"valor":2184,"tolerancia":43.68,"explicacion":"42 × 52 = 2.184 kg por año: casi 2.2 toneladas de residuos que se convierten en abono."}},{"slug":"residuos-3.s7.p8","orden":8,"grupo":"residuos-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El consorcio publica las reglas. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Cubrí siempre los restos con hojas secas."},{"id":"s2","texto":"Podés poner huesos y restos de comida cocida sin problema."},{"id":"s3","texto":"Cada semana, un departamento revuelve las composteras."},{"id":"s4","texto":"Si huele mal, echale agua hasta que se vaya el olor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Buenas reglas evitan los problemas antes de que aparezcan.","por_opcion":{"s2":"En una compostera de patio atraen roedores y generan olores.","s4":"El olor suele ser exceso de humedad: hay que sumar secos y airear."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"residuos-4","rama":"residuos","orden":4,"nivel":2,"titulo_es":"El problema del plástico","bajada_es":"Liviano, barato y casi eterno: por qué el plástico cambió el mundo, adónde va a parar, qué son los microplásticos y qué soluciones funcionan de verdad.","objetivos_es":["Explicar las propiedades y los usos del plástico, y por qué duran tanto","Describir los destinos del plástico descartado en el mundo","Reconocer las fuentes y los riesgos de los microplásticos","Relacionar el plástico con la contaminación de ríos, mares y fauna","Comparar soluciones según la jerarquía de residuos"],"repasa":["residuos-2","residuos-1","tronco-2"],"requiere_tronco":2,"fuentes":["oecd-plasticos","unep-plasticos","ellen-macarthur","rep-envases","emf-textiles"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-4.s1","orden":1,"tipo":"leccion","titulo_es":"Un material que dura demasiado","bajada_es":"De dónde sale el plástico, por qué es tan útil y por qué su gran virtud es también su gran problema.","minutos":10,"pasos":[{"slug":"residuos-4.s1.p1","orden":1,"grupo":"residuos-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es el plástico","cuerpo":["Los plásticos son materiales hechos de moléculas muy largas, los polímeros, que en su gran mayoría se fabrican a partir de petróleo y gas. Se pueden moldear en casi cualquier forma, son livianos, baratos, resistentes al agua y duraderos. Por eso están en envases, ropa, autos, caños, juguetes, equipos médicos y casi todo lo que usamos.","La producción mundial creció de unos 2 millones de toneladas en 1950 a más de 450 millones de toneladas por año en 2019, según la OCDE."],"destacado":{"valor":"> 450 millones","texto":"de toneladas de plástico por año se producían en el mundo en 2019, según la OCDE."}},"solucion":{}},{"slug":"residuos-4.s1.p2","orden":2,"grupo":"residuos-4.s1.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos millones de toneladas de plástico por año se producían en el mundo en 2019.","min":1,"max":10000,"paso":1,"unidad":"millones de t","escala":"log"},"solucion":{"valor":460,"banda":"log","explicacion":"Unos 460 millones de toneladas, según la OCDE. En 1950 eran unos 2 millones."}},{"slug":"residuos-4.s1.p3","orden":3,"grupo":"residuos-4.s1.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la producción de plástico pasó de 2 millones de toneladas por año en 1950 a 460 millones, ¿cuántas veces se multiplicó?","unidad":"veces","decimales":0},"solucion":{"valor":230,"tolerancia":4.6000000000000005,"explicacion":"460 ÷ 2 = 230 veces. Pocos materiales crecieron tanto en tan poco tiempo."}},{"slug":"residuos-4.s1.p3.v2","orden":3,"grupo":"residuos-4.s1.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la producción de plástico pasó de 2 millones de toneladas por año en 1950 a 400 millones, ¿cuántas veces se multiplicó?","unidad":"veces","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"400 ÷ 2 = 200 veces. Pocos materiales crecieron tanto en tan poco tiempo."}},{"slug":"residuos-4.s1.p3.v3","orden":3,"grupo":"residuos-4.s1.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la producción de plástico pasó de 2 millones de toneladas por año en 1950 a 450 millones, ¿cuántas veces se multiplicó?","unidad":"veces","decimales":0},"solucion":{"valor":225,"tolerancia":4.5,"explicacion":"450 ÷ 2 = 225 veces. Pocos materiales crecieron tanto en tan poco tiempo."}},{"slug":"residuos-4.s1.p4","orden":4,"grupo":"residuos-4.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Su virtud, su problema","cuerpo":["El plástico es útil porque es resistente y durable. Pero esa durabilidad es un problema cuando se descarta: la mayoría de los plásticos no se biodegradan en tiempos humanos; con el sol y el roce se rompen en pedazos cada vez más chicos, pero esos pedazos siguen siendo plástico durante décadas o siglos.","Además, una gran parte se usa en productos de un solo uso, como envases, que se descartan a los pocos minutos o días."]},"solucion":{}},{"slug":"residuos-4.s1.p5","orden":5,"grupo":"residuos-4.s1.p5","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el plástico de un solo uso es un problema.","items":[{"id":"i1","texto":"Se fabrica un envase muy durable"},{"id":"i2","texto":"Se usa unos minutos"},{"id":"i3","texto":"Se descarta"},{"id":"i4","texto":"Como no se biodegrada, persiste décadas o siglos"},{"id":"i5","texto":"Se acumula en rellenos, basurales o el ambiente"},{"id":"i6","texto":"Al descartarlo, el plástico se transforma en agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un material diseñado para durar, usado para algo que dura minutos."}},{"slug":"residuos-4.s1.p6","orden":6,"grupo":"residuos-4.s1.p6","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este uso del plástico suele ser de un solo uso o de larga duración?","grupos":[{"id":"g1","nombre":"Un solo uso"},{"id":"g2","nombre":"Larga duración"}],"items":[{"id":"i1","texto":"Bolsa de supermercado liviana"},{"id":"i2","texto":"Caño de agua de una casa"},{"id":"i3","texto":"Vaso de café descartable"},{"id":"i4","texto":"Parte de una heladera"},{"id":"i5","texto":"Film para envolver fruta"},{"id":"i6","texto":"Tanque de agua"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El problema más grande está en lo que se usa minutos y dura siglos."}},{"slug":"residuos-4.s1.p7","orden":7,"grupo":"residuos-4.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un envase plástico se biodegrada por completo en pocos meses en la naturaleza.","razones":[{"id":"r1","texto":"Porque se fragmenta pero sigue siendo plástico durante mucho tiempo"},{"id":"r2","texto":"Porque se convierte en arena en semanas"},{"id":"r3","texto":"Porque los plásticos son de origen vegetal"}]},"solucion":{"valor":false,"explicacion":"La mayoría de los plásticos no se biodegradan en tiempos humanos: se fragmentan en pedazos cada vez más chicos que persisten durante décadas o siglos.","clave":["r1"]}},{"slug":"residuos-4.s1.p8","orden":8,"grupo":"residuos-4.s1.p8","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada propiedad del plástico con por qué se usa tanto.","izquierda":[{"id":"a1","texto":"Liviano"},{"id":"a2","texto":"Resistente al agua"},{"id":"a3","texto":"Moldeable"},{"id":"a4","texto":"Barato"}],"derecha":[{"id":"b1","texto":"Abarata el transporte"},{"id":"b2","texto":"Sirve para envases de líquidos"},{"id":"b3","texto":"Se puede fabricar casi cualquier forma"},{"id":"b4","texto":"Reemplazó a muchos otros materiales"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las mismas propiedades que lo hicieron exitoso explican por qué se acumula."}},{"slug":"residuos-4.s1.p9","orden":9,"grupo":"residuos-4.s1.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿De qué se fabrica la gran mayoría de los plásticos?","opciones":[{"id":"o1","texto":"De petróleo y gas"},{"id":"o2","texto":"De arena de playa"},{"id":"o3","texto":"De maíz y caña de azúcar"},{"id":"o4","texto":"De madera de bosques nativos"}]},"solucion":{"clave":["o1"],"explicacion":"Por eso el plástico también está conectado con la energía y el clima.","por_opcion":{"o3":"Existen bioplásticos de origen vegetal, pero son una parte muy chica."}}},{"slug":"residuos-4.s1.p10","orden":10,"grupo":"residuos-4.s1.p10","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos objetos por cuánto tiempo suelen usarse, de más corto a más largo.","items":[{"id":"i1","texto":"Sorbete"},{"id":"i2","texto":"Botella de agua descartable"},{"id":"i3","texto":"Mochila de nylon"},{"id":"i4","texto":"Caño de PVC en una pared"}],"extremos":["Más corto","Más largo"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Todos pueden durar como material décadas o siglos. Cuanto más corto su uso, más absurdo el descarte.","valores":{"i1":"minutos","i2":"horas o días","i3":"años","i4":"décadas"}}},{"slug":"residuos-4.s1.p11","orden":11,"grupo":"residuos-4.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El plástico se fabrica sobre todo a partir de petróleo y gas."},{"id":"s2","texto":"El plástico desaparece por completo al romperse en pedazos chicos."},{"id":"s3","texto":"La producción de plástico creció enormemente desde 1950."},{"id":"s4","texto":"Casi todos los plásticos se usan en objetos de larga duración."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Útil, barato y durable: tres virtudes que se vuelven problema al descartarlo.","por_opcion":{"s2":"Los pedazos siguen siendo plástico: se vuelven microplásticos.","s4":"Una gran parte se usa en envases y productos de un solo uso."}}},{"slug":"residuos-4.s1.p12","orden":12,"grupo":"residuos-4.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los plásticos son {{0}} que se fabrican sobre todo con {{1}} y gas; y en lugar de biodegradarse, se {{2}}.","banco":[{"id":"w1","texto":"polímeros"},{"id":"w2","texto":"petróleo"},{"id":"w3","texto":"fragmentan"},{"id":"w4","texto":"minerales"},{"id":"w5","texto":"madera"},{"id":"w6","texto":"evaporan"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Qué es el plástico y por qué dura tanto."}},{"slug":"residuos-4.s1.p13","orden":13,"grupo":"residuos-4.s1.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿En qué productos cotidianos hay plástico? Marcá todos.","opciones":[{"id":"o1","texto":"Una remera de poliéster"},{"id":"o2","texto":"El envase de un yogur"},{"id":"o3","texto":"Un cepillo de dientes"},{"id":"o4","texto":"El chicle"},{"id":"o5","texto":"Una cuchara de acero inoxidable"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El plástico está hasta donde no se ve: en telas sintéticas y hasta en la goma de muchos chicles."}}]},{"slug":"residuos-4.s2","orden":2,"tipo":"leccion","titulo_es":"Adónde va el plástico","bajada_es":"Reciclado, quemado, enterrado o perdido en el ambiente: el destino real del plástico descartado.","minutos":11,"pasos":[{"slug":"residuos-4.s2.p1","orden":1,"grupo":"residuos-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números de la OCDE","cuerpo":["Según la OCDE, en 2019 se generaron en el mundo unos 353 millones de toneladas de residuos plásticos. Solo alrededor del 9 % terminó reciclado; cerca del 19 % se incineró; alrededor de la mitad fue a rellenos sanitarios; y cerca del 22 % se gestionó mal: terminó en basurales a cielo abierto, se quemó sin control o se escapó al ambiente."],"datos":{"tipo":"barras","titulo":"Destino de los residuos plásticos del mundo (2019)","unidad":"% del total","filas":[{"etiqueta":"Relleno sanitario","valor":50},{"etiqueta":"Mal gestionado","valor":22},{"etiqueta":"Incinerado","valor":19},{"etiqueta":"Reciclado","valor":9}],"nota":"OCDE, Global Plastics Outlook (2022). Valores redondeados."}},"solucion":{}},{"slug":"residuos-4.s2.p2","orden":2,"grupo":"residuos-4.s2.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según la OCDE, ordená los destinos del plástico descartado de mayor a menor porcentaje.","items":[{"id":"i1","texto":"Relleno sanitario"},{"id":"i2","texto":"Mal gestionado"},{"id":"i3","texto":"Incinerado"},{"id":"i4","texto":"Reciclado"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El reciclaje es el destino menos frecuente. Más de uno de cada cinco kilos termina mal gestionado.","valores":{"i1":"≈ 50 %","i2":"≈ 22 %","i3":"≈ 19 %","i4":"≈ 9 %"}}},{"slug":"residuos-4.s2.p3","orden":3,"grupo":"residuos-4.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 353 millones de toneladas de residuos plásticos, el 9 % se recicló. ¿Cuántos millones de toneladas son? Redondeá al entero.","unidad":"millones de t","decimales":0},"solucion":{"valor":32,"tolerancia":1,"explicacion":"353 × 9 ÷ 100 ≈ 32 millones de toneladas en un solo año."}},{"slug":"residuos-4.s2.p3.v2","orden":3,"grupo":"residuos-4.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 353 millones de toneladas de residuos plásticos, el 22 % se gestionó mal. ¿Cuántos millones de toneladas son? Redondeá al entero.","unidad":"millones de t","decimales":0},"solucion":{"valor":78,"tolerancia":1,"explicacion":"353 × 22 ÷ 100 ≈ 78 millones de toneladas en un solo año."}},{"slug":"residuos-4.s2.p3.v3","orden":3,"grupo":"residuos-4.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 353 millones de toneladas de residuos plásticos, el 19 % se incineró. ¿Cuántos millones de toneladas son? Redondeá al entero.","unidad":"millones de t","decimales":0},"solucion":{"valor":67,"tolerancia":1,"explicacion":"353 × 19 ÷ 100 ≈ 67 millones de toneladas en un solo año."}},{"slug":"residuos-4.s2.p4","orden":4,"grupo":"residuos-4.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mal gestionado","cuerpo":["\"Mal gestionado\" incluye el plástico que termina en basurales a cielo abierto, que se quema a cielo abierto liberando humos tóxicos, o que se escapa a arroyos, ríos y mares. Ocurre sobre todo donde no hay recolección suficiente, como en muchos barrios populares y zonas rurales del mundo, incluidos lugares de Argentina."]},"solucion":{}},{"slug":"residuos-4.s2.p5","orden":5,"grupo":"residuos-4.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una bolsa puede llegar al mar desde un barrio sin recolección.","items":[{"id":"i1","texto":"No pasa el camión recolector por el barrio"},{"id":"i2","texto":"La basura se acumula en un zanjón"},{"id":"i3","texto":"Una lluvia fuerte la arrastra al arroyo"},{"id":"i4","texto":"El arroyo desemboca en un río"},{"id":"i5","texto":"El río lleva la bolsa hasta el mar"},{"id":"i6","texto":"La bolsa vuela directo del barrio al mar en un día"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Buena parte del plástico del mar viene de tierra firme, arrastrado por los ríos."}},{"slug":"residuos-4.s2.p6","orden":6,"grupo":"residuos-4.s2.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La mayor parte del plástico que se descarta en el mundo se recicla.","razones":[{"id":"r1","texto":"Porque solo alrededor del 9 % se recicla"},{"id":"r2","texto":"Porque el 90 % se recicla en el mundo"},{"id":"r3","texto":"Porque el plástico no se puede reciclar nunca"}]},"solucion":{"valor":false,"explicacion":"Solo alrededor del 9 % se recicla, según la OCDE. La mayor parte va a rellenos, se incinera o se gestiona mal.","clave":["r1"]}},{"slug":"residuos-4.s2.p7","orden":7,"grupo":"residuos-4.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Incinerar","cuerpo":["Incinerar plástico en plantas con control de emisiones puede recuperar energía, pero emite CO₂ (el plástico es, en el fondo, petróleo) y deja cenizas que hay que gestionar. Quemarlo a cielo abierto, en cambio, libera humos muy tóxicos y es uno de los peores destinos."]},"solucion":{}},{"slug":"residuos-4.s2.p8","orden":8,"grupo":"residuos-4.s2.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un destino controlado o un destino mal gestionado?","grupos":[{"id":"g1","nombre":"Controlado"},{"id":"g2","nombre":"Mal gestionado"}],"items":[{"id":"i1","texto":"Relleno sanitario con membranas"},{"id":"i2","texto":"Quema en un basural"},{"id":"i3","texto":"Planta de reciclaje"},{"id":"i4","texto":"Bolsa en un arroyo"},{"id":"i5","texto":"Incineradora con control de emisiones"},{"id":"i6","texto":"Basural a cielo abierto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo controlado no es perfecto, pero lo mal gestionado daña el aire, el agua y la salud."}},{"slug":"residuos-4.s2.p9","orden":9,"grupo":"residuos-4.s2.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué quemar plástico a cielo abierto es uno de los peores destinos?","opciones":[{"id":"o1","texto":"Porque libera humos tóxicos sin ningún control"},{"id":"o2","texto":"Porque el plástico no se puede quemar"},{"id":"o3","texto":"Porque produce electricidad que se desperdicia"},{"id":"o4","texto":"Porque deja el plástico intacto"}]},"solucion":{"clave":["o1"],"explicacion":"La quema abierta afecta a quienes viven cerca y contamina el aire.","por_opcion":{"o3":"El problema principal son los humos tóxicos, no la energía."}}},{"slug":"residuos-4.s2.p10","orden":10,"grupo":"residuos-4.s2.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace falta para que menos plástico termine mal gestionado? Marcá todo.","opciones":[{"id":"o1","texto":"Recolección de residuos en todos los barrios"},{"id":"o2","texto":"Cerrar basurales a cielo abierto"},{"id":"o3","texto":"Reducir los plásticos de un solo uso"},{"id":"o4","texto":"Sistemas de recuperación con cooperativas"},{"id":"o5","texto":"Quemar más plástico en los patios"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Recolección, disposición adecuada, reducción y recuperación."}},{"slug":"residuos-4.s2.p11","orden":11,"grupo":"residuos-4.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada destino con su problema principal.","izquierda":[{"id":"a1","texto":"Relleno sanitario"},{"id":"a2","texto":"Incineración controlada"},{"id":"a3","texto":"Quema abierta"},{"id":"a4","texto":"Fuga al ambiente"}],"derecha":[{"id":"b1","texto":"Ocupa espacio durante siglos"},{"id":"b2","texto":"Emite CO₂ y deja cenizas"},{"id":"b3","texto":"Humos tóxicos"},{"id":"b4","texto":"Contamina ríos, mares y fauna"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Ningún destino del plástico descartado es neutro. Por eso reducir es la primera línea."}},{"slug":"residuos-4.s2.p12","orden":12,"grupo":"residuos-4.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Solo una pequeña parte del plástico del mundo se recicla."},{"id":"s2","texto":"Quemar plástico en el patio es una buena forma de deshacerse de él."},{"id":"s3","texto":"Mucho plástico del mar llega desde los ríos."},{"id":"s4","texto":"Incinerar plástico no emite CO₂."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer los destinos reales cambia la mirada sobre el plástico.","por_opcion":{"s2":"Libera humos tóxicos que afectan la salud.","s4":"Sí emite: el plástico está hecho de carbono de origen fósil."}}},{"slug":"residuos-4.s2.p13","orden":13,"grupo":"residuos-4.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Según la OCDE, solo alrededor del {{0}} % del plástico se recicla; cerca del {{1}} % se gestiona mal.","banco":[{"id":"w1","texto":"9"},{"id":"w2","texto":"22"},{"id":"w3","texto":"90"},{"id":"w4","texto":"2"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos números que resumen el problema global del plástico."}},{"slug":"residuos-4.s2.p14","orden":14,"grupo":"residuos-4.s2.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos millones de toneladas de residuos plásticos se generaron en el mundo en 2019.","min":1,"max":10000,"paso":1,"unidad":"millones de t","escala":"log"},"solucion":{"valor":353,"banda":"log","explicacion":"Unos 353 millones de toneladas, según la OCDE: más de un camión de basura lleno por segundo, durante todo el año."}}]},{"slug":"residuos-4.s3","orden":3,"tipo":"leccion","titulo_es":"Microplásticos","bajada_es":"Pedacitos de menos de 5 milímetros que ya están en el agua, el suelo, el aire y la comida.","minutos":11,"pasos":[{"slug":"residuos-4.s3.p1","orden":1,"grupo":"residuos-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué son","cuerpo":["Los microplásticos son pedazos de plástico de menos de 5 milímetros. Algunos se fabrican así de chicos (microplásticos primarios), como las bolitas que usa la industria para fabricar objetos o las microesferas de algunos cosméticos. Otros se forman cuando objetos más grandes se rompen (secundarios): bolsas, botellas, redes de pesca.","Hay además fuentes menos visibles: las fibras que sueltan las telas sintéticas al lavarse y el polvo que desprenden los neumáticos al rodar."]},"solucion":{}},{"slug":"residuos-4.s3.p2","orden":2,"grupo":"residuos-4.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un microplástico primario o secundario?","grupos":[{"id":"g1","nombre":"Primario (fabricado chico)"},{"id":"g2","nombre":"Secundario (de la rotura)"}],"items":[{"id":"i1","texto":"Bolitas de plástico para la industria"},{"id":"i2","texto":"Fragmentos de una botella rota por el sol"},{"id":"i3","texto":"Microesferas de un exfoliante"},{"id":"i4","texto":"Pedazos de una bolsa desgastada"},{"id":"i5","texto":"Trozos de una red de pesca vieja"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Unos se fabrican chicos; otros se achican con el tiempo. Los dos terminan en el ambiente."}},{"slug":"residuos-4.s3.p3","orden":3,"grupo":"residuos-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dónde están","cuerpo":["Se encontraron microplásticos en el agua de ríos y mares, en la arena de las playas, en el suelo agrícola, en el aire de las ciudades, en la nieve de las montañas, en el agua embotellada y de red, en alimentos como mariscos y sal, y en el cuerpo humano.","Los científicos todavía estudian cuánto afectan la salud. Lo que se sabe es que están en todas partes y que su cantidad sigue creciendo."]},"solucion":{}},{"slug":"residuos-4.s3.p4","orden":4,"grupo":"residuos-4.s3.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Dónde se encontraron microplásticos? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"En el mar y los ríos"},{"id":"o2","texto":"En el suelo agrícola"},{"id":"o3","texto":"En el aire de las ciudades"},{"id":"o4","texto":"En alimentos como mariscos y sal"},{"id":"o5","texto":"Solo en los rellenos sanitarios"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Están en todas partes: por eso se habla de una contaminación global."}},{"slug":"residuos-4.s3.p5","orden":5,"grupo":"residuos-4.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Ya está demostrado con certeza cuánto daño hacen los microplásticos a la salud humana.","razones":[{"id":"r1","texto":"Porque sus efectos todavía se están investigando"},{"id":"r2","texto":"Porque está demostrado que no hacen nada"},{"id":"r3","texto":"Porque los microplásticos no llegan al cuerpo"}]},"solucion":{"valor":false,"explicacion":"Se sabe que están en el cuerpo, pero la ciencia todavía estudia sus efectos. Es un caso donde el principio precautorio tiene mucho sentido.","clave":["r1"]}},{"slug":"residuos-4.s3.p6","orden":6,"grupo":"residuos-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Fibras y neumáticos","cuerpo":["Cada vez que se lava ropa de poliéster, nailon o acrílico, se sueltan miles de microfibras que van por el desagüe; muchas plantas de tratamiento no logran retenerlas todas. Y los neumáticos, al rozar el asfalto, desprenden partículas que la lluvia lleva a arroyos y ríos: en muchos estudios aparecen entre las mayores fuentes de microplásticos."]},"solucion":{}},{"slug":"residuos-4.s3.p7","orden":7,"grupo":"residuos-4.s3.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una microfibra de una campera polar.","items":[{"id":"i1","texto":"Se lava la campera en el lavarropas"},{"id":"i2","texto":"Se sueltan miles de microfibras"},{"id":"i3","texto":"Van por el desagüe"},{"id":"i4","texto":"Parte atraviesa la planta de tratamiento"},{"id":"i5","texto":"Llegan al río y al mar"},{"id":"i6","texto":"Las microfibras se disuelven en el jabón"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un camino invisible que empieza en el lavarropas."}},{"slug":"residuos-4.s3.p8","orden":8,"grupo":"residuos-4.s3.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué práctica reduce las microfibras que suelta la ropa sintética?","opciones":[{"id":"o1","texto":"Lavar menos, con carga completa y agua fría"},{"id":"o2","texto":"Lavar todo con agua muy caliente"},{"id":"o3","texto":"Lavar cada prenda sola, en ciclos cortos"},{"id":"o4","texto":"Usar más suavizante en cada lavado"}]},"solucion":{"clave":["o1"],"explicacion":"Menos lavados, carga completa y agua fría reducen la liberación. También existen filtros y bolsas de lavado que retienen fibras.","por_opcion":{"o3":"Cargas chicas suelen aumentar el roce y la liberación de fibras."}}},{"slug":"residuos-4.s3.p9","orden":9,"grupo":"residuos-4.s3.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada fuente con el tipo de microplástico que genera.","izquierda":[{"id":"a1","texto":"Lavarropas con ropa sintética"},{"id":"a2","texto":"Neumáticos en el asfalto"},{"id":"a3","texto":"Botella rota en la playa"},{"id":"a4","texto":"Fábrica de plásticos"}],"derecha":[{"id":"b1","texto":"Microfibras"},{"id":"b2","texto":"Partículas de caucho y plástico"},{"id":"b3","texto":"Fragmentos secundarios"},{"id":"b4","texto":"Bolitas industriales"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Fuentes muy distintas, un mismo problema."}},{"slug":"residuos-4.s3.p10","orden":10,"grupo":"residuos-4.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un lavado de ropa sintética suelta unas 700.000 microfibras y una familia hace 3 lavados por semana, ¿cuántas microfibras suelta en una semana?","unidad":"microfibras","decimales":0},"solucion":{"valor":2100000,"tolerancia":42000,"explicacion":"700.000 × 3 = 2.100.000 microfibras por semana, de una sola casa. Multiplicado por millones de casas, es una fuente enorme."}},{"slug":"residuos-4.s3.p10.v2","orden":10,"grupo":"residuos-4.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un lavado de ropa sintética suelta unas 500.000 microfibras y una familia hace 4 lavados por semana, ¿cuántas microfibras suelta en una semana?","unidad":"microfibras","decimales":0},"solucion":{"valor":2000000,"tolerancia":40000,"explicacion":"500.000 × 4 = 2.000.000 microfibras por semana, de una sola casa. Multiplicado por millones de casas, es una fuente enorme."}},{"slug":"residuos-4.s3.p10.v3","orden":10,"grupo":"residuos-4.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un lavado de ropa sintética suelta unas 1.000.000 microfibras y una familia hace 2 lavados por semana, ¿cuántas microfibras suelta en una semana?","unidad":"microfibras","decimales":0},"solucion":{"valor":2000000,"tolerancia":40000,"explicacion":"1.000.000 × 2 = 2.000.000 microfibras por semana, de una sola casa. Multiplicado por millones de casas, es una fuente enorme."}},{"slug":"residuos-4.s3.p11","orden":11,"grupo":"residuos-4.s3.p11","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos tamaños de mayor a menor.","items":[{"id":"i1","texto":"Una botella de plástico"},{"id":"i2","texto":"Una tapita"},{"id":"i3","texto":"Un microplástico grande"},{"id":"i4","texto":"Una microfibra de ropa"}],"extremos":["Mayor","Menor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El plástico no desaparece: pasa de lo que se ve a lo que no se ve.","valores":{"i1":"unos 20 centímetros","i2":"unos 3 centímetros","i3":"menos de 5 milímetros","i4":"más fina que un pelo"}}},{"slug":"residuos-4.s3.p12","orden":12,"grupo":"residuos-4.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los microplásticos miden menos de 5 milímetros."},{"id":"s2","texto":"Solo hay microplásticos en el mar, no en la comida."},{"id":"s3","texto":"Los neumáticos desprenden partículas que llegan a los ríos."},{"id":"s4","texto":"La ropa sintética no suelta nada al lavarse."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo que no se ve a simple vista también contamina.","por_opcion":{"s2":"Se encontraron en alimentos, agua y hasta en el cuerpo humano.","s4":"Suelta miles de microfibras en cada lavado."}}},{"slug":"residuos-4.s3.p13","orden":13,"grupo":"residuos-4.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los microplásticos miden menos de {{0}} milímetros; las telas sintéticas sueltan {{1}} al lavarse; y los {{2}} desprenden partículas al rodar.","banco":[{"id":"w1","texto":"5"},{"id":"w2","texto":"microfibras"},{"id":"w3","texto":"neumáticos"},{"id":"w4","texto":"50"},{"id":"w5","texto":"vitaminas"},{"id":"w6","texto":"semáforos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave sobre los microplásticos y sus fuentes."}},{"slug":"residuos-4.s3.p14","orden":14,"grupo":"residuos-4.s3.p14","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá el tamaño máximo, en milímetros, de un microplástico según la definición más usada.","min":0.1,"max":100,"paso":1,"unidad":"mm","escala":"log"},"solucion":{"valor":5,"banda":"log","explicacion":"Menos de 5 milímetros. Muchos son microscópicos."}}]},{"slug":"residuos-4.s4","orden":4,"tipo":"leccion","titulo_es":"Plástico en ríos, mares y fauna","bajada_es":"Cuánto plástico llega al agua, qué les hace a los animales y cómo se mueve por el océano.","minutos":11,"pasos":[{"slug":"residuos-4.s4.p1","orden":1,"grupo":"residuos-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Del río al mar","cuerpo":["Según el PNUMA, entre 19 y 23 millones de toneladas de residuos plásticos llegan cada año a lagos, ríos y mares. La mayor parte del plástico marino viene de tierra: de basurales, desagües y ríos que lo arrastran. Otra parte viene de la pesca: redes, sogas y boyas perdidas o abandonadas."],"destacado":{"valor":"19-23 millones de t","texto":"de residuos plásticos llegan cada año a lagos, ríos y mares, según el PNUMA."}},"solucion":{}},{"slug":"residuos-4.s4.p2","orden":2,"grupo":"residuos-4.s4.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos millones de toneladas de plástico llegan por año a lagos, ríos y mares, según el PNUMA.","min":0.1,"max":1000,"paso":1,"unidad":"millones de t","escala":"log"},"solucion":{"valor":21,"banda":"log","explicacion":"Entre 19 y 23 millones de toneladas por año. Como un camión de basura lleno cada unos 15 segundos, sin parar."}},{"slug":"residuos-4.s4.p3","orden":3,"grupo":"residuos-4.s4.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este plástico en el mar viene de tierra o del mar?","grupos":[{"id":"g1","nombre":"De tierra"},{"id":"g2","nombre":"Del mar"}],"items":[{"id":"i1","texto":"Bolsas que arrastra un río"},{"id":"i2","texto":"Redes de pesca perdidas"},{"id":"i3","texto":"Botellas de un basural costero"},{"id":"i4","texto":"Sogas y boyas abandonadas"},{"id":"i5","texto":"Envoltorios que caen a un desagüe"},{"id":"i6","texto":"Cajones que caen de un barco"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La mayor parte viene de tierra, pero los restos de pesca son de los más dañinos para la fauna."}},{"slug":"residuos-4.s4.p4","orden":4,"grupo":"residuos-4.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué les pasa a los animales","cuerpo":["Los animales marinos sufren el plástico de dos formas principales. Por enredo: tortugas, lobos marinos, aves y ballenas quedan atrapados en redes, sogas y anillos, y pueden ahogarse o lastimarse. Por ingestión: confunden el plástico con comida —las tortugas marinas, por ejemplo, pueden confundir bolsas con medusas— y se llenan el estómago de algo que no los alimenta.","Las \"redes fantasma\", redes de pesca perdidas que siguen atrapando animales durante años, son especialmente dañinas."]},"solucion":{}},{"slug":"residuos-4.s4.p5","orden":5,"grupo":"residuos-4.s4.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con el daño típico que le causa el plástico.","izquierda":[{"id":"a1","texto":"Tortuga marina"},{"id":"a2","texto":"Lobo marino"},{"id":"a3","texto":"Albatros"},{"id":"a4","texto":"Peces"}],"derecha":[{"id":"b1","texto":"Come bolsas confundiéndolas con medusas"},{"id":"b2","texto":"Se enreda en sogas y redes"},{"id":"b3","texto":"Alimenta a sus pichones con fragmentos de plástico"},{"id":"b4","texto":"Ingieren microplásticos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El enredo y la ingestión afectan a cientos de especies marinas."}},{"slug":"residuos-4.s4.p6","orden":6,"grupo":"residuos-4.s4.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una red de pesca perdida sigue matando.","items":[{"id":"i1","texto":"Una red de pesca se pierde en el mar"},{"id":"i2","texto":"Sigue flotando o en el fondo durante años"},{"id":"i3","texto":"Atrapa peces, tortugas y aves"},{"id":"i4","texto":"Los animales muertos atraen a otros animales"},{"id":"i5","texto":"Que también quedan atrapados"},{"id":"i6","texto":"La red se biodegrada en una semana"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso se las llama redes fantasma: pescan sin nadie que las maneje."}},{"slug":"residuos-4.s4.p7","orden":7,"grupo":"residuos-4.s4.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una tortuga marina puede confundir una bolsa de plástico con una medusa.","razones":[{"id":"r1","texto":"Porque en el agua la bolsa se parece a una medusa"},{"id":"r2","texto":"Porque las tortugas comen plástico a propósito"},{"id":"r3","texto":"Porque las bolsas tienen olor a pescado"}]},"solucion":{"valor":true,"explicacion":"En el agua, una bolsa flotando se parece a una medusa, uno de sus alimentos. Al comerla, puede morir por obstrucción.","clave":["r1"]}},{"slug":"residuos-4.s4.p8","orden":8,"grupo":"residuos-4.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las islas de basura","cuerpo":["Las corrientes del océano forman grandes remolinos, llamados giros, donde el plástico flotante se acumula. La más conocida es la \"gran mancha de basura del Pacífico\". No es una isla sólida: es una zona enorme con una concentración alta de fragmentos, la mayoría chicos, mezclados en el agua."]},"solucion":{}},{"slug":"residuos-4.s4.p9","orden":9,"grupo":"residuos-4.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo es realmente una \"isla de basura\" en el océano?","opciones":[{"id":"o1","texto":"Una zona enorme con muchos fragmentos flotando"},{"id":"o2","texto":"Una isla sólida de plástico donde se puede caminar"},{"id":"o3","texto":"Un basural en una isla con habitantes"},{"id":"o4","texto":"Una planta de reciclaje en medio del mar"}]},"solucion":{"clave":["o1"],"explicacion":"El nombre engaña: es más una sopa de fragmentos que una isla.","por_opcion":{"o3":"No es un lugar habitado: es una zona del océano donde se acumula plástico."}}},{"slug":"residuos-4.s4.p10","orden":10,"grupo":"residuos-4.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una limpieza de playa se juntaron 150 kg de residuos y el 70 % eran plásticos. ¿Cuántos kg de plástico se juntaron?","unidad":"kg","decimales":0},"solucion":{"valor":105,"tolerancia":2.1,"explicacion":"150 × 70 ÷ 100 = 105 kg de plástico. En las limpiezas de playas, el plástico suele ser la mayor parte de lo que se encuentra."}},{"slug":"residuos-4.s4.p10.v2","orden":10,"grupo":"residuos-4.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una limpieza de playa se juntaron 300 kg de residuos y el 80 % eran plásticos. ¿Cuántos kg de plástico se juntaron?","unidad":"kg","decimales":0},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"300 × 80 ÷ 100 = 240 kg de plástico. En las limpiezas de playas, el plástico suele ser la mayor parte de lo que se encuentra."}},{"slug":"residuos-4.s4.p10.v3","orden":10,"grupo":"residuos-4.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una limpieza de playa se juntaron 80 kg de residuos y el 60 % eran plásticos. ¿Cuántos kg de plástico se juntaron?","unidad":"kg","decimales":0},"solucion":{"valor":48,"tolerancia":0.96,"explicacion":"80 × 60 ÷ 100 = 48 kg de plástico. En las limpiezas de playas, el plástico suele ser la mayor parte de lo que se encuentra."}},{"slug":"residuos-4.s4.p11","orden":11,"grupo":"residuos-4.s4.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que menos plástico llegue al mar? Marcá todo.","opciones":[{"id":"o1","texto":"Recolección de basura en barrios cercanos a ríos"},{"id":"o2","texto":"Barreras que retienen residuos en arroyos"},{"id":"o3","texto":"Recuperar redes de pesca perdidas"},{"id":"o4","texto":"Reducir los plásticos de un solo uso"},{"id":"o5","texto":"Tirar la basura al río para que se la lleve"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cortar el camino en tierra es más efectivo que limpiar el mar."}},{"slug":"residuos-4.s4.p12","orden":12,"grupo":"residuos-4.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La mayor parte del plástico marino viene de tierra."},{"id":"s2","texto":"Las islas de basura son islas sólidas donde se puede caminar."},{"id":"s3","texto":"Las redes fantasma siguen atrapando animales."},{"id":"s4","texto":"El plástico en el mar no afecta a las aves."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El plástico en el mar es un problema real, que conviene contar con precisión.","por_opcion":{"s2":"Son zonas con muchos fragmentos flotando, no islas sólidas.","s4":"Muchas aves ingieren plástico o se enredan."}}},{"slug":"residuos-4.s4.p13","orden":13,"grupo":"residuos-4.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La mayor parte del plástico marino llega desde {{0}}; las redes perdidas que siguen atrapando animales se llaman redes {{1}}.","banco":[{"id":"w1","texto":"tierra"},{"id":"w2","texto":"fantasma"},{"id":"w3","texto":"el cielo"},{"id":"w4","texto":"mágicas"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas clave sobre el plástico en el mar y su origen."}},{"slug":"residuos-4.s4.p14","orden":14,"grupo":"residuos-4.s4.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas intervenciones de la más temprana a la más tardía en el camino del plástico hacia el mar.","items":[{"id":"i1","texto":"No producir el envase innecesario"},{"id":"i2","texto":"Recolectar la basura en el barrio"},{"id":"i3","texto":"Barrera en el arroyo"},{"id":"i4","texto":"Limpiar la playa"}],"extremos":["Más temprana","Más tardía"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto antes se corta el camino, menos esfuerzo y más efectivo.","valores":{"i1":"antes de que exista","i2":"en tierra","i3":"en el agua dulce","i4":"cuando ya llegó al mar"}}}]},{"slug":"residuos-4.s5","orden":5,"tipo":"leccion","titulo_es":"Soluciones que funcionan","bajada_es":"Reducir, rediseñar, retornables, responsabilidad del productor, prohibiciones y un tratado global.","minutos":12,"pasos":[{"slug":"residuos-4.s5.p1","orden":1,"grupo":"residuos-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo el ciclo","cuerpo":["Como el plástico es un problema de todo el ciclo —producción, uso y descarte—, las soluciones más efectivas actúan en varias etapas a la vez: producir menos plástico innecesario, rediseñar envases para que se puedan reutilizar o reciclar, recolectar y recuperar mejor, y limpiar lo que ya está en el ambiente.","Según la jerarquía de residuos que viste antes, reducir y reutilizar pesan más que reciclar, y limpiar es lo último: sirve, pero no alcanza si el grifo sigue abierto."]},"solucion":{}},{"slug":"residuos-4.s5.p2","orden":2,"grupo":"residuos-4.s5.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas contra el plástico según la jerarquía, de la más alta a la más baja.","items":[{"id":"i1","texto":"Eliminar envases innecesarios"},{"id":"i2","texto":"Sistemas de envases retornables"},{"id":"i3","texto":"Mejorar el reciclaje"},{"id":"i4","texto":"Limpiar playas"}],"extremos":["Más alta","Más baja"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cerrar la canilla antes que secar el piso.","valores":{"i1":"prevenir","i2":"reutilizar","i3":"reciclar","i4":"remediar"}}},{"slug":"residuos-4.s5.p3","orden":3,"grupo":"residuos-4.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Rediseñar","cuerpo":["Muchos envases son difíciles de reciclar porque combinan capas de materiales distintos (plástico con aluminio, por ejemplo), tienen colores oscuros que las máquinas no detectan o etiquetas que no se separan. Rediseñarlos con un solo material, colores claros y etiquetas fáciles de quitar mejora mucho su reciclaje.","La Fundación Ellen MacArthur promueve una economía circular del plástico: eliminar lo innecesario, innovar para que lo necesario sea reutilizable o reciclable, y hacer que circule sin volverse residuo."]},"solucion":{}},{"slug":"residuos-4.s5.p4","orden":4,"grupo":"residuos-4.s5.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este diseño facilita o dificulta el reciclaje?","grupos":[{"id":"g1","nombre":"Facilita"},{"id":"g2","nombre":"Dificulta"}],"items":[{"id":"i1","texto":"Botella de un solo tipo de plástico transparente"},{"id":"i2","texto":"Envase multicapa de plástico y aluminio"},{"id":"i3","texto":"Etiqueta que se despega fácil"},{"id":"i4","texto":"Bandeja de plástico negro"},{"id":"i5","texto":"Tapa del mismo material que el envase"},{"id":"i6","texto":"Etiqueta pegada con adhesivo que no se separa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El reciclaje empieza mucho antes del tacho: en el diseño."}},{"slug":"residuos-4.s5.p5","orden":5,"grupo":"residuos-4.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Responsabilidad extendida y depósito","cuerpo":["Con la responsabilidad extendida del productor, como viste antes, las empresas que ponen envases en el mercado financian su recuperación, lo que las incentiva a diseñar mejor. Los sistemas de depósito y retorno cobran un pequeño monto extra por el envase, que se devuelve al entregarlo vacío: en varios países logran recuperar la gran mayoría de las botellas."]},"solucion":{}},{"slug":"residuos-4.s5.p6","orden":6,"grupo":"residuos-4.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un sistema de depósito y retorno.","items":[{"id":"i1","texto":"Al comprar una bebida se paga un depósito por la botella"},{"id":"i2","texto":"Al terminarla, la persona la devuelve"},{"id":"i3","texto":"Recupera el dinero del depósito"},{"id":"i4","texto":"La botella se reutiliza o se recicla"},{"id":"i5","texto":"Muy pocas botellas terminan en el ambiente"},{"id":"i6","texto":"El depósito se pierde siempre, devuelvas o no la botella"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un incentivo económico chico puede cambiar muchísimo el destino de un envase."}},{"slug":"residuos-4.s5.p7","orden":7,"grupo":"residuos-4.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los sistemas de depósito y retorno pueden lograr que se recupere la gran mayoría de las botellas.","razones":[{"id":"r1","texto":"Porque el dinero del depósito incentiva a devolver"},{"id":"r2","texto":"Porque las botellas vuelven solas"},{"id":"r3","texto":"Porque el depósito es obligatorio para los pájaros"}]},"solucion":{"valor":true,"explicacion":"En varios países que los aplican, la tasa de recuperación de botellas supera ampliamente la de los sistemas sin depósito.","clave":["r1"]}},{"slug":"residuos-4.s5.p8","orden":8,"grupo":"residuos-4.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prohibiciones y un tratado","cuerpo":["Muchas ciudades y países prohibieron o restringieron algunos plásticos de un solo uso: bolsas livianas, sorbetes, cubiertos, vasos. Funcionan mejor cuando hay alternativas reutilizables accesibles.","Desde 2022, los países de las Naciones Unidas negocian un tratado global para terminar con la contaminación por plásticos, que abarque todo el ciclo de vida. Las negociaciones son difíciles, porque hay intereses muy distintos entre países productores y consumidores."]},"solucion":{}},{"slug":"residuos-4.s5.p9","orden":9,"grupo":"residuos-4.s5.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas contra el plástico actúan antes de que exista el residuo? Marcá todas.","opciones":[{"id":"o1","texto":"Prohibir bolsas livianas de un solo uso"},{"id":"o2","texto":"Sistemas de envases retornables"},{"id":"o3","texto":"Rediseñar para usar menos material"},{"id":"o4","texto":"Venta a granel con envase propio"},{"id":"o5","texto":"Limpiar playas los fines de semana"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las medidas \"aguas arriba\" evitan el problema; las de limpieza lo remedian."}},{"slug":"residuos-4.s5.p10","orden":10,"grupo":"residuos-4.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con cómo funciona.","izquierda":[{"id":"a1","texto":"Responsabilidad extendida"},{"id":"a2","texto":"Depósito y retorno"},{"id":"a3","texto":"Prohibición"},{"id":"a4","texto":"Rediseño"}],"derecha":[{"id":"b1","texto":"El productor financia la recuperación"},{"id":"b2","texto":"Se devuelve dinero al entregar el envase"},{"id":"b3","texto":"Se deja de vender un producto de un solo uso"},{"id":"b4","texto":"El envase se hace más fácil de reciclar o reutilizar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Herramientas distintas que se combinan en las políticas más exitosas."}},{"slug":"residuos-4.s5.p11","orden":11,"grupo":"residuos-4.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una ciudad prohíbe las bolsas livianas. ¿Qué hace más probable que la medida funcione?","opciones":[{"id":"o1","texto":"Que haya bolsas reutilizables accesibles"},{"id":"o2","texto":"Que la prohibición se anuncie sin ninguna explicación"},{"id":"o3","texto":"Que se reemplacen por bolsas más gruesas de un solo uso"},{"id":"o4","texto":"Que no se controle su cumplimiento"}]},"solucion":{"clave":["o1"],"explicacion":"Las prohibiciones funcionan mejor con alternativas, comunicación y control.","por_opcion":{"o3":"Si la bolsa gruesa también se tira, puede empeorar el problema."}}},{"slug":"residuos-4.s5.p12","orden":12,"grupo":"residuos-4.s5.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad se venden 1.000.000 botellas por mes. Sin depósito se recupera el 40 %; con depósito, el 90 %. ¿Cuántas botellas más por mes se recuperan con depósito?","unidad":"botellas","decimales":0},"solucion":{"valor":500000,"tolerancia":10000,"explicacion":"1.000.000 × (90 − 40) ÷ 100 = 500.000 botellas más por mes que no terminan en el ambiente ni en el relleno."}},{"slug":"residuos-4.s5.p12.v2","orden":12,"grupo":"residuos-4.s5.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad se venden 500.000 botellas por mes. Sin depósito se recupera el 30 %; con depósito, el 85 %. ¿Cuántas botellas más por mes se recuperan con depósito?","unidad":"botellas","decimales":0},"solucion":{"valor":275000,"tolerancia":5500,"explicacion":"500.000 × (85 − 30) ÷ 100 = 275.000 botellas más por mes que no terminan en el ambiente ni en el relleno."}},{"slug":"residuos-4.s5.p12.v3","orden":12,"grupo":"residuos-4.s5.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad se venden 2.000.000 botellas por mes. Sin depósito se recupera el 50 %; con depósito, el 95 %. ¿Cuántas botellas más por mes se recuperan con depósito?","unidad":"botellas","decimales":0},"solucion":{"valor":900000,"tolerancia":18000,"explicacion":"2.000.000 × (95 − 50) ÷ 100 = 900.000 botellas más por mes que no terminan en el ambiente ni en el relleno."}},{"slug":"residuos-4.s5.p13","orden":13,"grupo":"residuos-4.s5.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Prohibiremos las bolsas livianas y promoveremos las reutilizables."},{"id":"s2","texto":"Reemplazaremos los sorbetes de plástico por sorbetes de plástico \"oxodegradable\"."},{"id":"s3","texto":"Implementaremos un sistema de depósito para botellas."},{"id":"s4","texto":"Como vamos a limpiar la playa, no hace falta reducir nada."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las soluciones que funcionan atacan la causa y combinan herramientas.","por_opcion":{"s2":"Los oxodegradables se fragmentan en microplásticos: no es una solución.","s4":"Limpiar sin reducir es secar el piso con la canilla abierta."}}},{"slug":"residuos-4.s5.p14","orden":14,"grupo":"residuos-4.s5.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las mejores soluciones contra el plástico empiezan por {{0}}; el sistema que devuelve dinero al entregar el envase es el de {{1}} y retorno; y desde 2022 se negocia un {{2}} global.","banco":[{"id":"w1","texto":"reducir"},{"id":"w2","texto":"depósito"},{"id":"w3","texto":"tratado"},{"id":"w4","texto":"limpiar"},{"id":"w5","texto":"descuento"},{"id":"w6","texto":"mundial de fútbol"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre las soluciones al plástico."}},{"slug":"residuos-4.s5.p15","orden":15,"grupo":"residuos-4.s5.p15","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción actúa sobre la causa o sobre la consecuencia?","grupos":[{"id":"g1","nombre":"Causa"},{"id":"g2","nombre":"Consecuencia"}],"items":[{"id":"i1","texto":"Eliminar envases innecesarios"},{"id":"i2","texto":"Limpiar una playa"},{"id":"i3","texto":"Rediseñar para reciclar"},{"id":"i4","texto":"Sacar plástico de un arroyo con una red"},{"id":"i5","texto":"Retornables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Las dos hacen falta, pero sin actuar sobre la causa, la consecuencia no termina nunca."}}]},{"slug":"residuos-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el problema del plástico","bajada_es":"Producción, destinos, microplásticos, mares y soluciones, mezclados.","minutos":8,"pasos":[{"slug":"residuos-4.s6.p1","orden":1,"grupo":"residuos-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El problema del plástico». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el relevamiento de la costanera","bajada_es":"Un grupo de voluntarios limpió una costanera y clasificó lo que encontró. Con los datos, proponé qué hacer.","minutos":10,"pasos":[{"slug":"residuos-4.s7.p1","orden":1,"grupo":"residuos-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["En una jornada de limpieza de 1 km de costanera se juntaron 2.000 objetos: 600 colillas de cigarrillo, 400 envoltorios de golosinas y snacks, 300 tapitas, 250 botellas plásticas, 200 bolsas, 150 sorbetes y 100 objetos de otros materiales.","El municipio quiere usar los datos para tomar medidas."]},"solucion":{}},{"slug":"residuos-4.s7.p2","orden":2,"grupo":"residuos-4.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de los objetos eran colillas de cigarrillo?","unidad":"%","decimales":0,"contexto":"600 colillas de 2.000 objetos en total."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"600 ÷ 2.000 × 100 = 30 %. Las colillas tienen filtros de acetato de celulosa, un plástico, y suelen ser el residuo más encontrado en limpiezas de playas."}},{"slug":"residuos-4.s7.p3","orden":3,"grupo":"residuos-4.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos objetos eran envases o partes de envases de bebidas (botellas y tapitas)?","unidad":"objetos","decimales":0,"contexto":"250 botellas y 300 tapitas."},"solucion":{"valor":550,"tolerancia":11,"explicacion":"250 botellas + 300 tapitas = 550 objetos, más de un cuarto del total."}},{"slug":"residuos-4.s7.p4","orden":4,"grupo":"residuos-4.s7.p4","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los residuos por cantidad encontrada, de más a menos.","items":[{"id":"i1","texto":"Colillas"},{"id":"i2","texto":"Envoltorios"},{"id":"i3","texto":"Tapitas"},{"id":"i4","texto":"Botellas"},{"id":"i5","texto":"Sorbetes"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los datos muestran dónde conviene actuar primero.","valores":{"i1":"600","i2":"400","i3":"300","i4":"250","i5":"150"}}},{"slug":"residuos-4.s7.p5","orden":5,"grupo":"residuos-4.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Asigná a cada residuo una medida adecuada.","grupos":[{"id":"g1","nombre":"Ceniceros y campañas"},{"id":"g2","nombre":"Depósito y retorno o retornables"},{"id":"g3","nombre":"Prohibición o alternativas reutilizables"}],"items":[{"id":"i1","texto":"Colillas"},{"id":"i2","texto":"Botellas"},{"id":"i3","texto":"Sorbetes"},{"id":"i4","texto":"Tapitas"},{"id":"i5","texto":"Bolsas livianas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g2","i5":"g3"},"explicacion":"Cada tipo de residuo tiene su herramienta más efectiva."}},{"slug":"residuos-4.s7.p6","orden":6,"grupo":"residuos-4.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las colillas son un problema, aunque sean chicas?","opciones":[{"id":"o1","texto":"Porque su filtro es plástico y tóxico"},{"id":"o2","texto":"Porque son de papel y se degradan en un día"},{"id":"o3","texto":"Porque ocupan mucho espacio en la playa"},{"id":"o4","texto":"Porque atraen a los pingüinos de la zona"}]},"solucion":{"clave":["o1"],"explicacion":"El filtro de acetato de celulosa es un plástico que puede tardar años en degradarse y suelta sustancias tóxicas en el agua.","por_opcion":{"o3":"Ocupan poco; el problema es su material y las sustancias que liberan."}}},{"slug":"residuos-4.s7.p7","orden":7,"grupo":"residuos-4.s7.p7","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas propondrías al municipio con estos datos? Marcá todas las razonables.","opciones":[{"id":"o1","texto":"Ceniceros y campañas sobre colillas en la costanera"},{"id":"o2","texto":"Promover bebederos y botellas reutilizables"},{"id":"o3","texto":"Restringir sorbetes y bolsas de un solo uso en los paradores"},{"id":"o4","texto":"Repetir el relevamiento para ver si las medidas funcionan"},{"id":"o5","texto":"Solo organizar más limpiezas sin cambiar nada más"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Datos, medidas específicas y un nuevo relevamiento para evaluar: ciencia ciudadana aplicada."}},{"slug":"residuos-4.s7.p8","orden":8,"grupo":"residuos-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio anuncia su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pondremos ceniceros cada 100 metros de costanera."},{"id":"s2","texto":"Los paradores entregarán sorbetes solo si se piden, y de materiales reutilizables."},{"id":"s3","texto":"Como las colillas son chiquitas, no vale la pena ocuparse."},{"id":"s4","texto":"No volveremos a medir: ya sabemos lo que hay."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Medir, actuar y volver a medir: así se sabe si un plan funciona.","por_opcion":{"s3":"Son el residuo más frecuente y liberan sustancias tóxicas.","s4":"Sin medir de nuevo, no se sabe si las medidas funcionaron."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"residuos-5","rama":"residuos","orden":5,"nivel":3,"titulo_es":"Gestión integral de residuos en la ciudad","bajada_es":"De la vereda al relleno sanitario: cómo se diseña, se calcula y se mejora el sistema de residuos de un municipio, y cómo se cierra un basural.","objetivos_es":["Describir las etapas de la gestión integral de residuos sólidos urbanos","Planificar un estudio de caracterización y calcular la generación de un municipio","Diseñar la separación en origen y la recolección diferenciada","Dimensionar plantas de clasificación y compostaje","Explicar cómo funciona un relleno sanitario y cómo se cierra un basural"],"repasa":["residuos-1","residuos-2","residuos-3","consumo-3"],"requiere_tronco":3,"fuentes":["basurales-ar","chequeado-basurales","ley-25916-residuos","ley-1854-basura-cero","ceamse","faccyr","bm-what-a-waste","epa"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-5.s1","orden":1,"tipo":"leccion","titulo_es":"Un sistema, no un camión","bajada_es":"Generación, separación, recolección, transferencia, tratamiento y disposición final: la gestión integral de los residuos urbanos.","minutos":11,"pasos":[{"slug":"residuos-5.s1.p1","orden":1,"grupo":"residuos-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La gestión integral","cuerpo":["La gestión integral de residuos sólidos urbanos (GIRSU) mira todo el recorrido de la basura como un sistema: generación (cuánto y qué se produce), disposición inicial (cómo se separa y se saca), recolección, transferencia (cuando hay que llevarla lejos, se pasa a camiones más grandes), tratamiento (clasificación, reciclaje, compostaje) y disposición final (relleno sanitario). La Ley 25.916, de presupuestos mínimos, establece este enfoque en Argentina."],"lista":["Generación","Disposición inicial y separación","Recolección","Transferencia","Tratamiento","Disposición final"]},"solucion":{}},{"slug":"residuos-5.s1.p2","orden":2,"grupo":"residuos-5.s1.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas de la gestión integral de residuos.","items":[{"id":"i1","texto":"Generación en casas y comercios"},{"id":"i2","texto":"Separación y disposición inicial"},{"id":"i3","texto":"Recolección"},{"id":"i4","texto":"Transferencia a camiones más grandes"},{"id":"i5","texto":"Tratamiento: clasificación y compostaje"},{"id":"i6","texto":"Disposición final en un relleno sanitario"}]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Cada etapa condiciona a la siguiente: lo que no se separa al principio es muy difícil de recuperar después."}},{"slug":"residuos-5.s1.p3","orden":3,"grupo":"residuos-5.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números del país","cuerpo":["Según el Gobierno nacional, en Argentina se generan en promedio 1,15 kilos de residuos por habitante por día: casi 45.000 toneladas diarias, alrededor de 16,5 millones de toneladas por año. Y existen unos 5.000 basurales a cielo abierto, más de dos por municipio en promedio. Una parte importante de la población todavía tiene una disposición final inadecuada."],"destacado":{"valor":"≈ 5.000","texto":"basurales a cielo abierto existen en Argentina, según el Gobierno nacional: más de dos por municipio en promedio."}},"solucion":{}},{"slug":"residuos-5.s1.p4","orden":4,"grupo":"residuos-5.s1.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un municipio tiene 60.000 habitantes y cada uno genera 1,15 kg de residuos por día, ¿cuántas toneladas por día genera el municipio? Redondeá a un decimal.","unidad":"toneladas por día","decimales":1,"contexto":"60000 habitantes; 1,15 kg por persona por día."},"solucion":{"valor":69,"tolerancia":0.1,"explicacion":"60.000 × 1,15 = 69.000 kg ≈ 69 t por día. Es el punto de partida para dimensionar camiones y plantas."}},{"slug":"residuos-5.s1.p4.v2","orden":4,"grupo":"residuos-5.s1.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un municipio tiene 150.000 habitantes y cada uno genera 1,15 kg de residuos por día, ¿cuántas toneladas por día genera el municipio? Redondeá a un decimal.","unidad":"toneladas por día","decimales":1,"contexto":"150000 habitantes; 1,15 kg por persona por día."},"solucion":{"valor":172.5,"tolerancia":0.1,"explicacion":"150.000 × 1,15 = 172.500 kg ≈ 172,5 t por día. Es el punto de partida para dimensionar camiones y plantas."}},{"slug":"residuos-5.s1.p4.v3","orden":4,"grupo":"residuos-5.s1.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un municipio tiene 25.000 habitantes y cada uno genera 1,15 kg de residuos por día, ¿cuántas toneladas por día genera el municipio? Redondeá a un decimal.","unidad":"toneladas por día","decimales":1,"contexto":"25000 habitantes; 1,15 kg por persona por día."},"solucion":{"valor":28.7,"tolerancia":0.1,"explicacion":"25.000 × 1,15 = 28.750 kg ≈ 28,7 t por día. Es el punto de partida para dimensionar camiones y plantas."}},{"slug":"residuos-5.s1.p5","orden":5,"grupo":"residuos-5.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Regionalizar","cuerpo":["Muchos municipios son demasiado chicos para tener cada uno su propio relleno sanitario y sus plantas: los costos fijos serían enormes. Por eso se promueven sistemas regionales: varios municipios se asocian en un consorcio, comparten un relleno y plantas de tratamiento, y usan estaciones de transferencia para llevar los residuos. Así se logra escala y se evita que cada pueblo tenga su basural."]},"solucion":{}},{"slug":"residuos-5.s1.p6","orden":6,"grupo":"residuos-5.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué conviene regionalizar.","items":[{"id":"i1","texto":"Un pueblo chico genera pocas toneladas por día"},{"id":"i2","texto":"Un relleno sanitario tiene altos costos fijos"},{"id":"i3","texto":"Para un solo pueblo sería carísimo por tonelada"},{"id":"i4","texto":"Varios municipios se asocian y comparten el relleno"},{"id":"i5","texto":"El costo por tonelada baja y se cierran los basurales locales"},{"id":"i6","texto":"Cada pueblo construye su propio relleno aunque no pueda pagarlo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La escala compartida hace posible lo que un municipio solo no podría sostener."}},{"slug":"residuos-5.s1.p7","orden":7,"grupo":"residuos-5.s1.p7","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada etapa con su ejemplo.","izquierda":[{"id":"a1","texto":"Disposición inicial"},{"id":"a2","texto":"Transferencia"},{"id":"a3","texto":"Tratamiento"},{"id":"a4","texto":"Disposición final"}],"derecha":[{"id":"b1","texto":"Separar orgánicos y reciclables en casa"},{"id":"b2","texto":"Pasar la carga a camiones grandes para un viaje largo"},{"id":"b3","texto":"Compostar los restos de poda y comida"},{"id":"b4","texto":"Enterrar el rechazo en un relleno sanitario"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada etapa tiene su infraestructura y sus responsables."}},{"slug":"residuos-5.s1.p8","orden":8,"grupo":"residuos-5.s1.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La gestión de residuos de un municipio consiste solo en que pase el camión.","razones":[{"id":"r1","texto":"Porque incluye todo el sistema, no solo la recolección"},{"id":"r2","texto":"Porque los municipios no recogen residuos"},{"id":"r3","texto":"Porque los residuos desaparecen al subir al camión"}]},"solucion":{"valor":false,"explicacion":"El camión es una etapa. La gestión integral incluye separación, tratamiento, disposición final, cierre de basurales, educación y control.","clave":["r1"]}},{"slug":"residuos-5.s1.p9","orden":9,"grupo":"residuos-5.s1.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción pertenece a la recolección o al tratamiento?","grupos":[{"id":"g1","nombre":"Recolección"},{"id":"g2","nombre":"Tratamiento"}],"items":[{"id":"i1","texto":"Diseñar las rutas de los camiones"},{"id":"i2","texto":"Clasificar plásticos y cartón en una planta"},{"id":"i3","texto":"Definir la frecuencia de paso por barrio"},{"id":"i4","texto":"Compostar restos de poda"},{"id":"i5","texto":"Recuperar metales en una cinta de separación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Recolectar es mover; tratar es transformar y recuperar."}},{"slug":"residuos-5.s1.p10","orden":10,"grupo":"residuos-5.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si 45 millones de personas generan 1,15 kg de residuos por día cada una, ¿cuántas toneladas por día son? Redondeá a los mil más cercanos.","unidad":"toneladas por día","decimales":0,"contexto":"45000000 habitantes; 1,15 kg cada uno por día."},"solucion":{"valor":52000,"tolerancia":1000,"explicacion":"45 millones × 1,15 kg ≈ 52.000 toneladas por día: del orden de una tonelada cada dos segundos."}},{"slug":"residuos-5.s1.p10.v2","orden":10,"grupo":"residuos-5.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si 46 millones de personas generan 1,15 kg de residuos por día cada una, ¿cuántas toneladas por día son? Redondeá a los mil más cercanos.","unidad":"toneladas por día","decimales":0,"contexto":"46000000 habitantes; 1,15 kg cada uno por día."},"solucion":{"valor":53000,"tolerancia":1000,"explicacion":"46 millones × 1,15 kg ≈ 53.000 toneladas por día: del orden de una tonelada cada dos segundos."}},{"slug":"residuos-5.s1.p10.v3","orden":10,"grupo":"residuos-5.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si 44 millones de personas generan 1,15 kg de residuos por día cada una, ¿cuántas toneladas por día son? Redondeá a los mil más cercanos.","unidad":"toneladas por día","decimales":0,"contexto":"44000000 habitantes; 1,15 kg cada uno por día."},"solucion":{"valor":51000,"tolerancia":1000,"explicacion":"44 millones × 1,15 kg ≈ 51.000 toneladas por día: del orden de una tonelada cada dos segundos."}},{"slug":"residuos-5.s1.p11","orden":11,"grupo":"residuos-5.s1.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ventajas tiene un consorcio regional de residuos? Marcá todas.","opciones":[{"id":"o1","texto":"Menor costo por tonelada"},{"id":"o2","texto":"Rellenos sanitarios con mejor control técnico"},{"id":"o3","texto":"Posibilidad de cerrar basurales locales"},{"id":"o4","texto":"Cada municipio mantiene su propio basural"},{"id":"o5","texto":"Los residuos viajan sin ningún control"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La regionalización es una de las claves para terminar con los basurales."}},{"slug":"residuos-5.s1.p12","orden":12,"grupo":"residuos-5.s1.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos basurales a cielo abierto hay en Argentina, según el Gobierno nacional.","min":10,"max":100000,"paso":1,"unidad":"basurales","escala":"log"},"solucion":{"valor":5000,"banda":"log","explicacion":"Unos 5.000: más de dos por municipio en promedio. Cerrarlos exige tener antes un destino adecuado para los residuos."}},{"slug":"residuos-5.s1.p13","orden":13,"grupo":"residuos-5.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En Argentina se generan en promedio 1,15 kg de residuos por persona por día."},{"id":"s2","texto":"En el país quedan menos de diez basurales a cielo abierto."},{"id":"s3","texto":"La Ley 25.916 establece la gestión integral de residuos domiciliarios."},{"id":"s4","texto":"La transferencia consiste en enterrar la basura."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer el sistema completo permite ver dónde están los problemas.","por_opcion":{"s2":"Se estima que hay unos 5.000.","s4":"Es pasar la carga a camiones más grandes para viajes largos."}}},{"slug":"residuos-5.s1.p14","orden":14,"grupo":"residuos-5.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La gestión integral de residuos se conoce por la sigla {{0}}; en Argentina cada persona genera en promedio {{1}} kg de residuos por día; y cuando varios municipios se asocian para gestionarlos forman un {{2}}.","banco":[{"id":"w1","texto":"GIRSU"},{"id":"w2","texto":"1,15"},{"id":"w3","texto":"consorcio"},{"id":"w4","texto":"RAEE"},{"id":"w5","texto":"11,5"},{"id":"w6","texto":"basural"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para entender la gestión de residuos de una ciudad."}}]},{"slug":"residuos-5.s2","orden":2,"tipo":"leccion","titulo_es":"Conocer la basura","bajada_es":"El estudio de caracterización: cómo saber cuánto y qué se tira, antes de decidir qué plantas construir.","minutos":11,"pasos":[{"slug":"residuos-5.s2.p1","orden":1,"grupo":"residuos-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Caracterizar","cuerpo":["Antes de diseñar un sistema hay que conocer la basura: cuánto se genera y de qué está hecha. Eso se hace con un estudio de caracterización. Se toman muestras de los camiones de distintos barrios y días, se mezclan, se reduce la muestra de forma representativa (por ejemplo, con el método del cuarteo: se divide el montón en cuatro partes y se descartan dos opuestas, repitiendo hasta llegar a un tamaño manejable) y se separa y pesa cada fracción: orgánicos, papel y cartón, plásticos, vidrio, metales, textiles, peligrosos y otros."]},"solucion":{}},{"slug":"residuos-5.s2.p2","orden":2,"grupo":"residuos-5.s2.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de un estudio de caracterización.","items":[{"id":"i1","texto":"Elegir barrios y días representativos"},{"id":"i2","texto":"Tomar muestras de los camiones"},{"id":"i3","texto":"Mezclar y reducir la muestra por cuarteo"},{"id":"i4","texto":"Separar la muestra en fracciones"},{"id":"i5","texto":"Pesar cada fracción y calcular porcentajes"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un buen muestreo es la diferencia entre un dato que sirve y uno que engaña."}},{"slug":"residuos-5.s2.p3","orden":3,"grupo":"residuos-5.s2.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene tomar muestras en distintos barrios y épocas del año?","opciones":[{"id":"o1","texto":"Porque la composición cambia según el barrio y la estación"},{"id":"o2","texto":"Porque así el estudio tarda más y es más caro"},{"id":"o3","texto":"Porque un solo barrio representa a toda la ciudad"},{"id":"o4","texto":"Porque la ley obliga a visitar todos los barrios"}]},"solucion":{"clave":["o1"],"explicacion":"En verano hay más restos de fruta y poda; los barrios comerciales tiran más cartón: una sola muestra engaña.","por_opcion":{"o3":"Cada barrio y cada época tiene basura distinta."}}},{"slug":"residuos-5.s2.p4","orden":4,"grupo":"residuos-5.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué se encuentra","cuerpo":["En la mayoría de las ciudades argentinas, los orgánicos (restos de comida y poda) son la fracción más grande de la bolsa: suelen rondar entre el 40 y el 50 % del peso. Luego vienen el papel y el cartón, los plásticos, el vidrio y otros. Esto tiene una consecuencia enorme: sin tratar los orgánicos, ninguna estrategia puede reducir mucho lo que llega al relleno."],"datos":{"tipo":"barras","titulo":"Composición típica de los residuos de una ciudad argentina (valores de ejemplo)","unidad":"% del peso","filas":[{"etiqueta":"Orgánicos","valor":45},{"etiqueta":"Papel y cartón","valor":15},{"etiqueta":"Plásticos","valor":15},{"etiqueta":"Vidrio","valor":5},{"etiqueta":"Metales","valor":2},{"etiqueta":"Otros","valor":18}],"nota":"Valores ilustrativos: cada ciudad debe caracterizar su propia basura."}},"solucion":{}},{"slug":"residuos-5.s2.p5","orden":5,"grupo":"residuos-5.s2.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio genera 69 toneladas de residuos por día y el 45 % son orgánicos. ¿Cuántas toneladas de orgánicos por día genera? Redondeá a un decimal.","unidad":"toneladas","decimales":1,"contexto":"69 t por día; 45 % orgánicos."},"solucion":{"valor":31.1,"tolerancia":0.1,"explicacion":"69 × 45 % = 31,1 toneladas de orgánicos por día. Es la fracción más grande, y la que más conviene tratar."}},{"slug":"residuos-5.s2.p5.v2","orden":5,"grupo":"residuos-5.s2.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio genera 150 toneladas de residuos por día y el 50 % son orgánicos. ¿Cuántas toneladas de orgánicos por día genera? Redondeá a un decimal.","unidad":"toneladas","decimales":1,"contexto":"150 t por día; 50 % orgánicos."},"solucion":{"valor":75,"tolerancia":0.1,"explicacion":"150 × 50 % = 75 toneladas de orgánicos por día. Es la fracción más grande, y la que más conviene tratar."}},{"slug":"residuos-5.s2.p5.v3","orden":5,"grupo":"residuos-5.s2.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio genera 30 toneladas de residuos por día y el 40 % son orgánicos. ¿Cuántas toneladas de orgánicos por día genera? Redondeá a un decimal.","unidad":"toneladas","decimales":1,"contexto":"30 t por día; 40 % orgánicos."},"solucion":{"valor":12,"tolerancia":0.1,"explicacion":"30 × 40 % = 12 toneladas de orgánicos por día. Es la fracción más grande, y la que más conviene tratar."}},{"slug":"residuos-5.s2.p6","orden":6,"grupo":"residuos-5.s2.p6","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué fracción pertenece cada residuo en una caracterización?","grupos":[{"id":"g1","nombre":"Orgánicos"},{"id":"g2","nombre":"Reciclables secos"},{"id":"g3","nombre":"Peligrosos"}],"items":[{"id":"i1","texto":"Cáscaras de fruta"},{"id":"i2","texto":"Cajas de cartón"},{"id":"i3","texto":"Pilas"},{"id":"i4","texto":"Restos de poda"},{"id":"i5","texto":"Botellas de plástico"},{"id":"i6","texto":"Envases de insecticida"},{"id":"i7","texto":"Yerba usada"},{"id":"i8","texto":"Latas de aluminio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2"},"explicacion":"Separar bien en la muestra permite dimensionar cada planta."}},{"slug":"residuos-5.s2.p7","orden":7,"grupo":"residuos-5.s2.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el 45 % de la basura es orgánica, reciclar solo plásticos y cartón puede reducir a la mitad lo que va al relleno.","razones":[{"id":"r1","texto":"Porque los orgánicos son la fracción más grande"},{"id":"r2","texto":"Porque el plástico pesa más que todo lo demás"},{"id":"r3","texto":"Porque el cartón es orgánico"}]},"solucion":{"valor":false,"explicacion":"Plásticos y cartón juntos suelen ser cerca de un tercio. Sin tratar los orgánicos, es muy difícil reducir mucho lo que se entierra.","clave":["r1"]}},{"slug":"residuos-5.s2.p8","orden":8,"grupo":"residuos-5.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Densidad y volumen","cuerpo":["Además del peso, importa el volumen: los camiones y los rellenos se llenan por volumen. La basura suelta en una bolsa es liviana para su tamaño (baja densidad); un camión compactador la aprieta varias veces; y en el relleno se compacta todavía más. Por eso el mismo peso ocupa volúmenes muy distintos en cada etapa."]},"solucion":{}},{"slug":"residuos-5.s2.p9","orden":9,"grupo":"residuos-5.s2.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión compactador lleva la basura con una densidad de 0,5 toneladas por metro cúbico. ¿Cuántos metros cúbicos ocupan 10 toneladas?","unidad":"m³","decimales":0,"contexto":"10 t; densidad 0.5 t/m³."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"10 ÷ 0,5 = 20 m³. Conocer la densidad permite calcular cuántos viajes hacen falta y cuánto dura un relleno."}},{"slug":"residuos-5.s2.p9.v2","orden":9,"grupo":"residuos-5.s2.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión compactador lleva la basura con una densidad de 0,4 toneladas por metro cúbico. ¿Cuántos metros cúbicos ocupan 20 toneladas?","unidad":"m³","decimales":0,"contexto":"20 t; densidad 0.4 t/m³."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"20 ÷ 0,4 = 50 m³. Conocer la densidad permite calcular cuántos viajes hacen falta y cuánto dura un relleno."}},{"slug":"residuos-5.s2.p9.v3","orden":9,"grupo":"residuos-5.s2.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión compactador lleva la basura con una densidad de 0,6 toneladas por metro cúbico. ¿Cuántos metros cúbicos ocupan 15 toneladas?","unidad":"m³","decimales":0,"contexto":"15 t; densidad 0.6 t/m³."},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"15 ÷ 0,6 = 25 m³. Conocer la densidad permite calcular cuántos viajes hacen falta y cuánto dura un relleno."}},{"slug":"residuos-5.s2.p10","orden":10,"grupo":"residuos-5.s2.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Para qué sirve un estudio de caracterización? Marcá todo.","opciones":[{"id":"o1","texto":"Dimensionar una planta de compostaje"},{"id":"o2","texto":"Estimar cuánto material reciclable hay"},{"id":"o3","texto":"Planificar cuántos camiones hacen falta"},{"id":"o4","texto":"Medir si un programa de separación funciona"},{"id":"o5","texto":"Reemplazar la recolección de residuos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Sin datos de la basura, las plantas se construyen a ciegas."}},{"slug":"residuos-5.s2.p11","orden":11,"grupo":"residuos-5.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Caracterización"},{"id":"a2","texto":"Cuarteo"},{"id":"a3","texto":"Densidad"},{"id":"a4","texto":"Fracción"}],"derecha":[{"id":"b1","texto":"Estudio de cuánto y qué se tira"},{"id":"b2","texto":"Método para reducir una muestra de forma representativa"},{"id":"b3","texto":"Cuánto pesa un volumen de residuos"},{"id":"b4","texto":"Tipo de material dentro de la basura"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario técnico básico de la gestión de residuos."}},{"slug":"residuos-5.s2.p12","orden":12,"grupo":"residuos-5.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una caracterización muestra 30 % de cartón en la basura del centro comercial y 8 % en los barrios residenciales. ¿Qué conviene?","opciones":[{"id":"o1","texto":"Recolección diferenciada de cartón en el centro"},{"id":"o2","texto":"La misma recolección de siempre en toda la ciudad"},{"id":"o3","texto":"Prohibir el cartón en los comercios"},{"id":"o4","texto":"Dejar de caracterizar los barrios residenciales"}]},"solucion":{"clave":["o1"],"explicacion":"Los datos por zona permiten diseñar servicios donde rinden más.","por_opcion":{"o3":"Es poco práctico; conviene recuperarlo donde se concentra."}}},{"slug":"residuos-5.s2.p13","orden":13,"grupo":"residuos-5.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé el informe de un estudio y marcá los errores.","segmentos":[{"id":"s1","texto":"Tomamos muestras en barrios residenciales y comerciales."},{"id":"s2","texto":"Hicimos una sola muestra un día de enero y la usamos para todo el año."},{"id":"s3","texto":"Los orgánicos resultaron la fracción más grande."},{"id":"s4","texto":"Pesamos solo los reciclables porque el resto no importa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La calidad del estudio define la calidad de las decisiones.","por_opcion":{"s2":"La composición cambia según la estación; hacen falta varias campañas.","s4":"Hay que pesar todas las fracciones para dimensionar el sistema."}}},{"slug":"residuos-5.s2.p14","orden":14,"grupo":"residuos-5.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El estudio que mide cuánto y qué se tira es una {{0}}; el método para reducir una muestra dividiéndola en cuatro se llama {{1}}; y la fracción más grande de la basura suelen ser los {{2}}.","banco":[{"id":"w1","texto":"caracterización"},{"id":"w2","texto":"cuarteo"},{"id":"w3","texto":"orgánicos"},{"id":"w4","texto":"auditoría"},{"id":"w5","texto":"sorteo"},{"id":"w6","texto":"metales"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para conocer la basura antes de decidir."}}]},{"slug":"residuos-5.s3","orden":3,"tipo":"leccion","titulo_es":"Separar y recolectar","bajada_es":"Cómo se diseña un programa de separación en origen y una recolección diferenciada que funcionen.","minutos":12,"pasos":[{"slug":"residuos-5.s3.p1","orden":1,"grupo":"residuos-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Separación en origen","cuerpo":["Separar en origen es separar en casas y comercios, antes de que todo se mezcle en el camión. Lo más simple y efectivo suele ser pocas fracciones: por ejemplo, reciclables secos, orgánicos y resto. Un programa funciona si es fácil y claro (qué va en cada bolsa, qué día pasa el camión), si la gente ve que lo separado no se vuelve a mezclar y si hay comunicación constante. Cuanto más separado llega el material, más valor tiene."]},"solucion":{}},{"slug":"residuos-5.s3.p2","orden":2,"grupo":"residuos-5.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un programa de separación en origen funcione? Marcá todo.","opciones":[{"id":"o1","texto":"Pocas fracciones, fáciles de entender"},{"id":"o2","texto":"Días de recolección claros para cada fracción"},{"id":"o3","texto":"Que el material separado no se vuelva a mezclar"},{"id":"o4","texto":"Comunicación y devolución de resultados"},{"id":"o5","texto":"Cambiar las reglas cada mes"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Si la gente ve que lo separado se mezcla en el camión, deja de separar."}},{"slug":"residuos-5.s3.p3","orden":3,"grupo":"residuos-5.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos indicadores","cuerpo":["Para saber si un programa funciona se miran dos cosas. La participación: qué porcentaje de los hogares separa. Y la calidad o contaminación: qué porcentaje de lo que llega como \"reciclable\" en realidad no lo es (restos de comida, pañales, material sucio). Un programa con mucha participación pero muy contaminado puede recuperar poco."]},"solucion":{}},{"slug":"residuos-5.s3.p4","orden":4,"grupo":"residuos-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A la planta llegan 8 toneladas por día de \"reciclables\" y el 25 % es material contaminado que no sirve. ¿Cuántas toneladas se pueden recuperar realmente?","unidad":"toneladas","decimales":1,"contexto":"8 t; 25 % contaminado."},"solucion":{"valor":6,"tolerancia":0.1,"explicacion":"8 × 75 % = 6 toneladas. La contaminación de la fracción seca reduce lo recuperable y encarece la planta."}},{"slug":"residuos-5.s3.p4.v2","orden":4,"grupo":"residuos-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A la planta llegan 12 toneladas por día de \"reciclables\" y el 30 % es material contaminado que no sirve. ¿Cuántas toneladas se pueden recuperar realmente?","unidad":"toneladas","decimales":1,"contexto":"12 t; 30 % contaminado."},"solucion":{"valor":8.4,"tolerancia":0.1,"explicacion":"12 × 70 % = 8,4 toneladas. La contaminación de la fracción seca reduce lo recuperable y encarece la planta."}},{"slug":"residuos-5.s3.p4.v3","orden":4,"grupo":"residuos-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A la planta llegan 5 toneladas por día de \"reciclables\" y el 15 % es material contaminado que no sirve. ¿Cuántas toneladas se pueden recuperar realmente?","unidad":"toneladas","decimales":1,"contexto":"5 t; 15 % contaminado."},"solucion":{"valor":4.3,"tolerancia":0.1,"explicacion":"5 × 85 % = 4,3 toneladas. La contaminación de la fracción seca reduce lo recuperable y encarece la planta."}},{"slug":"residuos-5.s3.p5","orden":5,"grupo":"residuos-5.s3.p5","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la contaminación arruina el reciclaje.","items":[{"id":"i1","texto":"Alguien pone restos de comida en la bolsa de reciclables"},{"id":"i2","texto":"El cartón y el papel se mojan y se ensucian"},{"id":"i3","texto":"En la planta no se pueden recuperar"},{"id":"i4","texto":"Ese material termina en el relleno"},{"id":"i5","texto":"Baja lo recuperado y sube el costo"},{"id":"i6","texto":"La comida mejora la calidad del cartón"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una fracción seca limpia vale mucho más que una grande y sucia."}},{"slug":"residuos-5.s3.p6","orden":6,"grupo":"residuos-5.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La recolección","cuerpo":["La recolección suele ser la etapa más cara de todo el sistema: camiones, combustible, personal, mantenimiento. Se planifica con rutas, frecuencias y horarios. Con separación en origen se puede reorganizar: por ejemplo, pasar varios días por semana por los orgánicos, que se descomponen, y menos por los secos. Contenedores en la vereda o puntos limpios en los barrios cambian el costo y la comodidad del servicio."]},"solucion":{}},{"slug":"residuos-5.s3.p7","orden":7,"grupo":"residuos-5.s3.p7","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué fracción conviene recolectar con más frecuencia?","grupos":[{"id":"g1","nombre":"Con más frecuencia"},{"id":"g2","nombre":"Con menos frecuencia"}],"items":[{"id":"i1","texto":"Restos de comida"},{"id":"i2","texto":"Cartón seco"},{"id":"i3","texto":"Residuos de verdulerías"},{"id":"i4","texto":"Botellas de plástico limpias"},{"id":"i5","texto":"Latas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Lo que se descompone y huele necesita más frecuencia; lo seco puede esperar."}},{"slug":"residuos-5.s3.p8","orden":8,"grupo":"residuos-5.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio recolecta 69 toneladas por día. Cada camión carga 10 toneladas por viaje y hace 2 viajes por día. ¿Cuántos camiones hacen falta como mínimo? (Redondeá hacia arriba.)","unidad":"camiones","decimales":0,"contexto":"69 t por día; 10 t por viaje; 2 viajes por día."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"Cada camión lleva 20 t por día; 69 ÷ 20 = 3,45, así que hacen falta 4 camiones, más alguno de reserva para mantenimiento."}},{"slug":"residuos-5.s3.p8.v2","orden":8,"grupo":"residuos-5.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio recolecta 150 toneladas por día. Cada camión carga 12 toneladas por viaje y hace 3 viajes por día. ¿Cuántos camiones hacen falta como mínimo? (Redondeá hacia arriba.)","unidad":"camiones","decimales":0,"contexto":"150 t por día; 12 t por viaje; 3 viajes por día."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"Cada camión lleva 36 t por día; 150 ÷ 36 = 4,17, así que hacen falta 5 camiones, más alguno de reserva para mantenimiento."}},{"slug":"residuos-5.s3.p8.v3","orden":8,"grupo":"residuos-5.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio recolecta 30 toneladas por día. Cada camión carga 8 toneladas por viaje y hace 2 viajes por día. ¿Cuántos camiones hacen falta como mínimo? (Redondeá hacia arriba.)","unidad":"camiones","decimales":0,"contexto":"30 t por día; 8 t por viaje; 2 viajes por día."},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"Cada camión lleva 16 t por día; 30 ÷ 16 = 1,88, así que hacen falta 2 camiones, más alguno de reserva para mantenimiento."}},{"slug":"residuos-5.s3.p9","orden":9,"grupo":"residuos-5.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Incluir a quienes ya recuperan","cuerpo":["En muchas ciudades argentinas, los recuperadores urbanos y las cooperativas ya hacen gran parte de la recuperación de reciclables. Un buen sistema no los reemplaza: los integra, con recolección diferenciada a cargo de cooperativas, centros verdes con equipamiento, pagos por el servicio ambiental que prestan y condiciones de trabajo dignas. La Ley 1.854 de Basura Cero de la Ciudad de Buenos Aires, por ejemplo, incluyó a las cooperativas en la recolección de secos."]},"solucion":{}},{"slug":"residuos-5.s3.p10","orden":10,"grupo":"residuos-5.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué hace un buen sistema municipal con los recuperadores urbanos que ya trabajan en la ciudad?","opciones":[{"id":"o1","texto":"Los integra con pago y condiciones dignas"},{"id":"o2","texto":"Los prohíbe para que trabajen solo empresas"},{"id":"o3","texto":"Los ignora y los deja trabajar sin apoyo"},{"id":"o4","texto":"Les cobra por usar los contenedores"}]},"solucion":{"clave":["o1"],"explicacion":"Integrar a las cooperativas mejora la recuperación y la justicia del sistema.","por_opcion":{"o3":"Pierde una fuerza de recuperación clave y deja condiciones precarias."}}},{"slug":"residuos-5.s3.p11","orden":11,"grupo":"residuos-5.s3.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si muchos hogares separan pero la fracción reciclable llega muy contaminada, el programa igual recupera mucho.","razones":[{"id":"r1","texto":"Porque la contaminación reduce mucho lo recuperable"},{"id":"r2","texto":"Porque la participación no importa"},{"id":"r3","texto":"Porque la contaminación mejora los materiales"}]},"solucion":{"valor":false,"explicacion":"La contaminación reduce lo recuperable y puede arruinar lotes enteros. Participación y calidad tienen que ir juntas.","clave":["r1"]}},{"slug":"residuos-5.s3.p12","orden":12,"grupo":"residuos-5.s3.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un programa con pocas fracciones claras suele funcionar mejor que uno con muchas fracciones complicadas.","razones":[{"id":"r1","texto":"Porque lo simple aumenta la participación y reduce errores"},{"id":"r2","texto":"Porque separar no sirve para nada"},{"id":"r3","texto":"Porque las fracciones complicadas se reciclan mejor"}]},"solucion":{"valor":true,"explicacion":"Cuanto más simple, más gente participa y menos se equivoca. La separación fina puede hacerse después, en la planta.","clave":["r1"]}},{"slug":"residuos-5.s3.p13","orden":13,"grupo":"residuos-5.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de separación y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Usaremos tres fracciones: secos, orgánicos y resto."},{"id":"s2","texto":"El camión recogerá todo junto para ahorrar viajes."},{"id":"s3","texto":"Mediremos participación y contaminación cada mes."},{"id":"s4","texto":"Las cooperativas de recuperadores quedarán afuera del sistema."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan de separación se gana o se pierde en la confianza de los vecinos.","por_opcion":{"s2":"Si se mezcla en el camión, se pierde la separación y la confianza de los vecinos.","s4":"Conviene integrarlas: ya hacen gran parte de la recuperación."}}},{"slug":"residuos-5.s3.p14","orden":14,"grupo":"residuos-5.s3.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada indicador con lo que mide.","izquierda":[{"id":"a1","texto":"Participación"},{"id":"a2","texto":"Contaminación"},{"id":"a3","texto":"Tasa de recuperación"},{"id":"a4","texto":"Generación per cápita"}],"derecha":[{"id":"b1","texto":"Porcentaje de hogares que separan"},{"id":"b2","texto":"Porcentaje de material que no corresponde"},{"id":"b3","texto":"Porcentaje del total que se recupera"},{"id":"b4","texto":"Kilos por persona por día"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Sin indicadores no se sabe si el sistema mejora."}},{"slug":"residuos-5.s3.p15","orden":15,"grupo":"residuos-5.s3.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Separar en casas y comercios es separar en {{0}}; el porcentaje de hogares que separa es la {{1}}; y la etapa más cara del sistema suele ser la {{2}}.","banco":[{"id":"w1","texto":"origen"},{"id":"w2","texto":"participación"},{"id":"w3","texto":"recolección"},{"id":"w4","texto":"destino"},{"id":"w5","texto":"contaminación"},{"id":"w6","texto":"disposición"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para diseñar la separación y la recolección."}}]},{"slug":"residuos-5.s4","orden":4,"tipo":"leccion","titulo_es":"Plantas de tratamiento","bajada_es":"Plantas de clasificación, compostaje y biodigestión: qué entra, qué sale y cuánto rinde cada una.","minutos":11,"pasos":[{"slug":"residuos-5.s4.p1","orden":1,"grupo":"residuos-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Planta de clasificación","cuerpo":["En una planta de clasificación, la fracción seca pasa por cintas donde trabajadores y máquinas separan cartón, distintos plásticos, vidrio y metales. Los imanes separan el acero; otras máquinas, el aluminio. Lo recuperado se enfarda y se vende a la industria. Lo que no se puede recuperar se llama rechazo y va al relleno. Cuanto más limpia llega la fracción seca, menor el rechazo."]},"solucion":{}},{"slug":"residuos-5.s4.p2","orden":2,"grupo":"residuos-5.s4.p2","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de la fracción seca en una planta de clasificación.","items":[{"id":"i1","texto":"Llega el camión con reciclables"},{"id":"i2","texto":"Se descarga en la playa de recepción"},{"id":"i3","texto":"La cinta lleva el material a los puestos de separación"},{"id":"i4","texto":"Se separan cartón, plásticos, vidrio y metales"},{"id":"i5","texto":"Se enfarda lo recuperado y el rechazo va al relleno"},{"id":"i6","texto":"Todo el material se entierra sin separar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una planta de clasificación convierte residuos mezclados en materias primas."}},{"slug":"residuos-5.s4.p3","orden":3,"grupo":"residuos-5.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A una planta de clasificación entran 10 toneladas por día de reciclables y el 30 % es rechazo. ¿Cuántas toneladas por día se venden como material recuperado?","unidad":"toneladas","decimales":1,"contexto":"10 t por día; rechazo del 30 %."},"solucion":{"valor":7,"tolerancia":0.1,"explicacion":"10 × 70 % = 7 toneladas recuperadas. El rechazo depende mucho de la calidad de la separación en origen."}},{"slug":"residuos-5.s4.p3.v2","orden":3,"grupo":"residuos-5.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A una planta de clasificación entran 15 toneladas por día de reciclables y el 20 % es rechazo. ¿Cuántas toneladas por día se venden como material recuperado?","unidad":"toneladas","decimales":1,"contexto":"15 t por día; rechazo del 20 %."},"solucion":{"valor":12,"tolerancia":0.1,"explicacion":"15 × 80 % = 12 toneladas recuperadas. El rechazo depende mucho de la calidad de la separación en origen."}},{"slug":"residuos-5.s4.p3.v3","orden":3,"grupo":"residuos-5.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A una planta de clasificación entran 8 toneladas por día de reciclables y el 40 % es rechazo. ¿Cuántas toneladas por día se venden como material recuperado?","unidad":"toneladas","decimales":1,"contexto":"8 t por día; rechazo del 40 %."},"solucion":{"valor":4.8,"tolerancia":0.1,"explicacion":"8 × 60 % = 4,8 toneladas recuperadas. El rechazo depende mucho de la calidad de la separación en origen."}},{"slug":"residuos-5.s4.p4","orden":4,"grupo":"residuos-5.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Compostar a escala","cuerpo":["Una planta de compostaje municipal trata restos de poda y, cuando hay separación, restos de comida. Se arman pilas o hileras que se voltean para oxigenarlas; se controla la humedad y la temperatura, que sube a más de 55 °C y elimina patógenos y semillas. Después de unos meses queda compost. Durante el proceso se pierde agua y parte de la materia orgánica se convierte en CO₂: el compost final pesa, en general, entre un tercio y la mitad de lo que entró."]},"solucion":{}},{"slug":"residuos-5.s4.p5","orden":5,"grupo":"residuos-5.s4.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una planta recibe 30 toneladas de orgánicos por día. Si el compost final pesa el 40 % de lo que entra, ¿cuántas toneladas de compost produce por día?","unidad":"toneladas","decimales":1,"contexto":"30 t de orgánicos; rendimiento del 40 %."},"solucion":{"valor":12,"tolerancia":0.1,"explicacion":"30 × 40 % = 12 toneladas de compost. El resto se va como agua y CO₂ durante el proceso."}},{"slug":"residuos-5.s4.p5.v2","orden":5,"grupo":"residuos-5.s4.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una planta recibe 20 toneladas de orgánicos por día. Si el compost final pesa el 35 % de lo que entra, ¿cuántas toneladas de compost produce por día?","unidad":"toneladas","decimales":1,"contexto":"20 t de orgánicos; rendimiento del 35 %."},"solucion":{"valor":7,"tolerancia":0.1,"explicacion":"20 × 35 % = 7 toneladas de compost. El resto se va como agua y CO₂ durante el proceso."}},{"slug":"residuos-5.s4.p5.v3","orden":5,"grupo":"residuos-5.s4.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una planta recibe 50 toneladas de orgánicos por día. Si el compost final pesa el 45 % de lo que entra, ¿cuántas toneladas de compost produce por día?","unidad":"toneladas","decimales":1,"contexto":"50 t de orgánicos; rendimiento del 45 %."},"solucion":{"valor":22.5,"tolerancia":0.1,"explicacion":"50 × 45 % = 22,5 toneladas de compost. El resto se va como agua y CO₂ durante el proceso."}},{"slug":"residuos-5.s4.p6","orden":6,"grupo":"residuos-5.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el compost pesa mucho menos que los residuos orgánicos que entraron?","opciones":[{"id":"o1","texto":"Se pierde agua y parte de la materia se vuelve CO₂"},{"id":"o2","texto":"Porque se le saca todo lo que no es tierra"},{"id":"o3","texto":"Porque se vende por kilo a menor precio"},{"id":"o4","texto":"Porque el compost se evapora al sol"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con el compost casero: los microorganismos respiran y el agua se evapora.","por_opcion":{"o3":"El precio no cambia el peso: es un proceso físico y biológico."}}},{"slug":"residuos-5.s4.p7","orden":7,"grupo":"residuos-5.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Biodigestores","cuerpo":["Otra opción para los orgánicos es la biodigestión: en tanques cerrados y sin oxígeno, bacterias descomponen los residuos y producen biogás, rico en metano, que puede usarse para generar electricidad o calor. Lo que queda, el digerido, puede usarse como enmienda del suelo. Es útil para residuos muy húmedos, como los de la industria alimentaria o los mercados."]},"solucion":{}},{"slug":"residuos-5.s4.p8","orden":8,"grupo":"residuos-5.s4.p8","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tratamiento con su producto principal.","izquierda":[{"id":"a1","texto":"Planta de clasificación"},{"id":"a2","texto":"Compostaje"},{"id":"a3","texto":"Biodigestión"},{"id":"a4","texto":"Relleno sanitario"}],"derecha":[{"id":"b1","texto":"Materiales para reciclar"},{"id":"b2","texto":"Compost para el suelo"},{"id":"b3","texto":"Biogás para energía"},{"id":"b4","texto":"Disposición segura del rechazo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada tratamiento transforma una fracción distinta."}},{"slug":"residuos-5.s4.p9","orden":9,"grupo":"residuos-5.s4.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tratamiento conviene más para cada residuo?","grupos":[{"id":"g1","nombre":"Compostaje"},{"id":"g2","nombre":"Biodigestión"},{"id":"g3","nombre":"Clasificación y reciclaje"}],"items":[{"id":"i1","texto":"Restos de poda"},{"id":"i2","texto":"Residuos húmedos de un mercado de frutas"},{"id":"i3","texto":"Cartón de comercios"},{"id":"i4","texto":"Hojas secas de la plaza"},{"id":"i5","texto":"Descartes de una industria láctea"},{"id":"i6","texto":"Botellas de plástico limpias"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Elegir bien el tratamiento para cada flujo aumenta lo que se aprovecha."}},{"slug":"residuos-5.s4.p10","orden":10,"grupo":"residuos-5.s4.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La temperatura alta de una pila de compost bien manejada ayuda a eliminar patógenos y semillas de malezas.","razones":[{"id":"r1","texto":"Porque el calor de la pila elimina patógenos y semillas"},{"id":"r2","texto":"Porque el compost nunca se calienta"},{"id":"r3","texto":"Porque los patógenos resisten cualquier temperatura"}]},"solucion":{"valor":true,"explicacion":"Cuando la pila supera los 55 °C durante varios días, muchos patógenos y semillas mueren. Por eso se controla la temperatura en las plantas.","clave":["r1"]}},{"slug":"residuos-5.s4.p11","orden":11,"grupo":"residuos-5.s4.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué se controla en una pila de compost de una planta municipal? Marcá todo.","opciones":[{"id":"o1","texto":"La humedad"},{"id":"o2","texto":"La temperatura"},{"id":"o3","texto":"La oxigenación, con volteos"},{"id":"o4","texto":"Que no entren materiales peligrosos"},{"id":"o5","texto":"El color del cartel de la planta"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un compost de calidad depende del control del proceso y de lo que entra."}},{"slug":"residuos-5.s4.p12","orden":12,"grupo":"residuos-5.s4.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos destinos para 1 tonelada de restos de poda, del de más valor al de menos.","items":[{"id":"i1","texto":"Compostarla y usar el compost en plazas"},{"id":"i2","texto":"Triturarla como cobertura del suelo"},{"id":"i3","texto":"Enterrarla en un relleno sanitario"},{"id":"i4","texto":"Quemarla a cielo abierto"}],"extremos":["Más valor","Menos valor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo viste con la escalera de los residuos: enterrar o quemar orgánicos es desperdiciar un recurso.","valores":{"i1":"devuelve nutrientes al suelo","i2":"buen uso directo","i3":"se pierde y genera metano","i4":"contamina el aire"}}},{"slug":"residuos-5.s4.p13","orden":13,"grupo":"residuos-5.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este proyecto de planta y marcá los errores.","segmentos":[{"id":"s1","texto":"La planta de compostaje controlará humedad y temperatura."},{"id":"s2","texto":"El compost final pesará lo mismo que los residuos que entren."},{"id":"s3","texto":"El rechazo de la clasificación irá al relleno sanitario."},{"id":"s4","texto":"Mezclaremos pilas en la planta de compost para aprovecharlas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una planta bien diseñada separa lo que se trata de lo que contamina.","por_opcion":{"s2":"Pesa bastante menos: se pierde agua y parte se vuelve CO₂.","s4":"Las pilas son residuos peligrosos: contaminan el compost."}}},{"slug":"residuos-5.s4.p14","orden":14,"grupo":"residuos-5.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que una planta de clasificación no puede recuperar se llama {{0}}; el tratamiento sin oxígeno que produce biogás es la {{1}}; y el compost final pesa entre un {{2}} y la mitad de lo que entró.","banco":[{"id":"w1","texto":"rechazo"},{"id":"w2","texto":"biodigestión"},{"id":"w3","texto":"tercio"},{"id":"w4","texto":"residuo"},{"id":"w5","texto":"incineración"},{"id":"w6","texto":"doble"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave sobre las plantas de tratamiento."}}]},{"slug":"residuos-5.s5","orden":5,"tipo":"leccion","titulo_es":"Relleno sanitario y cierre de basurales","bajada_es":"Cómo se construye y se opera un relleno sanitario, y cómo se cierra un basural sin dejar a nadie afuera.","minutos":10,"pasos":[{"slug":"residuos-5.s5.p1","orden":1,"grupo":"residuos-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un relleno sanitario por dentro","cuerpo":["Un relleno sanitario es una obra de ingeniería. El fondo se impermeabiliza con capas de arcilla compactada y membranas plásticas para que los líquidos no lleguen a las napas. Esos líquidos, llamados lixiviados, se captan con cañerías y se tratan. Los residuos se compactan en celdas y se cubren cada día con tierra. Caños verticales captan el biogás, que se quema o se usa para generar energía. Pozos de monitoreo controlan el agua subterránea durante décadas, incluso después del cierre."]},"solucion":{}},{"slug":"residuos-5.s5.p2","orden":2,"grupo":"residuos-5.s5.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada componente del relleno con su función.","izquierda":[{"id":"a1","texto":"Impermeabilización del fondo"},{"id":"a2","texto":"Captación de lixiviados"},{"id":"a3","texto":"Cobertura diaria"},{"id":"a4","texto":"Captación de biogás"},{"id":"a5","texto":"Pozos de monitoreo"}],"derecha":[{"id":"b1","texto":"Evitar que los líquidos lleguen a las napas"},{"id":"b2","texto":"Recoger los líquidos para tratarlos"},{"id":"b3","texto":"Evitar olores, vectores y voladuras"},{"id":"b4","texto":"Evitar la liberación de metano"},{"id":"b5","texto":"Controlar el agua subterránea"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada componente previene un impacto distinto del basural."}},{"slug":"residuos-5.s5.p3","orden":3,"grupo":"residuos-5.s5.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se forma el lixiviado.","items":[{"id":"i1","texto":"La lluvia cae sobre los residuos"},{"id":"i2","texto":"El agua se filtra entre la basura"},{"id":"i3","texto":"Arrastra sustancias de los residuos en descomposición"},{"id":"i4","texto":"Se acumula un líquido contaminante en el fondo"},{"id":"i5","texto":"En un relleno se capta y se trata; en un basural llega a las napas"},{"id":"i6","texto":"El lixiviado es agua potable filtrada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La diferencia entre un relleno y un basural está, en buena parte, en qué pasa con ese líquido."}},{"slug":"residuos-5.s5.p4","orden":4,"grupo":"residuos-5.s5.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno tiene 1.000.000 m³ de capacidad. Recibe 200 toneladas por día, que se compactan a 0,8 t/m³. ¿Cuántos años de vida útil tiene? Redondeá a un decimal.","unidad":"años","decimales":1,"contexto":"1000000 m³; 200 t por día; 0.8 t/m³."},"solucion":{"valor":11,"tolerancia":0.1,"explicacion":"Capacidad en toneladas: 1.000.000 × 0,8 = 800.000 t. Por año entran 73.000 t. Vida útil ≈ 11 años. Cada tonelada que no llega al relleno alarga su vida."}},{"slug":"residuos-5.s5.p4.v2","orden":4,"grupo":"residuos-5.s5.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno tiene 500.000 m³ de capacidad. Recibe 100 toneladas por día, que se compactan a 0,9 t/m³. ¿Cuántos años de vida útil tiene? Redondeá a un decimal.","unidad":"años","decimales":1,"contexto":"500000 m³; 100 t por día; 0.9 t/m³."},"solucion":{"valor":12.3,"tolerancia":0.1,"explicacion":"Capacidad en toneladas: 500.000 × 0,9 = 450.000 t. Por año entran 36.500 t. Vida útil ≈ 12,3 años. Cada tonelada que no llega al relleno alarga su vida."}},{"slug":"residuos-5.s5.p4.v3","orden":4,"grupo":"residuos-5.s5.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno tiene 2.000.000 m³ de capacidad. Recibe 400 toneladas por día, que se compactan a 1 t/m³. ¿Cuántos años de vida útil tiene? Redondeá a un decimal.","unidad":"años","decimales":1,"contexto":"2000000 m³; 400 t por día; 1 t/m³."},"solucion":{"valor":13.7,"tolerancia":0.1,"explicacion":"Capacidad en toneladas: 2.000.000 × 1 = 2.000.000 t. Por año entran 146.000 t. Vida útil ≈ 13,7 años. Cada tonelada que no llega al relleno alarga su vida."}},{"slug":"residuos-5.s5.p5","orden":5,"grupo":"residuos-5.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cerrar un basural","cuerpo":["Cerrar un basural no es solo poner un candado. Hay que tener antes un destino alternativo para los residuos (un relleno o un sistema regional), caracterizar el sitio, cubrir y sellar los residuos, controlar los gases y los líquidos, monitorear el agua, y después recuperar el terreno. Y muchas veces en el basural trabajan familias que recuperan materiales: un cierre justo incluye un plan para que puedan pasar a trabajar en plantas, cooperativas o nuevas actividades."]},"solucion":{}},{"slug":"residuos-5.s5.p6","orden":6,"grupo":"residuos-5.s5.p6","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para cerrar un basural.","items":[{"id":"i1","texto":"Garantizar un destino alternativo para los residuos"},{"id":"i2","texto":"Acordar un plan con las familias que trabajan en el basural"},{"id":"i3","texto":"Dejar de recibir residuos"},{"id":"i4","texto":"Cubrir, sellar y controlar gases y líquidos"},{"id":"i5","texto":"Monitorear el agua y recuperar el terreno"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin destino alternativo, el basural reaparece en otro lugar; sin plan social, el cierre deja familias sin ingresos."}},{"slug":"residuos-5.s5.p7","orden":7,"grupo":"residuos-5.s5.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué pasa si se cierra un basural sin un destino alternativo para los residuos?","opciones":[{"id":"o1","texto":"Aparecen basurales nuevos en otros lugares"},{"id":"o2","texto":"Los residuos dejan de generarse"},{"id":"o3","texto":"Los vecinos llevan la basura a un relleno lejano por su cuenta"},{"id":"o4","texto":"El basural se limpia solo"}]},"solucion":{"clave":["o1"],"explicacion":"Cerrar un basural es parte de un sistema: primero el destino, después el cierre.","por_opcion":{"o3":"Es poco probable: sin un sistema, la basura termina en otro terreno."}}},{"slug":"residuos-5.s5.p8","orden":8,"grupo":"residuos-5.s5.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta característica es de un relleno sanitario o de un basural a cielo abierto?","grupos":[{"id":"g1","nombre":"Relleno sanitario"},{"id":"g2","nombre":"Basural a cielo abierto"}],"items":[{"id":"i1","texto":"Fondo impermeabilizado"},{"id":"i2","texto":"Quemas frecuentes"},{"id":"i3","texto":"Cobertura diaria con tierra"},{"id":"i4","texto":"Lixiviados que llegan a las napas"},{"id":"i5","texto":"Monitoreo del agua subterránea"},{"id":"i6","texto":"Animales y personas sin protección entre los residuos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo viste en la base de la rama: el mismo residuo, dos destinos muy distintos."}},{"slug":"residuos-5.s5.p9","orden":9,"grupo":"residuos-5.s5.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un relleno sanitario deja de necesitar control apenas se cierra.","razones":[{"id":"r1","texto":"Porque sigue generando lixiviados y biogás por décadas"},{"id":"r2","texto":"Porque los residuos desaparecen al cerrarlo"},{"id":"r3","texto":"Porque los rellenos no generan gases"}]},"solucion":{"valor":false,"explicacion":"Los residuos siguen generando lixiviados y biogás durante décadas: hay que mantener el control y el monitoreo mucho después del cierre.","clave":["r1"]}},{"slug":"residuos-5.s5.p10","orden":10,"grupo":"residuos-5.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué incluye un cierre justo de un basural? Marcá todo.","opciones":[{"id":"o1","texto":"Un destino alternativo para los residuos"},{"id":"o2","texto":"Un plan de trabajo para las familias recuperadoras"},{"id":"o3","texto":"Control de gases y líquidos"},{"id":"o4","texto":"Monitoreo del agua"},{"id":"o5","texto":"Echar a las familias sin ninguna alternativa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un cierre ambiental que ignora a las personas termina fracasando."}},{"slug":"residuos-5.s5.p11","orden":11,"grupo":"residuos-5.s5.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan municipal y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Primero habilitaremos el relleno regional y después cerraremos el basural."},{"id":"s2","texto":"Cerraremos el basural mañana, aunque no haya otro destino."},{"id":"s3","texto":"Las familias que trabajan en el basural se sumarán a la planta de clasificación."},{"id":"s4","texto":"El relleno no necesitará impermeabilización porque el suelo es arcilloso."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan combina ingeniería, secuencia correcta e inclusión.","por_opcion":{"s2":"Sin destino alternativo aparecen nuevos basurales.","s4":"La impermeabilización con membranas y arcilla compactada es esencial."}}},{"slug":"residuos-5.s5.p12","orden":12,"grupo":"residuos-5.s5.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El líquido que se forma cuando el agua atraviesa los residuos se llama {{0}}; el gas rico en metano que se capta en un relleno es el {{1}}; y antes de cerrar un basural hace falta un destino {{2}}.","banco":[{"id":"w1","texto":"lixiviado"},{"id":"w2","texto":"biogás"},{"id":"w3","texto":"alternativo"},{"id":"w4","texto":"néctar"},{"id":"w5","texto":"oxígeno"},{"id":"w6","texto":"decorativo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la disposición final y el cierre de basurales."}},{"slug":"residuos-5.s5.p13","orden":13,"grupo":"residuos-5.s5.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno recibe 200 toneladas por día. Si un programa de compostaje y reciclaje reduce en un 30 % lo que llega, ¿cuántas toneladas por día deja de recibir?","unidad":"toneladas","decimales":0,"contexto":"200 t por día; reducción del 30 %."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"200 × 30 % = 60 toneladas por día menos. Eso alarga la vida útil del relleno y reduce su biogás y sus lixiviados."}},{"slug":"residuos-5.s5.p13.v2","orden":13,"grupo":"residuos-5.s5.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno recibe 100 toneladas por día. Si un programa de compostaje y reciclaje reduce en un 40 % lo que llega, ¿cuántas toneladas por día deja de recibir?","unidad":"toneladas","decimales":0,"contexto":"100 t por día; reducción del 40 %."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"100 × 40 % = 40 toneladas por día menos. Eso alarga la vida útil del relleno y reduce su biogás y sus lixiviados."}},{"slug":"residuos-5.s5.p13.v3","orden":13,"grupo":"residuos-5.s5.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno recibe 400 toneladas por día. Si un programa de compostaje y reciclaje reduce en un 25 % lo que llega, ¿cuántas toneladas por día deja de recibir?","unidad":"toneladas","decimales":0,"contexto":"400 t por día; reducción del 25 %."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"400 × 25 % = 100 toneladas por día menos. Eso alarga la vida útil del relleno y reduce su biogás y sus lixiviados."}}]},{"slug":"residuos-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: gestión integral de residuos","bajada_es":"Sistema, caracterización, separación, plantas, relleno y cierre de basurales, mezclados.","minutos":8,"pasos":[{"slug":"residuos-5.s6.p1","orden":1,"grupo":"residuos-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Gestión integral de residuos en la ciudad». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el plan GIRSU de Villa Serena","bajada_es":"Un municipio de 60.000 habitantes tiene un basural a cielo abierto y quiere un sistema integral. Con los datos, armá el plan.","minutos":10,"pasos":[{"slug":"residuos-5.s7.p1","orden":1,"grupo":"residuos-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Villa Serena tiene 60.000 habitantes que generan 1,15 kg de residuos por persona por día. Un estudio de caracterización mostró 45 % de orgánicos, 30 % de reciclables secos y 25 % de resto. Hoy todo va a un basural donde trabajan 40 familias recuperadoras. A 50 km hay un relleno sanitario regional que podría recibir sus residuos, y el municipio puede instalar una planta de clasificación y una de compostaje."]},"solucion":{}},{"slug":"residuos-5.s7.p2","orden":2,"grupo":"residuos-5.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de residuos por día genera Villa Serena?","unidad":"toneladas","decimales":0,"contexto":"60.000 habitantes; 1,15 kg por persona por día."},"solucion":{"valor":69,"tolerancia":1.3800000000000001,"explicacion":"60.000 × 1,15 kg = 69.000 kg = 69 toneladas por día."}},{"slug":"residuos-5.s7.p3","orden":3,"grupo":"residuos-5.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas por día de orgánicos podría tratar la planta de compostaje si llegaran todos separados? Redondeá a un decimal.","unidad":"toneladas","decimales":1,"contexto":"69 t por día; 45 % orgánicos."},"solucion":{"valor":31.1,"tolerancia":0.622,"explicacion":"69 × 45 % ≈ 31,1 toneladas por día. En la práctica, la participación no será total al principio."}},{"slug":"residuos-5.s7.p4","orden":4,"grupo":"residuos-5.s7.p4","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se compostara el 60 % de los orgánicos y se recuperara el 50 % de los secos, ¿cuántas toneladas por día seguirían yendo al relleno? Redondeá a un decimal.","unidad":"toneladas","decimales":1,"contexto":"69 t; 60 % de 31,05 t orgánicas y 50 % de 20,7 t secas."},"solucion":{"valor":40,"tolerancia":0.1,"explicacion":"Orgánicos: 69 × 45 % = 31,05 t, y se compostan 18,63 t. Secos: 69 × 30 % = 20,7 t, y se recuperan 10,35 t. Al relleno: 69 − 18,63 − 10,35 ≈ 40,0 t por día, un 42 % menos que hoy."}},{"slug":"residuos-5.s7.p5","orden":5,"grupo":"residuos-5.s7.p5","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas del plan.","items":[{"id":"i1","texto":"Acordar el envío de residuos al relleno regional"},{"id":"i2","texto":"Acordar con las 40 familias su incorporación a la planta de clasificación"},{"id":"i3","texto":"Lanzar la separación en origen con tres fracciones"},{"id":"i4","texto":"Poner en marcha las plantas de clasificación y compostaje"},{"id":"i5","texto":"Cerrar y sanear el basural"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Primero destino y acuerdo social; después separación y plantas; al final, el cierre del basural."}},{"slug":"residuos-5.s7.p6","orden":6,"grupo":"residuos-5.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué indicadores debería medir el municipio cada año? Marcá todos.","opciones":[{"id":"o1","texto":"Toneladas enviadas al relleno"},{"id":"o2","texto":"Participación y contaminación de la separación"},{"id":"o3","texto":"Toneladas de compost y de reciclables vendidos"},{"id":"o4","texto":"Ingresos de las familias recuperadoras"},{"id":"o5","texto":"Cantidad de bolsas de colores entregadas, sin más datos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Medir resultados, no solo actividades, permite corregir el plan."}},{"slug":"residuos-5.s7.p7","orden":7,"grupo":"residuos-5.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el relleno regional está a 50 km, conviene seguir usando el basural local.","razones":[{"id":"r1","texto":"Porque el basural contamina y la transferencia lo resuelve"},{"id":"r2","texto":"Porque 50 km es imposible de recorrer"},{"id":"r3","texto":"Porque los basurales no contaminan"}]},"solucion":{"valor":false,"explicacion":"El basural contamina el agua, el aire y la salud. Con una estación de transferencia, llevar los residuos a un relleno regional suele ser la opción responsable.","clave":["r1"]}},{"slug":"residuos-5.s7.p8","orden":8,"grupo":"residuos-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El concejo revisa el plan. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Separaremos en tres fracciones: orgánicos, secos y resto."},{"id":"s2","texto":"Las 40 familias recuperadoras quedarán afuera cuando cierre el basural."},{"id":"s3","texto":"Mediremos cada año cuánto va al relleno."},{"id":"s4","texto":"Cerraremos el basural antes de tener acordado el relleno regional."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan GIRSU exitoso combina números, secuencia correcta e inclusión social.","por_opcion":{"s2":"Un cierre justo las incorpora a la planta o a cooperativas.","s4":"Sin destino alternativo aparecen nuevos basurales."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"residuos-6","rama":"residuos","orden":6,"nivel":3,"titulo_es":"Residuos peligrosos y especiales","bajada_es":"Pilas, lavandina, envases de agroquímicos, residuos de hospital, neumáticos y aparatos viejos: por qué no van a la bolsa común y qué camino tienen que seguir.","objetivos_es":["Reconocer las características que hacen peligroso a un residuo y leer sus pictogramas","Explicar la cadena de custodia de la Ley 24.051 y el Convenio de Basilea","Manejar con seguridad los residuos peligrosos del hogar","Describir la gestión de envases de fitosanitarios y residuos patogénicos","Evaluar el destino de neumáticos, aceites y aparatos electrónicos"],"repasa":["residuos-5","digital-1","digital-4","oceanos-3"],"requiere_tronco":3,"fuentes":["ley-24051-peligrosos","basilea","ley-27279-fitosanitarios","unece-sga","ewaste-monitor","minamata","msal-dengue"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-6.s1","orden":1,"tipo":"leccion","titulo_es":"Qué hace peligroso a un residuo","bajada_es":"Inflamable, corrosivo, reactivo, tóxico o infeccioso: las características del peligro y cómo reconocerlas en una etiqueta.","minutos":11,"pasos":[{"slug":"residuos-6.s1.p1","orden":1,"grupo":"residuos-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cinco características","cuerpo":["Un residuo es peligroso cuando puede dañar a las personas o al ambiente por sus características. Puede ser inflamable (se prende fuego con facilidad, como solventes o nafta), corrosivo (quema la piel o destruye materiales, como ácidos o soda cáustica), reactivo (puede explotar o liberar gases al mezclarse, como algunos productos de limpieza), tóxico (daña la salud aun en pequeñas cantidades, como el mercurio o muchos plaguicidas) o infeccioso (puede transmitir enfermedades, como algunos residuos de hospital)."],"lista":["Inflamable","Corrosivo","Reactivo","Tóxico","Infeccioso"]},"solucion":{}},{"slug":"residuos-6.s1.p2","orden":2,"grupo":"residuos-6.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada característica con un ejemplo.","izquierda":[{"id":"a1","texto":"Inflamable"},{"id":"a2","texto":"Corrosivo"},{"id":"a3","texto":"Tóxico"},{"id":"a4","texto":"Infeccioso"}],"derecha":[{"id":"b1","texto":"Restos de solvente para pintura"},{"id":"b2","texto":"Ácido de una batería de auto"},{"id":"b3","texto":"Mercurio de un termómetro roto"},{"id":"b4","texto":"Jeringas usadas de un hospital"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer la característica indica cómo guardarlo, transportarlo y tratarlo."}},{"slug":"residuos-6.s1.p3","orden":3,"grupo":"residuos-6.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los pictogramas","cuerpo":["Los productos químicos llevan pictogramas: rombos con borde rojo y un símbolo negro, definidos por un sistema internacional. Una llama indica inflamable; una mano y una superficie corroídas, corrosivo; una calavera, toxicidad aguda; una silueta humana con una estrella en el pecho, daño grave a la salud a largo plazo; un pez y un árbol secos, peligro para el ambiente acuático. Si el producto es peligroso, su envase vacío y sus restos también lo son."]},"solucion":{}},{"slug":"residuos-6.s1.p4","orden":4,"grupo":"residuos-6.s1.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pictograma con su significado.","izquierda":[{"id":"a1","texto":"Llama"},{"id":"a2","texto":"Calavera"},{"id":"a3","texto":"Mano y superficie corroídas"},{"id":"a4","texto":"Pez y árbol secos"},{"id":"a5","texto":"Silueta con estrella en el pecho"}],"derecha":[{"id":"b1","texto":"Inflamable"},{"id":"b2","texto":"Toxicidad aguda"},{"id":"b3","texto":"Corrosivo"},{"id":"b4","texto":"Peligroso para el ambiente acuático"},{"id":"b5","texto":"Daño grave a la salud a largo plazo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Los pictogramas son un idioma común: se leen igual en todo el mundo."}},{"slug":"residuos-6.s1.p5","orden":5,"grupo":"residuos-6.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un producto tiene pictogramas de peligro, su envase vacío puede tirarse con los reciclables sin más.","razones":[{"id":"r1","texto":"Porque los restos del producto siguen siendo peligrosos"},{"id":"r2","texto":"Porque los envases vacíos no existen"},{"id":"r3","texto":"Porque los pictogramas son solo decorativos"}]},"solucion":{"valor":false,"explicacion":"Los envases conservan restos del producto: siguen siendo peligrosos. Hay que seguir las indicaciones de la etiqueta y usar los circuitos adecuados.","clave":["r1"]}},{"slug":"residuos-6.s1.p6","orden":6,"grupo":"residuos-6.s1.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué característica peligrosa tiene cada residuo?","grupos":[{"id":"g1","nombre":"Inflamable"},{"id":"g2","nombre":"Corrosivo"},{"id":"g3","nombre":"Tóxico"}],"items":[{"id":"i1","texto":"Restos de thinner"},{"id":"i2","texto":"Destapacañerías a base de soda cáustica"},{"id":"i3","texto":"Lámpara fluorescente rota"},{"id":"i4","texto":"Aerosol con gas propelente"},{"id":"i5","texto":"Ácido muriático"},{"id":"i6","texto":"Insecticida vencido"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Muchos productos de uso diario son peligrosos: por eso sus restos no van a la bolsa común."}},{"slug":"residuos-6.s1.p7","orden":7,"grupo":"residuos-6.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mezclas peligrosas","cuerpo":["Algunos residuos son peligrosos sobre todo al mezclarse. Por ejemplo, la lavandina mezclada con productos que contienen amoníaco o con ácidos, como el ácido muriático, libera gases tóxicos que dañan las vías respiratorias. Por eso nunca hay que mezclar productos de limpieza ni juntar sus restos en un mismo recipiente."]},"solucion":{}},{"slug":"residuos-6.s1.p8","orden":8,"grupo":"residuos-6.s1.p8","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué no hay que mezclar productos de limpieza.","items":[{"id":"i1","texto":"Alguien mezcla lavandina con ácido muriático para limpiar más"},{"id":"i2","texto":"Los productos reaccionan entre sí"},{"id":"i3","texto":"Se libera un gas tóxico"},{"id":"i4","texto":"Se respira en un baño cerrado"},{"id":"i5","texto":"Daña las vías respiratorias"},{"id":"i6","texto":"La mezcla neutraliza todos los peligros"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Más fuerte no es mejor: algunas mezclas son muy peligrosas."}},{"slug":"residuos-6.s1.p9","orden":9,"grupo":"residuos-6.s1.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con los restos de distintos productos de limpieza?","opciones":[{"id":"o1","texto":"No mezclarlos y guardarlos en sus envases originales"},{"id":"o2","texto":"Juntarlos en una botella para tirarlos juntos"},{"id":"o3","texto":"Mezclarlos para que se neutralicen entre sí"},{"id":"o4","texto":"Tirarlos todos juntos por la pileta de una vez"}]},"solucion":{"clave":["o1"],"explicacion":"Envase original, bien cerrado y etiquetado, sin mezclas: la regla básica de seguridad.","por_opcion":{"o3":"Algunas mezclas liberan gases tóxicos."}}},{"slug":"residuos-6.s1.p10","orden":10,"grupo":"residuos-6.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué productos del hogar suelen tener pictogramas de peligro? Marcá todos.","opciones":[{"id":"o1","texto":"Lavandina"},{"id":"o2","texto":"Insecticidas"},{"id":"o3","texto":"Solventes para pintura"},{"id":"o4","texto":"Destapacañerías"},{"id":"o5","texto":"Jabón de tocador"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Leer la etiqueta es el primer paso para usar y descartar bien un producto."}},{"slug":"residuos-6.s1.p11","orden":11,"grupo":"residuos-6.s1.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos residuos según su peligrosidad para una persona que los manipula sin protección, de mayor a menor.","items":[{"id":"i1","texto":"Jeringas usadas con restos de sangre"},{"id":"i2","texto":"Pila rota con líquido derramado"},{"id":"i3","texto":"Pila común agotada, entera"},{"id":"i4","texto":"Botella de plástico limpia"}],"extremos":["Más peligroso","Menos peligroso"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El riesgo depende de la característica y del estado del residuo: una pila entera es menos riesgosa que una rota.","valores":{"i1":"infeccioso y cortante","i2":"corrosivo y tóxico","i3":"bajo riesgo inmediato","i4":"sin peligro"}}},{"slug":"residuos-6.s1.p12","orden":12,"grupo":"residuos-6.s1.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué una pila rota es más riesgosa que una entera?","opciones":[{"id":"o1","texto":"Puede liberar sustancias corrosivas o tóxicas"},{"id":"o2","texto":"Porque pesa más que una pila entera"},{"id":"o3","texto":"Porque deja de tener carga eléctrica"},{"id":"o4","texto":"Porque se vuelve inflamable al instante"}]},"solucion":{"clave":["o1"],"explicacion":"El estado del residuo cambia su riesgo: por eso se guardan enteras y en recipientes cerrados.","por_opcion":{"o3":"La carga no es el problema: lo es lo que se derrama."}}},{"slug":"residuos-6.s1.p13","orden":13,"grupo":"residuos-6.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cartel de un depósito y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El pictograma de la llama indica material inflamable."},{"id":"s2","texto":"Guardamos juntos lavandina y ácido muriático para ahorrar espacio."},{"id":"s3","texto":"La calavera indica toxicidad aguda."},{"id":"s4","texto":"Los envases vacíos de productos corrosivos no tienen ningún riesgo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La seguridad empieza por leer y respetar las etiquetas.","por_opcion":{"s2":"Mezclados pueden liberar gases tóxicos: se guardan separados.","s4":"Conservan restos del producto."}}},{"slug":"residuos-6.s1.p14","orden":14,"grupo":"residuos-6.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un residuo que se prende fuego con facilidad es {{0}}; uno que quema la piel o destruye materiales es {{1}}; y la lavandina nunca se mezcla con {{2}}.","banco":[{"id":"w1","texto":"inflamable"},{"id":"w2","texto":"corrosivo"},{"id":"w3","texto":"ácidos"},{"id":"w4","texto":"reciclable"},{"id":"w5","texto":"orgánico"},{"id":"w6","texto":"agua"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para reconocer residuos peligrosos."}}]},{"slug":"residuos-6.s2","orden":2,"tipo":"leccion","titulo_es":"La cadena de custodia","bajada_es":"Generador, transportista y operador: la Ley 24.051, el manifiesto y el Convenio de Basilea.","minutos":11,"pasos":[{"slug":"residuos-6.s2.p1","orden":1,"grupo":"residuos-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De la cuna a la tumba","cuerpo":["En Argentina, la Ley 24.051, de 1991, regula los residuos peligrosos. Su idea central es la responsabilidad \"de la cuna a la tumba\": quien genera un residuo peligroso es responsable de él hasta su tratamiento o disposición final. Intervienen tres actores inscriptos en un registro: el generador, que lo produce; el transportista, habilitado para llevarlo; y el operador, que lo trata o lo dispone en instalaciones autorizadas."]},"solucion":{}},{"slug":"residuos-6.s2.p2","orden":2,"grupo":"residuos-6.s2.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada actor con su rol.","izquierda":[{"id":"a1","texto":"Generador"},{"id":"a2","texto":"Transportista"},{"id":"a3","texto":"Operador"},{"id":"a4","texto":"Autoridad de aplicación"}],"derecha":[{"id":"b1","texto":"Produce el residuo peligroso"},{"id":"b2","texto":"Lo lleva en vehículos habilitados"},{"id":"b3","texto":"Lo trata o lo dispone en instalaciones autorizadas"},{"id":"b4","texto":"Registra y controla a todos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada eslabón tiene obligaciones y responsabilidades."}},{"slug":"residuos-6.s2.p3","orden":3,"grupo":"residuos-6.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El manifiesto","cuerpo":["Cada vez que un residuo peligroso se mueve, lo acompaña un documento llamado manifiesto. Indica qué residuo es, cuánto, quién lo genera, quién lo transporta y a dónde va. Lo firman el generador, el transportista y el operador. Así se puede seguir el recorrido del residuo y detectar si \"desaparece\" en el camino."]},"solucion":{}},{"slug":"residuos-6.s2.p4","orden":4,"grupo":"residuos-6.s2.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido de un residuo peligroso con su manifiesto.","items":[{"id":"i1","texto":"El generador completa el manifiesto"},{"id":"i2","texto":"El transportista retira el residuo y firma"},{"id":"i3","texto":"El residuo llega a la planta del operador"},{"id":"i4","texto":"El operador firma la recepción y lo trata"},{"id":"i5","texto":"Se cierra el circuito con el manifiesto completo"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El manifiesto permite comprobar que cada kilo llegó a destino."}},{"slug":"residuos-6.s2.p5","orden":5,"grupo":"residuos-6.s2.p5","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Para qué sirve el manifiesto?","opciones":[{"id":"o1","texto":"Para seguir el residuo desde que sale hasta que se trata"},{"id":"o2","texto":"Para cobrar un impuesto por cada camión"},{"id":"o3","texto":"Para que el residuo pueda tirarse en cualquier lugar"},{"id":"o4","texto":"Para publicitar a la empresa generadora"}]},"solucion":{"clave":["o1"],"explicacion":"Sin trazabilidad, un residuo peligroso puede terminar en un basural o un arroyo sin que nadie lo sepa.","por_opcion":{"o3":"Es al revés: sirve para controlar que llegue a un lugar autorizado."}}},{"slug":"residuos-6.s2.p6","orden":6,"grupo":"residuos-6.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una empresa entrega sus residuos peligrosos a un transportista, deja de ser responsable de ellos.","razones":[{"id":"r1","texto":"Por el principio de responsabilidad de la cuna a la tumba"},{"id":"r2","texto":"Porque la ley no se aplica a las empresas"},{"id":"r3","texto":"Porque el transportista es el dueño del residuo"}]},"solucion":{"valor":false,"explicacion":"Por el principio de la cuna a la tumba, el generador sigue siendo responsable hasta su tratamiento o disposición final. Por eso debe elegir actores habilitados.","clave":["r1"]}},{"slug":"residuos-6.s2.p7","orden":7,"grupo":"residuos-6.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Convenio de Basilea","cuerpo":["A nivel internacional, el Convenio de Basilea, de 1989, controla los movimientos de residuos peligrosos entre países. Nació para frenar la práctica de enviar residuos tóxicos de países ricos a países con menos controles. Exige, entre otras cosas, que el país que recibe dé su consentimiento previo e informado, y promueve que cada país gestione sus residuos lo más cerca posible de donde se generan."]},"solucion":{}},{"slug":"residuos-6.s2.p8","orden":8,"grupo":"residuos-6.s2.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué nació el Convenio de Basilea.","items":[{"id":"i1","texto":"Tratar residuos peligrosos es caro en los países con controles estrictos"},{"id":"i2","texto":"Algunas empresas los enviaban a países con menos controles"},{"id":"i3","texto":"Los residuos contaminaban comunidades con menos recursos"},{"id":"i4","texto":"Se acordó un convenio internacional"},{"id":"i5","texto":"Los envíos requieren consentimiento previo del país receptor"},{"id":"i6","texto":"Los países ricos dejaron de generar residuos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Basilea es también una herramienta de justicia ambiental entre países."}},{"slug":"residuos-6.s2.p9","orden":9,"grupo":"residuos-6.s2.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica cumple o incumple el espíritu de Basilea?","grupos":[{"id":"g1","nombre":"Cumple"},{"id":"g2","nombre":"Incumple"}],"items":[{"id":"i1","texto":"Tratar los residuos cerca de donde se generan"},{"id":"i2","texto":"Enviar residuos tóxicos declarados como \"materiales para reciclar\" falsos"},{"id":"i3","texto":"Pedir consentimiento previo al país que recibe"},{"id":"i4","texto":"Exportar residuos a un país sin informarle qué son"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"La transparencia y el consentimiento son el corazón del convenio."}},{"slug":"residuos-6.s2.p10","orden":10,"grupo":"residuos-6.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un taller genera 300 kg de residuos peligrosos por mes. ¿Cuántos kg genera en 12 meses, que deberán figurar en sus manifiestos?","unidad":"kg","decimales":0,"contexto":"300 kg por mes durante 12 meses."},"solucion":{"valor":3600,"tolerancia":72,"explicacion":"300 × 12 = 3.600 kg. Comparar lo generado con lo que figura en los manifiestos permite detectar desvíos."}},{"slug":"residuos-6.s2.p10.v2","orden":10,"grupo":"residuos-6.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un taller genera 150 kg de residuos peligrosos por mes. ¿Cuántos kg genera en 6 meses, que deberán figurar en sus manifiestos?","unidad":"kg","decimales":0,"contexto":"150 kg por mes durante 6 meses."},"solucion":{"valor":900,"tolerancia":18,"explicacion":"150 × 6 = 900 kg. Comparar lo generado con lo que figura en los manifiestos permite detectar desvíos."}},{"slug":"residuos-6.s2.p10.v3","orden":10,"grupo":"residuos-6.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un taller genera 500 kg de residuos peligrosos por mes. ¿Cuántos kg genera en 12 meses, que deberán figurar en sus manifiestos?","unidad":"kg","decimales":0,"contexto":"500 kg por mes durante 12 meses."},"solucion":{"valor":6000,"tolerancia":120,"explicacion":"500 × 12 = 6.000 kg. Comparar lo generado con lo que figura en los manifiestos permite detectar desvíos."}},{"slug":"residuos-6.s2.p11","orden":11,"grupo":"residuos-6.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué obligaciones tiene un generador de residuos peligrosos? Marcá todas.","opciones":[{"id":"o1","texto":"Inscribirse en el registro correspondiente"},{"id":"o2","texto":"Entregar sus residuos solo a transportistas habilitados"},{"id":"o3","texto":"Completar los manifiestos"},{"id":"o4","texto":"Almacenarlos de forma segura hasta su retiro"},{"id":"o5","texto":"Tirarlos en el contenedor de basura común"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La ley busca que ningún residuo peligroso quede fuera del circuito controlado."}},{"slug":"residuos-6.s2.p12","orden":12,"grupo":"residuos-6.s2.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año se firmó el Convenio de Basilea sobre residuos peligrosos.","min":1950,"max":2025,"paso":1,"unidad":"","escala":"lineal"},"solucion":{"valor":1989,"banda":"lineal","explicacion":"En 1989, tras varios escándalos por envíos de residuos tóxicos a países con menos controles."}},{"slug":"residuos-6.s2.p13","orden":13,"grupo":"residuos-6.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de una auditoría y marcá los problemas.","segmentos":[{"id":"s1","texto":"El taller está inscripto como generador."},{"id":"s2","texto":"El año pasado generó 3.600 kg, pero los manifiestos suman 900 kg."},{"id":"s3","texto":"El transportista tiene habilitación vigente."},{"id":"s4","texto":"El taller guarda los residuos al aire libre, sin techo ni contención."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los manifiestos permiten detectar el residuo que \"desaparece\".","por_opcion":{"s2":"Faltan 2.700 kg: hay que averiguar a dónde fueron.","s4":"El almacenamiento debe ser seguro para evitar derrames."}}},{"slug":"residuos-6.s2.p14","orden":14,"grupo":"residuos-6.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La ley argentina de residuos peligrosos es la Ley {{0}}; el documento que acompaña al residuo es el {{1}}; y el convenio internacional que controla sus movimientos es el de {{2}}.","banco":[{"id":"w1","texto":"24.051"},{"id":"w2","texto":"manifiesto"},{"id":"w3","texto":"Basilea"},{"id":"w4","texto":"25.916"},{"id":"w5","texto":"recibo"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la cadena de custodia de los residuos peligrosos."}}]},{"slug":"residuos-6.s3","orden":3,"tipo":"leccion","titulo_es":"Peligrosos del hogar","bajada_es":"Pilas, lámparas, medicamentos, aerosoles, pinturas y aceites: pequeñas cantidades que suman mucho.","minutos":11,"pasos":[{"slug":"residuos-6.s3.p1","orden":1,"grupo":"residuos-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"En cada casa","cuerpo":["En cada casa se generan residuos peligrosos en pequeñas cantidades: pilas y baterías, lámparas de bajo consumo y tubos fluorescentes (que contienen mercurio), termómetros de mercurio, medicamentos vencidos, aerosoles, restos de pinturas y solventes, insecticidas y aceite de motor. Sumados en toda una ciudad, son toneladas. Mezclados con la basura común, pueden contaminar el compost, el suelo, el agua o lastimar a quienes recolectan."]},"solucion":{}},{"slug":"residuos-6.s3.p2","orden":2,"grupo":"residuos-6.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este residuo del hogar es peligroso o no?","grupos":[{"id":"g1","nombre":"Peligroso"},{"id":"g2","nombre":"No peligroso"}],"items":[{"id":"i1","texto":"Pilas usadas"},{"id":"i2","texto":"Cáscaras de papa"},{"id":"i3","texto":"Tubo fluorescente"},{"id":"i4","texto":"Diario viejo"},{"id":"i5","texto":"Restos de solvente"},{"id":"i6","texto":"Botella de agua vacía"},{"id":"i7","texto":"Medicamentos vencidos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1"},"explicacion":"Los peligrosos del hogar necesitan circuitos especiales, distintos de los reciclables y los orgánicos."}},{"slug":"residuos-6.s3.p3","orden":3,"grupo":"residuos-6.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué hacer con cada uno","cuerpo":["Las pilas y baterías se llevan a puntos de recolección. Las lámparas con mercurio, sin romper, también. Los medicamentos vencidos, a farmacias o puntos habilitados donde existan: nunca al inodoro. El aceite de motor, en un bidón cerrado, a talleres o puntos de recolección. Las pinturas y solventes, en su envase original y bien cerrados, a puntos limpios. Si una lámpara con mercurio se rompe, hay que ventilar, no usar aspiradora y juntar los restos con cuidado."]},"solucion":{}},{"slug":"residuos-6.s3.p4","orden":4,"grupo":"residuos-6.s3.p4","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada residuo con su destino correcto.","izquierda":[{"id":"a1","texto":"Pilas usadas"},{"id":"a2","texto":"Medicamentos vencidos"},{"id":"a3","texto":"Aceite de motor"},{"id":"a4","texto":"Restos de pintura"}],"derecha":[{"id":"b1","texto":"Punto de recolección de pilas"},{"id":"b2","texto":"Farmacia o punto habilitado"},{"id":"b3","texto":"Taller o punto de recolección, en bidón cerrado"},{"id":"b4","texto":"Punto limpio, en su envase original"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada residuo peligroso tiene su circuito: conocerlo evita que termine en el agua o el suelo."}},{"slug":"residuos-6.s3.p5","orden":5,"grupo":"residuos-6.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Se rompe una lámpara de bajo consumo en tu cuarto. ¿Qué conviene hacer?","opciones":[{"id":"o1","texto":"Ventilar y juntar con cuidado, sin aspiradora"},{"id":"o2","texto":"Pasar la aspiradora enseguida para limpiar todo"},{"id":"o3","texto":"Tirar los restos al inodoro"},{"id":"o4","texto":"Cerrar la ventana para que no entre aire"}]},"solucion":{"clave":["o1"],"explicacion":"Estas lámparas contienen pequeñas cantidades de mercurio: ventilar y evitar dispersar el polvo es la clave.","por_opcion":{"o3":"Contamina el agua con mercurio."}}},{"slug":"residuos-6.s3.p6","orden":6,"grupo":"residuos-6.s3.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Tirar medicamentos vencidos al inodoro es una forma segura de descartarlos.","razones":[{"id":"r1","texto":"Porque terminan en el agua y afectan a la fauna"},{"id":"r2","texto":"Porque las plantas de tratamiento los eliminan por completo"},{"id":"r3","texto":"Porque los medicamentos no tienen efectos fuera del cuerpo"}]},"solucion":{"valor":false,"explicacion":"Los medicamentos pueden llegar a ríos y arroyos, donde afectan a peces y otros organismos. Conviene llevarlos a farmacias o puntos habilitados.","clave":["r1"]}},{"slug":"residuos-6.s3.p7","orden":7,"grupo":"residuos-6.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad hay 20.000 hogares y cada uno descarta en promedio 15 pilas por año. ¿Cuántas pilas por año se descartan en total?","unidad":"pilas","decimales":0,"contexto":"20000 hogares; 15 pilas por hogar por año."},"solucion":{"valor":300000,"tolerancia":6000,"explicacion":"20.000 × 15 = 300.000 pilas por año. Pequeñas cantidades por hogar suman volúmenes que justifican un circuito especial. Datos de ejemplo."}},{"slug":"residuos-6.s3.p7.v2","orden":7,"grupo":"residuos-6.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad hay 50.000 hogares y cada uno descarta en promedio 12 pilas por año. ¿Cuántas pilas por año se descartan en total?","unidad":"pilas","decimales":0,"contexto":"50000 hogares; 12 pilas por hogar por año."},"solucion":{"valor":600000,"tolerancia":12000,"explicacion":"50.000 × 12 = 600.000 pilas por año. Pequeñas cantidades por hogar suman volúmenes que justifican un circuito especial. Datos de ejemplo."}},{"slug":"residuos-6.s3.p7.v3","orden":7,"grupo":"residuos-6.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad hay 8.000 hogares y cada uno descarta en promedio 20 pilas por año. ¿Cuántas pilas por año se descartan en total?","unidad":"pilas","decimales":0,"contexto":"8000 hogares; 20 pilas por hogar por año."},"solucion":{"valor":160000,"tolerancia":3200,"explicacion":"8.000 × 20 = 160.000 pilas por año. Pequeñas cantidades por hogar suman volúmenes que justifican un circuito especial. Datos de ejemplo."}},{"slug":"residuos-6.s3.p8","orden":8,"grupo":"residuos-6.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El aceite de cocina","cuerpo":["El aceite de cocina usado no es tóxico como el de motor, pero es un problema: tirado por la pileta, tapa cañerías, dificulta el tratamiento de las cloacas y, si llega al agua, forma una película que impide el intercambio de oxígeno. Juntado en una botella cerrada y llevado a un punto de recolección, puede transformarse en biodiésel o en otros productos."]},"solucion":{}},{"slug":"residuos-6.s3.p9","orden":9,"grupo":"residuos-6.s3.p9","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino correcto del aceite de cocina usado.","items":[{"id":"i1","texto":"Se deja enfriar el aceite después de cocinar"},{"id":"i2","texto":"Se guarda en una botella de plástico cerrada"},{"id":"i3","texto":"Se lleva a un punto de recolección"},{"id":"i4","texto":"Una planta lo procesa"},{"id":"i5","texto":"Se convierte en biodiésel u otros productos"},{"id":"i6","texto":"Se tira por la pileta con agua caliente para que no tape"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un residuo que tapa cañerías se convierte en recurso si se junta aparte."}},{"slug":"residuos-6.s3.p10","orden":10,"grupo":"residuos-6.s3.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hacer con los peligrosos del hogar hasta llevarlos a un punto de recolección? Marcá todo.","opciones":[{"id":"o1","texto":"Guardarlos en su envase original y bien cerrado"},{"id":"o2","texto":"Mantenerlos fuera del alcance de chicos y mascotas"},{"id":"o3","texto":"No mezclar productos distintos"},{"id":"o4","texto":"Juntarlos todos en un balde abierto"},{"id":"o5","texto":"Pasarlos a botellas de gaseosa sin etiqueta"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Un envase sin etiqueta o una botella de gaseosa con un tóxico es una causa frecuente de intoxicaciones."}},{"slug":"residuos-6.s3.p11","orden":11,"grupo":"residuos-6.s3.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El aceite de cocina usado, tirado por la pileta, puede tapar cañerías y dificultar el tratamiento de las cloacas.","razones":[{"id":"r1","texto":"Porque se solidifica y forma tapones en las cañerías"},{"id":"r2","texto":"Porque el aceite se disuelve por completo en el agua"},{"id":"r3","texto":"Porque las cloacas no reciben aceite"}]},"solucion":{"valor":true,"explicacion":"Al enfriarse se pega a las cañerías y forma tapones; en las plantas y en el agua, complica el tratamiento y forma películas.","clave":["r1"]}},{"slug":"residuos-6.s3.p12","orden":12,"grupo":"residuos-6.s3.p12","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos destinos para una pila usada, del mejor al peor.","items":[{"id":"i1","texto":"Punto de recolección de pilas"},{"id":"i2","texto":"Guardarla en un frasco cerrado hasta encontrar un punto"},{"id":"i3","texto":"Bolsa de basura común"},{"id":"i4","texto":"Tirarla en un arroyo o en la tierra"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Mientras no haya un punto cerca, guardarla bien es mejor que mezclarla con la basura.","valores":{"i1":"el mejor","i2":"aceptable","i3":"malo","i4":"el peor"}}},{"slug":"residuos-6.s3.p13","orden":13,"grupo":"residuos-6.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un grupo vecinal y marcá los errores.","segmentos":[{"id":"s1","texto":"Llevamos las pilas al punto de recolección de la municipalidad."},{"id":"s2","texto":"Pasamos los restos de insecticida a una botella de gaseosa para ahorrar lugar."},{"id":"s3","texto":"El aceite de cocina se junta en botellas cerradas."},{"id":"s4","texto":"Si se rompe una lámpara de bajo consumo, usamos la aspiradora."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Pequeños errores con residuos peligrosos pueden tener consecuencias graves.","por_opcion":{"s2":"Puede confundirse con una bebida: se guarda en el envase original.","s4":"Dispersa el polvo con mercurio: hay que ventilar y juntar con cuidado."}}},{"slug":"residuos-6.s3.p14","orden":14,"grupo":"residuos-6.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las lámparas de bajo consumo contienen {{0}}; los medicamentos vencidos no se tiran al {{1}}; y el aceite de cocina usado puede convertirse en {{2}}.","banco":[{"id":"w1","texto":"mercurio"},{"id":"w2","texto":"inodoro"},{"id":"w3","texto":"biodiésel"},{"id":"w4","texto":"plomo"},{"id":"w5","texto":"jardín"},{"id":"w6","texto":"vidrio"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para manejar los peligrosos del hogar."}}]},{"slug":"residuos-6.s4","orden":4,"tipo":"leccion","titulo_es":"Del campo, la salud y la industria","bajada_es":"Envases de agroquímicos y triple lavado, residuos patogénicos y residuos industriales.","minutos":12,"pasos":[{"slug":"residuos-6.s4.p1","orden":1,"grupo":"residuos-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Envases de fitosanitarios","cuerpo":["En el campo se usan grandes cantidades de fitosanitarios (agroquímicos) y sus envases vacíos conservan restos del producto. La Ley 27.279, de 2016, obliga a hacerles el triple lavado o lavado a presión, a guardarlos en un lugar adecuado y a entregarlos en un Centro de Almacenamiento Transitorio dentro del año de la compra. Prohíbe abandonarlos, quemarlos, enterrarlos o darlos a personas fuera del sistema, por ejemplo para usarlos como recipientes de agua."]},"solucion":{}},{"slug":"residuos-6.s4.p2","orden":2,"grupo":"residuos-6.s4.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El triple lavado","cuerpo":["El triple lavado consiste en llenar el envase vacío con agua hasta un cuarto de su capacidad, taparlo, agitarlo y volcar el agua de enjuague en el tanque de la pulverizadora, para usarla en la misma aplicación. Se repite tres veces. Después se perfora el envase para que no pueda reutilizarse y se guarda hasta llevarlo al centro de acopio."]},"solucion":{}},{"slug":"residuos-6.s4.p3","orden":3,"grupo":"residuos-6.s4.p3","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos del triple lavado de un envase de fitosanitario.","items":[{"id":"i1","texto":"Llenar el envase con agua hasta un cuarto"},{"id":"i2","texto":"Taparlo y agitarlo"},{"id":"i3","texto":"Volcar el enjuague en el tanque de la pulverizadora"},{"id":"i4","texto":"Repetir el proceso tres veces"},{"id":"i5","texto":"Perforar el envase y guardarlo para el centro de acopio"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El enjuague se aprovecha en la aplicación: no se tira al suelo ni al agua."}},{"slug":"residuos-6.s4.p4","orden":4,"grupo":"residuos-6.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué se vuelca el agua del enjuague en el tanque de la pulverizadora?","opciones":[{"id":"o1","texto":"Para usarla en la aplicación y no tirar el químico"},{"id":"o2","texto":"Para limpiar el tanque de la pulverizadora"},{"id":"o3","texto":"Para que la pulverizadora pese menos"},{"id":"o4","texto":"Porque el agua de enjuague es potable"}]},"solucion":{"clave":["o1"],"explicacion":"Así el resto del producto se usa donde corresponde y no contamina el suelo ni el agua.","por_opcion":{"o3":"No tiene relación con el peso: se trata de no contaminar."}}},{"slug":"residuos-6.s4.p5","orden":5,"grupo":"residuos-6.s4.p5","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un envase vacío de agroquímico, bien lavado, se puede usar para guardar agua de consumo.","razones":[{"id":"r1","texto":"Porque pueden conservar restos y la ley lo prohíbe"},{"id":"r2","texto":"Porque el agua disuelve el plástico"},{"id":"r3","texto":"Porque el triple lavado vuelve potable cualquier envase"}]},"solucion":{"valor":false,"explicacion":"La Ley 27.279 prohíbe entregarlos o reutilizarlos fuera del sistema: aun lavados, pueden conservar restos peligrosos. Por eso se perforan.","clave":["r1"]}},{"slug":"residuos-6.s4.p6","orden":6,"grupo":"residuos-6.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un productor usó 200 envases de 20 litros. Si en cada triple lavado usa agua hasta un cuarto del envase tres veces, ¿cuántos litros de enjuague vuelca al tanque en total?","unidad":"litros","decimales":0,"contexto":"200 envases de 20 litros; un cuarto, tres veces."},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"Por envase: 20 × 0,25 × 3 = 15 litros; × 200 = 3.000 litros. Todo ese enjuague se usa en la aplicación, no se tira."}},{"slug":"residuos-6.s4.p6.v2","orden":6,"grupo":"residuos-6.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un productor usó 500 envases de 10 litros. Si en cada triple lavado usa agua hasta un cuarto del envase tres veces, ¿cuántos litros de enjuague vuelca al tanque en total?","unidad":"litros","decimales":0,"contexto":"500 envases de 10 litros; un cuarto, tres veces."},"solucion":{"valor":3750,"tolerancia":75,"explicacion":"Por envase: 10 × 0,25 × 3 = 7.5 litros; × 500 = 3.750 litros. Todo ese enjuague se usa en la aplicación, no se tira."}},{"slug":"residuos-6.s4.p6.v3","orden":6,"grupo":"residuos-6.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un productor usó 80 envases de 20 litros. Si en cada triple lavado usa agua hasta un cuarto del envase tres veces, ¿cuántos litros de enjuague vuelca al tanque en total?","unidad":"litros","decimales":0,"contexto":"80 envases de 20 litros; un cuarto, tres veces."},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"Por envase: 20 × 0,25 × 3 = 15 litros; × 80 = 1.200 litros. Todo ese enjuague se usa en la aplicación, no se tira."}},{"slug":"residuos-6.s4.p7","orden":7,"grupo":"residuos-6.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Residuos patogénicos","cuerpo":["Hospitales, centros de salud, laboratorios y consultorios generan residuos patogénicos: materiales que pueden contener agentes infecciosos, como gasas con sangre, jeringas o cultivos. Se separan en el lugar en bolsas y recipientes especiales (los objetos cortantes, en descartadores rígidos), se transportan en vehículos habilitados y se tratan, por ejemplo, con autoclaves que los esterilizan con vapor a alta temperatura, antes de su disposición final."]},"solucion":{}},{"slug":"residuos-6.s4.p8","orden":8,"grupo":"residuos-6.s4.p8","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una jeringa usada en un centro de salud.","items":[{"id":"i1","texto":"Se descarta en un recipiente rígido para cortopunzantes"},{"id":"i2","texto":"El recipiente lleno se cierra y se guarda en un lugar seguro"},{"id":"i3","texto":"Un transportista habilitado lo retira"},{"id":"i4","texto":"Se esteriliza en una planta de tratamiento"},{"id":"i5","texto":"Se dispone de forma segura"},{"id":"i6","texto":"Se tira en la bolsa de residuos comunes del consultorio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La separación en el lugar protege a quienes limpian, recolectan y tratan los residuos."}},{"slug":"residuos-6.s4.p9","orden":9,"grupo":"residuos-6.s4.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un residuo patogénico o no?","grupos":[{"id":"g1","nombre":"Patogénico"},{"id":"g2","nombre":"No patogénico"}],"items":[{"id":"i1","texto":"Gasa con sangre de una curación"},{"id":"i2","texto":"Papel de la oficina del hospital"},{"id":"i3","texto":"Aguja usada"},{"id":"i4","texto":"Restos de comida del bar del hospital"},{"id":"i5","texto":"Cultivo de laboratorio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Separar bien evita tratar como patogénico lo que no lo es, algo caro e innecesario."}},{"slug":"residuos-6.s4.p10","orden":10,"grupo":"residuos-6.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Residuos industriales","cuerpo":["Las industrias generan residuos muy variados: barros de tratamiento de efluentes, restos de procesos químicos, aceites, solventes, metales. Los que son peligrosos siguen el circuito de la Ley 24.051. Pero lo más efectivo es prevenir: cambiar procesos para usar sustancias menos peligrosas, recuperar solventes para volver a usarlos y diseñar productos que generen menos residuos."]},"solucion":{}},{"slug":"residuos-6.s4.p11","orden":11,"grupo":"residuos-6.s4.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada residuo con su tratamiento o destino.","izquierda":[{"id":"a1","texto":"Jeringas usadas"},{"id":"a2","texto":"Envases de fitosanitarios"},{"id":"a3","texto":"Solvente industrial usado"},{"id":"a4","texto":"Barros industriales peligrosos"}],"derecha":[{"id":"b1","texto":"Esterilización en autoclave"},{"id":"b2","texto":"Centro de almacenamiento transitorio"},{"id":"b3","texto":"Recuperación para volver a usarlo"},{"id":"b4","texto":"Relleno de seguridad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada residuo peligroso tiene un tratamiento específico según su característica."}},{"slug":"residuos-6.s4.p12","orden":12,"grupo":"residuos-6.s4.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas estrategias para los residuos peligrosos de una industria, de la más preferible a la menos.","items":[{"id":"i1","texto":"Cambiar el proceso para no usar la sustancia peligrosa"},{"id":"i2","texto":"Recuperar el solvente y volver a usarlo"},{"id":"i3","texto":"Tratarlo para reducir su peligrosidad"},{"id":"i4","texto":"Disponerlo en un relleno de seguridad"}],"extremos":["Más preferible","Menos preferible"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La escalera de los residuos también vale para los peligrosos: lo mejor es que no existan.","valores":{"i1":"prevenir","i2":"reutilizar","i3":"tratar","i4":"último recurso"}}},{"slug":"residuos-6.s4.p13","orden":13,"grupo":"residuos-6.s4.p13","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué prohíbe la Ley 27.279 sobre los envases vacíos de fitosanitarios? Marcá todo.","opciones":[{"id":"o1","texto":"Abandonarlos en el campo"},{"id":"o2","texto":"Quemarlos"},{"id":"o3","texto":"Enterrarlos"},{"id":"o4","texto":"Entregarlos a personas fuera del sistema"},{"id":"o5","texto":"Llevarlos a un centro de almacenamiento transitorio"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La ley busca que todos los envases lleguen al circuito controlado."}},{"slug":"residuos-6.s4.p14","orden":14,"grupo":"residuos-6.s4.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta práctica de un campo y marcá lo que está mal.","segmentos":[{"id":"s1","texto":"Hacemos el triple lavado y volcamos el enjuague en la pulverizadora."},{"id":"s2","texto":"Quemamos los envases vacíos para no acumularlos."},{"id":"s3","texto":"Perforamos los envases antes de guardarlos."},{"id":"s4","texto":"Regalamos los bidones lavados a los vecinos para guardar agua."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La gestión de envases protege la salud de las familias rurales y del agua.","por_opcion":{"s2":"La ley lo prohíbe: la quema libera sustancias tóxicas.","s4":"Está prohibido: pueden conservar restos peligrosos."}}},{"slug":"residuos-6.s4.p15","orden":15,"grupo":"residuos-6.s4.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los envases de agroquímicos se lavan con el {{0}} lavado; los residuos de salud que pueden transmitir enfermedades son {{1}}; y la ley de envases vacíos de fitosanitarios es la Ley {{2}}.","banco":[{"id":"w1","texto":"triple"},{"id":"w2","texto":"patogénicos"},{"id":"w3","texto":"27.279"},{"id":"w4","texto":"doble"},{"id":"w5","texto":"orgánicos"},{"id":"w6","texto":"24.051"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de los residuos del campo, la salud y la industria."}}]},{"slug":"residuos-6.s5","orden":5,"tipo":"leccion","titulo_es":"Neumáticos, aceites y aparatos","bajada_es":"Residuos especiales que no siempre son tóxicos, pero que tienen riesgos y mucho valor si se gestionan bien.","minutos":12,"pasos":[{"slug":"residuos-6.s5.p1","orden":1,"grupo":"residuos-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Neumáticos fuera de uso","cuerpo":["Los neumáticos fuera de uso no son tóxicos en sí mismos, pero son un problema. Acumulados al aire libre, juntan agua de lluvia y se convierten en criaderos del mosquito que transmite el dengue. Quemados, liberan humo con sustancias tóxicas. Bien gestionados, pueden recaparse para volver a usarse, triturarse para hacer caucho granulado (para pisos deportivos, asfaltos o baldosas) o usarse como combustible en hornos industriales con control de emisiones."]},"solucion":{}},{"slug":"residuos-6.s5.p2","orden":2,"grupo":"residuos-6.s5.p2","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué los neumáticos acumulados son un riesgo para la salud.","items":[{"id":"i1","texto":"Se acumulan neumáticos al aire libre"},{"id":"i2","texto":"Llueve y se junta agua en su interior"},{"id":"i3","texto":"Los mosquitos ponen huevos en esa agua"},{"id":"i4","texto":"Crece la población de mosquitos"},{"id":"i5","texto":"Aumenta el riesgo de dengue en el barrio"},{"id":"i6","texto":"El caucho repele a todos los mosquitos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un residuo que parece inofensivo puede ser un problema de salud pública."}},{"slug":"residuos-6.s5.p3","orden":3,"grupo":"residuos-6.s5.p3","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada destino del neumático con su resultado.","izquierda":[{"id":"a1","texto":"Recapado"},{"id":"a2","texto":"Trituración"},{"id":"a3","texto":"Uso en hornos con control"},{"id":"a4","texto":"Quema a cielo abierto"}],"derecha":[{"id":"b1","texto":"Vuelve a usarse como neumático"},{"id":"b2","texto":"Caucho granulado para pisos y asfaltos"},{"id":"b3","texto":"Recuperación de energía"},{"id":"b4","texto":"Humo tóxico y contaminación"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El mismo residuo puede ser un recurso o una fuente de contaminación."}},{"slug":"residuos-6.s5.p4","orden":4,"grupo":"residuos-6.s5.p4","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un terreno baldío hay cientos de neumáticos viejos. ¿Qué conviene hacer primero?","opciones":[{"id":"o1","texto":"Retirarlos a un circuito de reciclaje"},{"id":"o2","texto":"Quemarlos para que desaparezcan rápido"},{"id":"o3","texto":"Dejarlos, porque no son tóxicos"},{"id":"o4","texto":"Taparlos con tierra en el mismo lugar"}]},"solucion":{"clave":["o1"],"explicacion":"Retirarlos elimina criaderos de mosquitos y permite recuperarlos.","por_opcion":{"o3":"Acumulan agua y crían mosquitos del dengue."}}},{"slug":"residuos-6.s5.p5","orden":5,"grupo":"residuos-6.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aceites usados","cuerpo":["El aceite lubricante usado de autos y máquinas es un residuo peligroso: contiene metales y compuestos tóxicos. Un solo cambio de aceite tirado a la tierra o a un desagüe puede contaminar mucha agua. Recolectado, puede regenerarse (refinarse para volver a ser lubricante) o usarse como combustible con controles. Los talleres son generadores y deben entregarlo a transportistas habilitados."]},"solucion":{}},{"slug":"residuos-6.s5.p6","orden":6,"grupo":"residuos-6.s5.p6","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una práctica correcta o incorrecta con el aceite de motor usado?","grupos":[{"id":"g1","nombre":"Correcta"},{"id":"g2","nombre":"Incorrecta"}],"items":[{"id":"i1","texto":"Guardarlo en un bidón cerrado"},{"id":"i2","texto":"Tirarlo en la tierra del patio"},{"id":"i3","texto":"Entregarlo a un transportista habilitado"},{"id":"i4","texto":"Volcarlo en la rejilla de la calle"},{"id":"i5","texto":"Llevarlo a un punto de recolección"},{"id":"i6","texto":"Usarlo para \"curar\" postes de madera sin control"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El aceite de motor usado es peligroso: siempre al circuito controlado."}},{"slug":"residuos-6.s5.p7","orden":7,"grupo":"residuos-6.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aparatos eléctricos y electrónicos","cuerpo":["Lo viste en la rama digital: los aparatos eléctricos y electrónicos viejos contienen metales valiosos, como oro, cobre y cobalto, y también sustancias peligrosas, como plomo, mercurio, cadmio o retardantes de llama. Por eso son residuos especiales: hay que desarmarlos en plantas adecuadas, separar lo peligroso y recuperar lo valioso. La responsabilidad extendida del productor busca que quienes fabrican o importan los aparatos financien ese circuito."]},"solucion":{}},{"slug":"residuos-6.s5.p8","orden":8,"grupo":"residuos-6.s5.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué contiene un aparato electrónico viejo? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Metales valiosos como cobre y oro"},{"id":"o2","texto":"Sustancias peligrosas como plomo o mercurio"},{"id":"o3","texto":"Plásticos que pueden recuperarse"},{"id":"o4","texto":"Solo plástico sin ningún valor"},{"id":"o5","texto":"Nada que pueda contaminar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Valor y peligro juntos: por eso necesitan un circuito especial."}},{"slug":"residuos-6.s5.p9","orden":9,"grupo":"residuos-6.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en el mundo se generaron 62 millones de toneladas de basura electrónica y se recicló de forma documentada el 22 %, ¿cuántos millones de toneladas se reciclaron? Redondeá a un decimal.","unidad":"millones de toneladas","decimales":1,"contexto":"62 millones de toneladas; 22 % reciclado."},"solucion":{"valor":13.6,"tolerancia":0.1,"explicacion":"62 × 22 % ≈ 13,6 millones de toneladas. La mayor parte de la basura electrónica todavía no tiene un destino documentado."}},{"slug":"residuos-6.s5.p9.v2","orden":9,"grupo":"residuos-6.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 62 millones de toneladas de aparatos descartados, el 22 % se recicló de forma documentada. ¿Cuántos millones de toneladas son? Redondeá a un decimal.","unidad":"millones de toneladas","decimales":1,"contexto":"62 millones de toneladas; 22 % reciclado."},"solucion":{"valor":13.6,"tolerancia":0.1,"explicacion":"62 × 22 % ≈ 13,6 millones de toneladas. La mayor parte de la basura electrónica todavía no tiene un destino documentado."}},{"slug":"residuos-6.s5.p9.v3","orden":9,"grupo":"residuos-6.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos millones de toneladas de basura electrónica se reciclaron de forma documentada, si fueron el 22 % de 62 millones? Redondeá a un decimal.","unidad":"millones de toneladas","decimales":1,"contexto":"62 millones de toneladas; 22 % reciclado."},"solucion":{"valor":13.6,"tolerancia":0.1,"explicacion":"62 × 22 % ≈ 13,6 millones de toneladas. La mayor parte de la basura electrónica todavía no tiene un destino documentado."}},{"slug":"residuos-6.s5.p10","orden":10,"grupo":"residuos-6.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada neumático de auto pesa unos 8 kg y alrededor del 70 % es caucho recuperable, ¿cuántos kilos de caucho se pueden recuperar de 600 neumáticos?","unidad":"kg","decimales":0,"contexto":"600 neumáticos; 8 kg cada uno; 70 % de caucho."},"solucion":{"valor":3360,"tolerancia":1,"explicacion":"600 × 8 × 70 % = 3.360 kg de caucho, que puede convertirse en pisos, baldosas o asfalto. Valores aproximados de ejemplo."}},{"slug":"residuos-6.s5.p10.v2","orden":10,"grupo":"residuos-6.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada neumático de auto pesa unos 8 kg y alrededor del 70 % es caucho recuperable, ¿cuántos kilos de caucho se pueden recuperar de 1000 neumáticos?","unidad":"kg","decimales":0,"contexto":"1000 neumáticos; 8 kg cada uno; 70 % de caucho."},"solucion":{"valor":5600,"tolerancia":1,"explicacion":"1000 × 8 × 70 % = 5.600 kg de caucho, que puede convertirse en pisos, baldosas o asfalto. Valores aproximados de ejemplo."}},{"slug":"residuos-6.s5.p10.v3","orden":10,"grupo":"residuos-6.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada neumático de auto pesa unos 9 kg y alrededor del 65 % es caucho recuperable, ¿cuántos kilos de caucho se pueden recuperar de 400 neumáticos?","unidad":"kg","decimales":0,"contexto":"400 neumáticos; 9 kg cada uno; 65 % de caucho."},"solucion":{"valor":2340,"tolerancia":1,"explicacion":"400 × 9 × 65 % = 2.340 kg de caucho, que puede convertirse en pisos, baldosas o asfalto. Valores aproximados de ejemplo."}},{"slug":"residuos-6.s5.p11","orden":11,"grupo":"residuos-6.s5.p11","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Responsabilidad extendida del productor","cuerpo":["En muchos países, los residuos especiales como neumáticos, aceites, pilas y aparatos tienen sistemas de responsabilidad extendida del productor: quienes los ponen en el mercado deben organizar y financiar su recolección y tratamiento, a veces con un cargo incluido en el precio. Así, el costo de gestionar el residuo queda en el producto y no en los municipios ni en el ambiente."]},"solucion":{}},{"slug":"residuos-6.s5.p12","orden":12,"grupo":"residuos-6.s5.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con la responsabilidad extendida del productor, el costo de gestionar un residuo especial queda en el producto, y no en el municipio.","razones":[{"id":"r1","texto":"Porque el productor financia la gestión del residuo"},{"id":"r2","texto":"Porque los residuos especiales desaparecen solos"},{"id":"r3","texto":"Porque el municipio paga el doble"}]},"solucion":{"valor":true,"explicacion":"El productor organiza y financia la recolección y el tratamiento. Además, tiene incentivos para diseñar productos más fáciles de recuperar.","clave":["r1"]}},{"slug":"residuos-6.s5.p13","orden":13,"grupo":"residuos-6.s5.p13","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para un celular viejo que todavía funciona, de la mejor a la peor.","items":[{"id":"i1","texto":"Seguir usándolo o dárselo a alguien que lo use"},{"id":"i2","texto":"Entregarlo para reacondicionar"},{"id":"i3","texto":"Llevarlo a un punto de reciclaje de electrónicos"},{"id":"i4","texto":"Tirarlo con la basura común"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero alargar la vida; el reciclaje, al final; la basura común, nunca.","valores":{"i1":"la mejor","i2":"muy buena","i3":"buena","i4":"la peor"}}},{"slug":"residuos-6.s5.p14","orden":14,"grupo":"residuos-6.s5.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este volante municipal y marcá los errores.","segmentos":[{"id":"s1","texto":"Los neumáticos viejos pueden convertirse en caucho granulado."},{"id":"s2","texto":"Quemar neumáticos es una buena forma de eliminarlos."},{"id":"s3","texto":"Los aparatos electrónicos tienen metales valiosos y sustancias peligrosas."},{"id":"s4","texto":"El aceite de motor usado puede tirarse en la rejilla si se diluye."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los residuos especiales tienen soluciones: el problema es que lleguen a ellas.","por_opcion":{"s2":"Libera humo con sustancias tóxicas.","s4":"Contamina igual: debe ir a un circuito controlado."}}},{"slug":"residuos-6.s5.p15","orden":15,"grupo":"residuos-6.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los neumáticos acumulados crían mosquitos del {{0}}; el aceite de motor usado puede {{1}} para volver a ser lubricante; y que el fabricante financie la gestión del residuo es responsabilidad {{2}}.","banco":[{"id":"w1","texto":"dengue"},{"id":"w2","texto":"regenerarse"},{"id":"w3","texto":"extendida"},{"id":"w4","texto":"resfrío"},{"id":"w5","texto":"evaporarse"},{"id":"w6","texto":"limitada"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre los residuos especiales con valor."}}]},{"slug":"residuos-6.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: residuos peligrosos y especiales","bajada_es":"Características, cadena de custodia, peligrosos del hogar, campo, salud, industria y residuos especiales, mezclados.","minutos":8,"pasos":[{"slug":"residuos-6.s6.p1","orden":1,"grupo":"residuos-6.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Residuos peligrosos y especiales». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-6.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el punto limpio del barrio","bajada_es":"Un municipio quiere abrir un punto limpio para los residuos peligrosos y especiales de los hogares. Diseñalo con los datos.","minutos":10,"pasos":[{"slug":"residuos-6.s7.p1","orden":1,"grupo":"residuos-6.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["La ciudad tiene 30.000 hogares. Una encuesta estima que, por año, cada hogar descarta en promedio 12 pilas, 2 lámparas de bajo consumo, 1 litro de aceite de motor y medio litro de restos de pinturas y solventes. Hoy casi todo va a la basura común. Hay una gomería con 600 neumáticos acumulados al aire libre y una cooperativa de reciclaje interesada en recibir aparatos electrónicos."]},"solucion":{}},{"slug":"residuos-6.s7.p2","orden":2,"grupo":"residuos-6.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas pilas por año descartan en total los hogares de la ciudad?","unidad":"pilas","decimales":0,"contexto":"30.000 hogares; 12 pilas por hogar por año."},"solucion":{"valor":360000,"tolerancia":7200,"explicacion":"30.000 × 12 = 360.000 pilas por año. Un volumen que justifica un circuito especial."}},{"slug":"residuos-6.s7.p3","orden":3,"grupo":"residuos-6.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de aceite de motor usado descartan por año los hogares?","unidad":"litros","decimales":0,"contexto":"30.000 hogares; 1 litro por hogar por año."},"solucion":{"valor":30000,"tolerancia":600,"explicacion":"30.000 × 1 litro = 30.000 litros por año, que hoy terminan en la tierra, los desagües o la basura."}},{"slug":"residuos-6.s7.p4","orden":4,"grupo":"residuos-6.s7.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería tener el punto limpio? Marcá todo.","opciones":[{"id":"o1","texto":"Recipientes separados para cada tipo de residuo"},{"id":"o2","texto":"Techo, piso impermeable y contención de derrames"},{"id":"o3","texto":"Personal capacitado"},{"id":"o4","texto":"Convenios con operadores habilitados para cada residuo"},{"id":"o5","texto":"Un solo contenedor para mezclar todo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un punto limpio mal diseñado puede convertirse en un foco de contaminación."}},{"slug":"residuos-6.s7.p5","orden":5,"grupo":"residuos-6.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer primero con los 600 neumáticos acumulados de la gomería?","opciones":[{"id":"o1","texto":"Retirarlos a un circuito de reciclaje antes de las lluvias"},{"id":"o2","texto":"Quemarlos en el mismo terreno para ahorrar el traslado"},{"id":"o3","texto":"Esperar a que la gomería cierre"},{"id":"o4","texto":"Cubrirlos con una lona sin retirarlos"}]},"solucion":{"clave":["o1"],"explicacion":"Retirarlos antes de la temporada de lluvias elimina criaderos de mosquitos.","por_opcion":{"o3":"Mientras tanto siguen criando mosquitos."}}},{"slug":"residuos-6.s7.p6","orden":6,"grupo":"residuos-6.s7.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué circuito va cada residuo que llega al punto limpio?","grupos":[{"id":"g1","nombre":"Operador de residuos peligrosos"},{"id":"g2","nombre":"Regeneración o recolección de aceites"},{"id":"g3","nombre":"Cooperativa de reciclaje de electrónicos"}],"items":[{"id":"i1","texto":"Pilas"},{"id":"i2","texto":"Aceite de motor usado"},{"id":"i3","texto":"Computadoras viejas"},{"id":"i4","texto":"Lámparas de bajo consumo"},{"id":"i5","texto":"Celulares descartados"},{"id":"i6","texto":"Restos de pinturas y solventes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g3","i6":"g1"},"explicacion":"Cada residuo tiene su operador: el punto limpio es el primer eslabón de la cadena."}},{"slug":"residuos-6.s7.p7","orden":7,"grupo":"residuos-6.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los hogares generan pocas cantidades, no hace falta llevar manifiestos ni trazabilidad desde el punto limpio.","razones":[{"id":"r1","texto":"Porque sumados son grandes volúmenes que deben seguir el circuito"},{"id":"r2","texto":"Porque los residuos del hogar no son peligrosos"},{"id":"r3","texto":"Porque el punto limpio los elimina en el lugar"}]},"solucion":{"valor":false,"explicacion":"Sumados, son toneladas. Desde el punto limpio, los residuos peligrosos deben seguir el circuito controlado, con transportistas y operadores habilitados.","clave":["r1"]}},{"slug":"residuos-6.s7.p8","orden":8,"grupo":"residuos-6.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el proyecto. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Habrá recipientes separados y personal capacitado."},{"id":"s2","texto":"Juntaremos pinturas, solventes y lavandina en un mismo tambor."},{"id":"s3","texto":"Firmaremos convenios con operadores habilitados."},{"id":"s4","texto":"No informaremos a los vecinos para no generar filas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un punto limpio funciona si es seguro, está bien conectado con los operadores y la gente lo conoce.","por_opcion":{"s2":"Mezclar puede provocar reacciones peligrosas: cada residuo va separado.","s4":"Sin comunicación, el punto limpio no se usa."}}}]}]}$ac$::jsonb);
